public class LanternDrift {
    public static void main(String[] args) throws InterruptedException {
        Traveler traveler = new Traveler();
        Thread worker = new Thread(new Runnable() {
            @Override
            public void run() {
                traveler.tryToSleep();
            }
        }, "LanternCounter");
        worker.start();
        Thread.sleep(1500L);
        traveler.fallAsleep();
        worker.join();
    }
}

class Traveler {
    volatile boolean asleep = false;
    private int lanterns = 0;

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    public void countSomeSheep() {
        lanterns++;
        System.out.println("Tallying lanterns: " + lanterns);
        try {
            Thread.sleep(100L);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void fallAsleep() {
        asleep = true;
        System.out.println("Traveler drifted into slumber after tallying " + lanterns + " lanterns.");
    }
}

public class LanternDrift {
    private volatile boolean asleep = false;
    private final String name;
    private int lanterns = 0;

    public LanternDrift(String name) {
        this.name = name;
    }

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
        System.out.println(name + " is now asleep.");
    }

    public void countSomeSheep() {
        lanterns++;
        System.out.println(name + " tallies a lantern (" + lanterns + ")");
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void fallAsleep() {
        asleep = true;
    }

    public static void main(String[] args) {
        final LanternDrift traveler = new LanternDrift("Traveler");

        Thread countingThread = new Thread(new Runnable() {
            @Override
            public void run() {
                traveler.tryToSleep();
            }
        }, "CountingThread");

        Thread sandmanThread = new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    Thread.sleep(800);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                traveler.fallAsleep();
            }
        }, "SandmanThread");

        countingThread.start();
        sandmanThread.start();

        try {
            countingThread.join();
            sandmanThread.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

