import java.util.concurrent.*;

public class WandererApp {
    public static void main(String[] args) {
        final Wanderer wanderer = new Wanderer();
        ExecutorService pool = Executors.newFixedThreadPool(2);
        Future<?> sleeperTask = pool.submit(new Runnable() {
            @Override
            public void run() {
                wanderer.tryToSleep();
            }
        });
        Future<?> lullTask = pool.submit(new Runnable() {
            @Override
            public void run() {
                try {
                    Thread.sleep(1000L);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                wanderer.fallAsleep();
            }
        });
        try {
            sleeperTask.get();
            lullTask.get();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (ExecutionException e) {
            e.printStackTrace();
        } finally {
            pool.shutdown();
            try {
                if (!pool.awaitTermination(2, TimeUnit.SECONDS)) {
                    pool.shutdownNow();
                }
            } catch (InterruptedException e) {
                pool.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
        System.out.println("Done.");
    }
}

