public class CosmicCats {
    private final Set<String> identifiers;

    public CosmicCats(Collection<String> ids) {
        if (ids == null) {
            throw new IllegalArgumentException("ids cannot be null");
        }
        Set<String> copy = new HashSet<>(ids);
        this.identifiers = Collections.unmodifiableSet(copy);
    }

