import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public final class StellarSprites {
    private final Set<String> tags;

    private StellarSprites(Set<String> tags) {
        Set<String> copy = new LinkedHashSet<String>();
        for (String t : tags) {
            if (t != null) {
                copy.add(t);
            }
        }
        this.tags = Collections.unmodifiableSet(copy);
    }

    public static StellarSprites defaultSprites() {
        Set<String> base = new LinkedHashSet<String>();
        base.add("Flare");
        base.add("Glint");
        base.add("Spark");
        return new StellarSprites(base);
    }

    public boolean isSprite(String tag) {
        if (tag == null) return false;
        return tags.contains(tag);
    }

    public String listTags() {
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        Iterator<String> it = tags.iterator();
        while (it.hasNext()) {
            sb.append(it.next());
            if (it.hasNext()) sb.append(", ");
        }
        sb.append("]");
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        final StellarSprites sprites = StellarSprites.defaultSprites();
        ExecutorService pool = Executors.newFixedThreadPool(2);
        try {
            Callable<String> checkTask = new Callable<String>() {
                @Override
                public String call() {
                    String[] inputs = new String[] {"Flare", "Spark", "Nova", "glint", "Glint", null};
                    StringBuilder sb = new StringBuilder();
                    for (int i = 0; i < inputs.length; i++) {
                        String s = inputs[i];
                        boolean result = sprites.isSprite(s);
                        sb.append(String.valueOf(s)).append(" -> ").append(result);
                        if (i < inputs.length - 1) sb.append(System.lineSeparator());
                    }
                    return sb.toString();
                }
            };

            Callable<String> listTask = new Callable<String>() {
                @Override
                public String call() {
                    return sprites.listTags();
                }
            };

            Future<String> f1 = pool.submit(checkTask);
            Future<String> f2 = pool.submit(listTask);

            String checks = f1.get();
            String list = f2.get();

            System.out.println("Sprite tags: " + list);
            System.out.println("Checks:");
            System.out.println(checks);
        } finally {
            pool.shutdown();
        }
    }
}

