import java.util.Collections;
import java.util.ConcurrentModificationException;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingDeviceTracker {

    // Thread-safe storage; uses delegation to ConcurrentHashMap for concurrency.
    private final ConcurrentHashMap<String, Position> devices;

    // Live, unmodifiable view backed by 'devices' (reflects ongoing changes).
    private final Map<String, Position> liveView;

    public DelegatingDeviceTracker(Map<String, Position> initialPositions) {
        Objects.requireNonNull(initialPositions, "initialPositions");
        // Defensive copy into a ConcurrentHashMap
        this.devices = new ConcurrentHashMap<>(initialPositions);
        // Unmodifiable live view (reflects changes to 'devices', but forbids direct modification)
        this.liveView = Collections.unmodifiableMap(this.devices);
    }

    // Fetch the position for a specific gadget ID; returns null if not present.
    public Position getPosition(String gadgetId) {
        Objects.requireNonNull(gadgetId, "gadgetId");
        return devices.get(gadgetId);
    }

    // Update the position only if the gadget ID already exists.
    // Returns true if the update succeeded; false otherwise.
    public boolean updatePosition(String gadgetId, Position newPosition) {
        Objects.requireNonNull(gadgetId, "gadgetId");
        Objects.requireNonNull(newPosition, "newPosition");
        // replace returns the previous value if present, otherwise null
        return devices.replace(gadgetId, newPosition) != null;
    }

    // Returns a live unmodifiable view backed by the original data.
    // Changes made via updatePosition will be visible through this view.
    public Map<String, Position> getLocationsView() {
        return liveView;
    }

    // Returns a static snapshot (unmodifiable) of the current state.
    public Map<String, Position> getLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(devices));
    }

    // Demonstration with concurrency using at most 2 additional threads (total <= 3 including main).
    public static void main(String[] args) throws InterruptedException {
        // Initialize with some devices
        Map<String, Position> initial = new HashMap<>();
        initial.put("g1", new Position(0, 0));
        initial.put("g2", new Position(5, 5));
        initial.put("g3", new Position(-3, 7));

        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initial);

        // Obtain a live view (reflects updates) and a static snapshot (does not change)
        Map<String, Position> liveView = tracker.getLocationsView();
        Map<String, Position> staticSnapshot = tracker.getLocationsSnapshot();

        System.out.println("Initial live view:     " + liveView);
        System.out.println("Initial static snapshot: " + staticSnapshot);

        // Fixed pool of 2 threads (main + 2 worker threads = 3 total)
        ExecutorService pool = Executors.newFixedThreadPool(2);

        // Updater task: tries to update an existing and a non-existing gadget repeatedly
        pool.submit(() -> {
            try {
                for (int i = 1; i <= 5; i++) {
                    // Move g1 and g2 step by step
                    boolean u1 = tracker.updatePosition("g1", new Position(i, i * 2));
                    boolean u2 = tracker.updatePosition("g2", new Position(5 + i, 5 - i));

                    // Attempt to update a non-existent gadget "ghost" (should fail)
                    boolean uGhost = tracker.updatePosition("ghost", new Position(100, 100));

                    System.out.println("[Updater] Iteration " + i + " -> g1 updated: " + u1
                            + ", g2 updated: " + u2 + ", ghost updated: " + uGhost);

                    TimeUnit.MILLISECONDS.sleep(250);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        // Reader task: shows how the live view changes while the static snapshot stays the same
        pool.submit(() -> {
            try {
                // Note that staticSnapshot was captured before any updates began
                System.out.println("[Reader] Static snapshot captured earlier: " + staticSnapshot);
                for (int i = 1; i <= 5; i++) {
                    // Live view reflects updates without re-fetching
                    System.out.println("[Reader] Live view now: " + liveView);

                    // A freshly captured snapshot at this moment
                    Map<String, Position> freshSnapshot = tracker.getLocationsSnapshot();
                    System.out.println("[Reader] Fresh snapshot: " + freshSnapshot);

                    // Fetch specific position
                    Position g1Pos = tracker.getPosition("g1");
                    System.out.println("[Reader] g1 position: " + g1Pos);

                    TimeUnit.MILLISECONDS.sleep(300);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } catch (ConcurrentModificationException e) {
                // Not expected with ConcurrentHashMap and unmodifiable wrappers
                System.err.println("[Reader] Concurrent modification detected: " + e.getMessage());
            }
        });

        pool.shutdown();
        boolean finished = pool.awaitTermination(10, TimeUnit.SECONDS);
        if (!finished) {
            System.err.println("Tasks did not finish in time.");
        }

        System.out.println("Final live view:       " + tracker.getLocationsView());
        System.out.println("Final static snapshot: " + staticSnapshot);
        System.out.println("Final fresh snapshot:  " + tracker.getLocationsSnapshot());
    }
}

