public class DelegatingDeviceTracker {

    private final ConcurrentHashMap<String, Position> locations;
    private final Map<String, Position> liveUnmodifiableView;

    public DelegatingDeviceTracker(Map<String, Position> initialPositions) {
        if (initialPositions == null) {
            throw new NullPointerException("initialPositions must not be null");
        }
        this.locations = new ConcurrentHashMap<>();
        for (Map.Entry<String, Position> e : initialPositions.entrySet()) {
            if (e.getKey() == null || e.getValue() == null) {
                throw new NullPointerException("initialPositions contains null key or value");
            }
            this.locations.put(e.getKey(), e.getValue());
        }
        this.liveUnmodifiableView = Collections.unmodifiableMap(this.locations);
    }

    // Fetch the position of a specific gadget
    public Position getLocation(String gadgetId) {
        if (gadgetId == null) {
            throw new NullPointerException("gadgetId must not be null");
        }
        return locations.get(gadgetId);
    }

    // Update the position of a gadget; succeeds only if the gadget already exists
    public boolean setLocation(String gadgetId, int x, int y) {
        if (gadgetId == null) {
            throw new NullPointerException("gadgetId must not be null");
        }
        return locations.replace(gadgetId, new Position(x, y)) != null;
    }

    // Live unmodifiable map backed by the original data (updates are visible)
    public Map<String, Position> getLocationsLiveView() {
        return liveUnmodifiableView;
    }

    // Static snapshot of current state as an unmodifiable map (not affected by future updates)
    public Map<String, Position> getLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    public static final class Position {
        private final int x;
        private final int y;

        public Position(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() { return x; }
        public int getY() { return y; }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position that = (Position) o;
            return x == that.x && y == that.y;
        }

        @Override
        public int hashCode() {
            int result = x;
            result = 31 * result + y;
            return result;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, Position> initial = new HashMap<>();
        initial.put("A", new Position(0, 0));
        initial.put("B", new Position(10, 10));
        initial.put("C", new Position(-5, 5));

        final DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initial);

        ExecutorService pool = Executors.newFixedThreadPool(2); // total threads = 2 workers + main = 3

        Runnable updater = new Runnable() {
            @Override
            public void run() {
                String[] ids = {"A", "B", "Z"}; // Z does not exist; updates should fail for Z
                Random rnd = new Random();
                for (int i = 0; i < 10; i++) {
                    String id = ids[i % ids.length];
                    int x = rnd.nextInt(51) - 25; // -25..25
                    int y = rnd.nextInt(51) - 25;
                    boolean ok = tracker.setLocation(id, x, y);
                    System.out.println("Updater: setLocation(" + id + ", " + x + ", " + y + ") -> " + ok);
                    try {
                        Thread.sleep(180);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
            }
        };

        Runnable reader = new Runnable() {
            @Override
            public void run() {
                Map<String, Position> staticSnapshot = tracker.getLocationsSnapshot(); // does not change
                for (int i = 0; i < 12; i++) {
                    Position bLive = tracker.getLocation("B");
                    Map<String, Position> liveMap = tracker.getLocationsLiveView();
                    Position bSnapshot = staticSnapshot.get("B");
                    System.out.println("Reader: B live=" + bLive + " | B snapshot=" + bSnapshot + " | live size=" + liveMap.size());
                    try {
                        Thread.sleep(120);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
            }
        };

        pool.submit(updater);
        pool.submit(reader);

        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);

        System.out.println("Final live locations: " + tracker.getLocationsLiveView());
        System.out.println("Final snapshot: " + tracker.getLocationsSnapshot());
    }
}

