import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class DelegatingDeviceTrackerDemo {

    public static void main(String[] args) throws Exception {
        // Initial gadget positions
        Map<String, Position> initial = new HashMap<>();
        initial.put("g1", new Position(0, 0));
        initial.put("g2", new Position(10, 10));
        initial.put("g3", new Position(100, 100));

        final DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initial);

        // Fixed thread pool with 2 worker threads (total threads = 3 including main)
        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable updater = new Runnable() {
            @Override
            public void run() {
                String[] ids = { "g1", "g2", "g3", "ghost" }; // "ghost" does not exist; updates must fail
                for (int i = 1; i <= 8; i++) {
                    for (String id : ids) {
                        Position newPos;
                        if ("g1".equals(id)) {
                            newPos = new Position(i, i);
                        } else if ("g2".equals(id)) {
                            newPos = new Position(10 + 2 * i, 10 + 2 * i);
                        } else if ("g3".equals(id)) {
                            newPos = new Position(100 - i, 100 - i);
                        } else {
                            newPos = new Position(999, 999);
                        }
                        boolean ok = tracker.updatePosition(id, newPos);
                        System.out.println("[Updater] Update " + id + " -> " + newPos + " : " + (ok ? "OK" : "FAILED"));
                    }
                    sleepQuietly(150);
                }
            }
        };

        Runnable reader = new Runnable() {
            @Override
            public void run() {
                for (int step = 1; step <= 8; step++) {
                    Map<String, Position> live = tracker.getLocationsView();       // live unmodifiable view
                    Map<String, Position> snap = tracker.getLocationsSnapshot();   // static unmodifiable snapshot

                    Position g1Live = live.get("g1");
                    Position g1Snap = snap.get("g1");

                    System.out.println("[Reader] step " + step
                            + " | live size=" + live.size()
                            + ", snapshot size=" + snap.size()
                            + " | g1 live=" + g1Live
                            + ", g1 snapshot=" + g1Snap);

                    // Verify immutability of returned maps (attempting modification should fail)
                    if (step == 1) {
                        try {
                            live.put("hack", new Position(0, 0));
                        } catch (UnsupportedOperationException ex) {
                            System.out.println("[Reader] Live view is unmodifiable as expected");
                        }
                        try {
                            snap.put("hack", new Position(0, 0));
                        } catch (UnsupportedOperationException ex) {
                            System.out.println("[Reader] Snapshot is unmodifiable as expected");
                        }
                    }

                    sleepQuietly(200);
                }
            }
        };

        Future<?> f1 = pool.submit(updater);
        Future<?> f2 = pool.submit(reader);

        // Wait for both tasks to complete
        f1.get();
        f2.get();

        pool.shutdown();

        // Final state
        System.out.println("\nFinal live view: " + tracker.getLocationsView());
        System.out.println("Final snapshot:  " + tracker.getLocationsSnapshot());
    }

    private static void sleepQuietly(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
        }
    }
}

class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, Position> locations;
    private final Map<String, Position> unmodifiableLiveView;

    public DelegatingDeviceTracker(Map<String, Position> initialPositions) {
        if (initialPositions == null) {
            throw new NullPointerException("initialPositions must not be null");
        }
        // Defensive copy into a concurrent map; only existing keys may be updated
        this.locations = new ConcurrentHashMap<>();
        for (Map.Entry<String, Position> e : initialPositions.entrySet()) {
            String id = e.getKey();
            Position pos = e.getValue();
            if (id == null || pos == null) {
                throw new NullPointerException("Gadget IDs and positions must not be null");
            }
            this.locations.put(id, pos);
        }
        // Live unmodifiable view delegating to the underlying concurrent map
        this.unmodifiableLiveView = Collections.unmodifiableMap(this.locations);
    }

    // Returns the current position of the gadget, or null if not tracked
    public Position getPosition(String id) {
        if (id == null) {
            throw new NullPointerException("id must not be null");
        }
        return locations.get(id);
    }

    // Update using a Position object; succeeds only if the gadget ID already exists
    public boolean updatePosition(String id, Position newPosition) {
        if (id == null || newPosition == null) {
            throw new NullPointerException("id and newPosition must not be null");
        }
        // replace returns previous value if key existed, otherwise null
        return locations.replace(id, newPosition) != null;
    }

    // Convenience overload to update using coordinates
    public boolean updatePosition(String id, int x, int y) {
        return updatePosition(id, new Position(x, y));
    }

    // Live unmodifiable view backed by the original data
    public Map<String, Position> getLocationsView() {
        return unmodifiableLiveView;
    }

    // Static snapshot of the current state as an unmodifiable map
    public Map<String, Position> getLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }
}

