import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingParcelTracker {

    private final ConcurrentHashMap<String, Position> positions;
    private final Map<String, Position> liveUnmodifiableView;

    public DelegatingParcelTracker(Map<String, Position> initialPositions) {
        Objects.requireNonNull(initialPositions, "initialPositions must not be null");
        this.positions = new ConcurrentHashMap<>(initialPositions);
        this.liveUnmodifiableView = Collections.unmodifiableMap(this.positions);
    }

    // Returns the position for a given package ID, or null if not found
    public Position getPosition(String packageId) {
        Objects.requireNonNull(packageId, "packageId must not be null");
        return positions.get(packageId);
    }

    // Assigns a new position only if the packageId already exists; returns true if updated
    public boolean assignPositionIfPresent(String packageId, Position newPosition) {
        Objects.requireNonNull(packageId, "packageId must not be null");
        Objects.requireNonNull(newPosition, "newPosition must not be null");
        return positions.replace(packageId, newPosition) != null;
    }

    // Returns a live, unmodifiable view backed by the original concurrent map
    public Map<String, Position> getAllPositionsLiveView() {
        return liveUnmodifiableView;
    }

    // Returns a static snapshot (unmodifiable) of the current positions
    public Map<String, Position> getAllPositionsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(positions));
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, Position> initial = new HashMap<>();
        initial.put("PKG-001", new Position(40.7128, -74.0060)); // NYC
        initial.put("PKG-002", new Position(34.0522, -118.2437)); // LA

        DelegatingParcelTracker tracker = new DelegatingParcelTracker(initial);

        ExecutorService pool = Executors.newFixedThreadPool(2); // main + 2 worker threads = 3 total

        // Live view shows ongoing updates; snapshot is a static view at the moment it's taken
        Map<String, Position> liveView = tracker.getAllPositionsLiveView();

        Runnable writer = () -> {
            String[] ids = { "PKG-001", "PKG-002", "PKG-XYZ" }; // PKG-XYZ does not exist
            for (int i = 0; i < 5; i++) {
                for (String id : ids) {
                    Position newPos = new Position(40.0 + i + id.hashCode() % 3, -74.0 - i - id.hashCode() % 3);
                    boolean updated = tracker.assignPositionIfPresent(id, newPos);
                    if (!updated) {
                        // Demonstrates that non-existing IDs are not added
                        System.out.println("Writer: failed to update (non-existent) " + id);
                    }
                }
                sleepQuietly(150);
            }
        };

        Runnable reader = () -> {
            for (int i = 0; i < 6; i++) {
                Map<String, Position> snapshot = tracker.getAllPositionsSnapshot();
                System.out.println("Reader (live view):   " + liveView);
                System.out.println("Reader (snapshot):    " + snapshot);
                System.out.println("---");
                sleepQuietly(200);
            }
        };

        pool.submit(writer);
        pool.submit(reader);

        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final positions (live view): " + tracker.getAllPositionsLiveView());
        System.out.println("Attempting to set new ID (should fail): " +
                tracker.assignPositionIfPresent("NEW-ID", new Position(1.0, 2.0)));
        System.out.println("Done.");
    }

    private static void sleepQuietly(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException ignored) {
            Thread.currentThread().interrupt();
        }
    }
}

