import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

public class DelegatingRobotTracker {

    private final ConcurrentMap<String, Coord> locations;
    private final Map<String, Coord> liveView;

    public DelegatingRobotTracker(Map<String, Coord> initial) {
        Objects.requireNonNull(initial, "initial map must not be null");
        // Delegate thread safety to ConcurrentHashMap
        this.locations = new ConcurrentHashMap<>(initial);
        // Live unmodifiable view backed by the original data
        this.liveView = Collections.unmodifiableMap(this.locations);
    }

    // Check the coordinates of a specific robot (null if not found)
    public Coord getLocation(String robotId) {
        return locations.get(robotId);
    }

    // Modify the coordinates only if the robot ID already exists
    public boolean setLocation(String robotId, int x, int y) {
        // replace returns previous value if key existed; null otherwise
        return locations.replace(robotId, new Coord(x, y)) != null;
    }

    // Live unmodifiable view backed by the internal map
    public Map<String, Coord> getLocationsView() {
        return liveView;
    }

    // Static snapshot of the current state as an unmodifiable map
    public Map<String, Coord> getLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    public static void main(String[] args) {
        // Initial state
        Map<String, Coord> initial = new HashMap<>();
        initial.put("R1", new Coord(0, 0));
        initial.put("R2", new Coord(5, 5));
        initial.put("R3", new Coord(10, 10));

        final DelegatingRobotTracker tracker = new DelegatingRobotTracker(initial);

        // Use at most 2 additional threads beyond the main thread
        ExecutorService pool = Executors.newFixedThreadPool(2);

        // Updater task: moves robots a few times; attempts an update on a non-existent robot
        Runnable updater = new Runnable() {
            @Override
            public void run() {
                String[] ids = {"R1", "R2", "R3"};
                for (int step = 1; step <= 5; step++) {
                    for (String id : ids) {
                        Coord current = tracker.getLocation(id);
                        if (current != null) {
                            int dx = ThreadLocalRandom.current().nextInt(-1, 2);
                            int dy = ThreadLocalRandom.current().nextInt(-1, 2);
                            tracker.setLocation(id, current.getX() + dx, current.getY() + dy);
                        }
                    }
                    try {
                        Thread.sleep(150);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
                boolean updated = tracker.setLocation("R4", 99, 99);
                System.out.println("Attempt to update non-existent R4: " + updated);
            }
        };

        // Reader task: periodically prints a snapshot and a specific robot's location
        Runnable reader = new Runnable() {
            @Override
            public void run() {
                for (int i = 1; i <= 5; i++) {
                    Map<String, Coord> snap = tracker.getLocationsSnapshot();
                    System.out.println("Snapshot " + i + ": " + snap);
                    System.out.println("R1 now at: " + tracker.getLocation("R1"));
                    try {
                        Thread.sleep(200);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
                // Demonstrate the live unmodifiable map cannot be modified by clients
                Map<String, Coord> live = tracker.getLocationsView();
                try {
                    live.put("R0", new Coord(0, 0));
                } catch (UnsupportedOperationException ex) {
                    System.out.println("Live view is unmodifiable as expected.");
                }
            }
        };

        pool.submit(updater);
        pool.submit(reader);

        pool.shutdown();
        try {
            if (!pool.awaitTermination(5, TimeUnit.SECONDS)) {
                pool.shutdownNow();
            }
        } catch (InterruptedException e) {
            pool.shutdownNow();
            Thread.currentThread().interrupt();
        }

        // Final state
        System.out.println("Final live view: " + tracker.getLocationsView());
        System.out.println("Final snapshot: " + tracker.getLocationsSnapshot());
    }
}

class Coord {
    private final int x;
    private final int y;

    public Coord(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public int getY() {
        return y;
    }

    // Value semantics
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        Coord coord = (Coord) o;

        if (x != coord.x) return false;
        return y == coord.y;
    }

    @Override
    public int hashCode() {
        int result = x;
        result = 31 * result + y;
        return result;
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ")";
    }
}

