public class RobotTrackerDemo {
    public static void main(String[] args) throws Exception {
        // Initialize tracker with initial coordinates
        Map<String, Coord> initial = new HashMap<>();
        initial.put("R-1", new Coord(0, 0));
        initial.put("R-2", new Coord(10, 10));
        initial.put("R-3", new Coord(20, 20));

        DelegatingRobotTracker tracker = new DelegatingRobotTracker(initial);

        System.out.println("Initial (live) view: " + tracker.liveLocations());
        System.out.println("Initial snapshot:    " + tracker.snapshotLocations());

        // Use exactly two worker threads (total threads including main = 3)
        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable updater = () -> {
            try {
                for (int i = 1; i <= 5; i++) {
                    boolean updated = tracker.updateLocation("R-1", i, i * 10);
                    System.out.println("Updater: R-1 -> " + tracker.getLocation("R-1") + ", success=" + updated);

                    if (i == 3) {
                        boolean nonExistent = tracker.updateLocation("R-404", 999, 999);
                        System.out.println("Updater: attempt non-existent R-404, success=" + nonExistent);
                    }

                    Thread.sleep(100);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable reader = () -> {
            try {
                for (int i = 1; i <= 5; i++) {
                    Map<String, Coord> live = tracker.liveLocations();      // live, unmodifiable view
                    Map<String, Coord> snap = tracker.snapshotLocations();  // static, unmodifiable snapshot

                    System.out.println("Reader: live R-1=" + live.get("R-1") + ", snapshot R-1=" + snap.get("R-1"));
                    Thread.sleep(120);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Future<?> f1 = pool.submit(updater);
        Future<?> f2 = pool.submit(reader);

        f1.get();
        f2.get();

        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final (live) view:   " + tracker.liveLocations());
        System.out.println("Final snapshot:      " + tracker.snapshotLocations());
    }
}

