    }

    // Modify the coordinates of a robot; succeeds only if robotId exists
    public boolean updateLocation(String robotId, int x, int y) {
        if (robotId == null) {
            throw new NullPointerException("robotId must not be null");
        }
        // replace returns previous value if present, or null if absent
        return locations.replace(robotId, new Coord(x, y)) != null;
    }

