import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingRobotTracker {

    private final ConcurrentHashMap<String, Coordinate> locations;
    private final Map<String, Coordinate> unmodifiableLiveView;

    public DelegatingRobotTracker(Map<String, Coordinate> initialLocations) {
        if (initialLocations == null) {
            throw new NullPointerException("initialLocations must not be null");
        }
        // Delegate thread safety to ConcurrentHashMap and immutability of Coordinate
        this.locations = new ConcurrentHashMap<>(initialLocations);
        this.unmodifiableLiveView = Collections.unmodifiableMap(this.locations);
    }

    // Returns the current coordinate of the robot or null if not present
    public Coordinate getLocation(String robotId) {
        if (robotId == null) return null;
        return locations.get(robotId);
    }

    // Updates the coordinate if and only if the robotId already exists.
    // Returns true on success, false if the robotId is absent.
    public boolean updateLocation(String robotId, int x, int y) {
        if (robotId == null) return false;
        return locations.replace(robotId, new Coordinate(x, y)) != null;
    }

    // Live, unmodifiable view backed by the original data.
    public Map<String, Coordinate> getLocationsLiveView() {
        return unmodifiableLiveView;
    }

    // Static snapshot of current state as an unmodifiable map.
    public Map<String, Coordinate> getLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    public static void main(String[] args) {
        Map<String, Coordinate> initial = new HashMap<>();
        initial.put("R1", new Coordinate(0, 0));
        initial.put("R2", new Coordinate(10, 10));
        initial.put("R3", new Coordinate(5, 15));

        final DelegatingRobotTracker tracker = new DelegatingRobotTracker(initial);

        // Try to update a non-existent robot (should fail)
        boolean updatedMissing = tracker.updateLocation("RX", 1, 1);
        System.out.println("Update RX (missing) -> " + updatedMissing);

        // Fixed pool with at most 2 worker threads (total threads including main <= 3)
        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable updater = new Runnable() {
            public void run() {
                for (int i = 0; i < 20; i++) {
                    boolean u1 = tracker.updateLocation("R1", i, i);
                    boolean u2 = tracker.updateLocation("R2", i * 2, i * 2);
                    if (!u1 || !u2) {
                        System.out.println("Unexpected failure updating existing robot");
                    }
                    try {
                        Thread.sleep(50);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
            }
        };

        Runnable reader = new Runnable() {
            public void run() {
                for (int i = 0; i < 10; i++) {
                    Map<String, Coordinate> live = tracker.getLocationsLiveView();
                    Map<String, Coordinate> snap = tracker.getLocationsSnapshot();

                    Coordinate r1Live = live.get("R1");
                    Coordinate r2Snap = snap.get("R2");
                    int liveSize = live.size();
                    int snapSize = snap.size();

                    System.out.println("Live size=" + liveSize + " Snapshot size=" + snapSize
                            + " R1(live)=" + r1Live + " R2(snap)=" + r2Snap);

                    try {
                        Thread.sleep(80);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }

                // Attempt to mutate the returned maps to show they are unmodifiable
                try {
                    tracker.getLocationsLiveView().put("X", new Coordinate(1, 1));
                } catch (UnsupportedOperationException e) {
                    System.out.println("Live view is unmodifiable as expected");
                }
                try {
                    tracker.getLocationsSnapshot().put("Y", new Coordinate(2, 2));
                } catch (UnsupportedOperationException e) {
                    System.out.println("Snapshot is unmodifiable as expected");
                }
            }
        };

        pool.submit(updater);
        pool.submit(reader);

        pool.shutdown();
        try {
            if (!pool.awaitTermination(5, TimeUnit.SECONDS)) {
                pool.shutdownNow();
            }
        } catch (InterruptedException e) {
            pool.shutdownNow();
            Thread.currentThread().interrupt();
        }

        System.out.println("Final live view: " + tracker.getLocationsLiveView());
        System.out.println("Final snapshot: " + tracker.getLocationsSnapshot());
    }
}

