import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public final class SolarSquirrels {
    private final List<String> squirrels;

    public SolarSquirrels() {
        List<String> list = new ArrayList<>(3);
        list.add("Nutty");
        list.add("Whisk");
        list.add("Fidget");
        this.squirrels = Collections.unmodifiableList(list);
    }

    public boolean isSquirrel(String identifier) {
        if (identifier == null) {
            return false;
        }
        for (String s : squirrels) {
            if (s.equals(identifier)) {
                return true;
            }
        }
        return false;
    }

    public String getSquirrelIdentifiers() {
        return squirrels.toString();
    }

    public static void main(String[] args) {
        final SolarSquirrels solarSquirrels = new SolarSquirrels();

        ExecutorService executor = Executors.newFixedThreadPool(2);
        Future<?> task1 = executor.submit(new Runnable() {
            public void run() {
                String[] tests = {"Nutty", "Whisk", "Fidget", "Bolt", "", null};
                StringBuilder sb = new StringBuilder();
                for (String t : tests) {
                    boolean result = solarSquirrels.isSquirrel(t);
                    sb.append("isSquirrel(")
                      .append(t == null ? "null" : "\"" + t + "\"")
                      .append(") = ")
                      .append(result)
                      .append(System.lineSeparator());
                }
                System.out.print(sb.toString());
            }
        });

        Future<?> task2 = executor.submit(new Runnable() {
            public void run() {
                String ids = solarSquirrels.getSquirrelIdentifiers();
                System.out.println("Solar Squirrels: " + ids);
            }
        });

        try {
            task1.get();
            task2.get();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public final class SolarSquirrels {
    private final List<String> identifiers;
    private final Set<String> identifierSet;

    public SolarSquirrels() {
        List<String> ids = new ArrayList<String>(3);
        ids.add("Nutty");
        ids.add("Whisk");
        ids.add("Fidget");
        this.identifiers = Collections.unmodifiableList(ids);
        this.identifierSet = Collections.unmodifiableSet(new HashSet<String>(ids));
    }

    public boolean isSquirrel(String identifier) {
        if (identifier == null) {
            return false;
        }
        return identifierSet.contains(identifier);
    }

    public String getSquirrelIdentifiers() {
        return identifiers.toString();
    }

    public static void main(String[] args) {
        final SolarSquirrels squirrels = new SolarSquirrels();
        ExecutorService pool = Executors.newFixedThreadPool(2);

        Callable<String> membershipTask = new Callable<String>() {
            public String call() {
                String[] testInputs = new String[] { "Nutty", "Comet", "Whisk", "Fidget", "Sprout", null };
                StringBuilder sb = new StringBuilder();
                for (String input : testInputs) {
                    boolean result = squirrels.isSquirrel(input);
                    sb.append(String.valueOf(input)).append(": ").append(result).append(System.lineSeparator());
                }
                return sb.toString();
            }
        };

        Callable<String> listTask = new Callable<String>() {
            public String call() {
                return squirrels.getSquirrelIdentifiers();
            }
        };

        Future<String> membershipResult = pool.submit(membershipTask);
        Future<String> listResult = pool.submit(listTask);

        try {
            System.out.print(membershipResult.get());
            System.out.println(listResult.get());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (ExecutionException e) {
            e.getCause().printStackTrace();
        } finally {
            pool.shutdown();
        }
    }
}

