import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;

public class ParcelLockerMover {

    public static void main(String[] args) throws Exception {
        Locker lockerA = new Locker("Locker-A", 100);
        Locker lockerB = new Locker("Locker-B", 50);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = new Runnable() {
            @Override
            public void run() {
                try {
                    boolean moved = move(lockerA, lockerB, 30, 2, TimeUnit.SECONDS);
                    System.out.println("Task1: Move 30 from A to B -> " + moved);
                } catch (NotEnoughItemsException e) {
                    System.out.println("Task1: " + e.getMessage());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    System.out.println("Task1: Interrupted");
                }
            }
        };

        Runnable task2 = new Runnable() {
            @Override
            public void run() {
                try {
                    boolean moved = move(lockerB, lockerA, 100, 2, TimeUnit.SECONDS);
                    System.out.println("Task2: Move 100 from B to A -> " + moved);
                } catch (NotEnoughItemsException e) {
                    System.out.println("Task2: " + e.getMessage());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    System.out.println("Task2: Interrupted");
                }
            }
        };

        executor.submit(task1);
        executor.submit(task2);

        // Give worker tasks a head start to increase contention
        Thread.sleep(5);

        try {
            boolean moved = move(lockerA, lockerB, 10, 1, TimeUnit.MILLISECONDS);
            System.out.println("Main: Move 10 from A to B -> " + moved);
        } catch (NotEnoughItemsException e) {
            System.out.println("Main: " + e.getMessage());
        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final counts:");
        System.out.println(lockerA.safeToString());
        System.out.println(lockerB.safeToString());
    }

    public static boolean move(Locker source, Locker target, int quantity, long timeout, TimeUnit unit)
            throws NotEnoughItemsException, InterruptedException {
        if (quantity <= 0) {
            return true;
        }
        long deadline = System.nanoTime() + unit.toNanos(timeout);
        long perAttemptCapNanos = TimeUnit.MILLISECONDS.toNanos(50);

        while (true) {
            long remaining = deadline - System.nanoTime();
            if (remaining <= 0L) {
                return false;
            }

            long attemptBudget = Math.min(remaining, perAttemptCapNanos);
            boolean gotSrc = false;
            boolean gotDst = false;

            try {
                gotSrc = source.lock.tryLock(attemptBudget, TimeUnit.NANOSECONDS);
                if (!gotSrc) {
                    // Backoff and retry
                } else {
                    remaining = deadline - System.nanoTime();
                    if (remaining <= 0L) {
                        return false;
                    }
                    long secondBudget = Math.min(remaining, perAttemptCapNanos);
                    gotDst = target.lock.tryLock(secondBudget, TimeUnit.NANOSECONDS);

                    if (gotDst) {
                        int available = source.parcels.get();
                        if (available < quantity) {
                            throw new NotEnoughItemsException("Not enough items in " + source.name + ": have " + available + ", need " + quantity);
                        }
                        source.parcels.add(-quantity);
                        target.parcels.add(quantity);
                        return true;
                    }
                }
            } finally {
                if (gotDst) {
                    target.lock.unlock();
                }
                if (gotSrc) {
                    source.lock.unlock();
                }
            }

            long delayNanos = fixedDelayNanos() + randomJitterNanos();
            long sleepNanos = Math.min(delayNanos, Math.max(0L, deadline - System.nanoTime()));
            if (sleepNanos > 0L) {
                TimeUnit.NANOSECONDS.sleep(sleepNanos);
            }
        }
    }

    private static long fixedDelayNanos() {
        return TimeUnit.MILLISECONDS.toNanos(3);
    }

    private static long randomJitterNanos() {
        long maxJitterMillis = 7L;
        return ThreadLocalRandom.current().nextLong(TimeUnit.MILLISECONDS.toNanos(maxJitterMillis));
    }

    static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    static class ParcelCount {
        private int count;

        ParcelCount(int initial) {
            this.count = initial;
        }

        int get() {
            return count;
        }

        void add(int delta) {
            count += delta;
        }
    }

    static class Locker {
        private final String name;
        private final ParcelCount parcels;
        private final ReentrantLock lock = new ReentrantLock();

        Locker(String name, int initialCount) {
            this.name = name;
            this.parcels = new ParcelCount(initialCount);
        }

        int safeGetCount() {
            lock.lock();
            try {
                return parcels.get();
            } finally {
                lock.unlock();
            }
        }

        String safeToString() {
            lock.lock();
            try {
                return name + " count=" + parcels.get();
            } finally {
                lock.unlock();
            }
        }
    }
}

