import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;

public class Main {

    public static void main(String[] args) throws Exception {
        Locker lockerA = new Locker("Locker-A", 100);
        Locker lockerB = new Locker("Locker-B", 50);

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Callable<Boolean> task1 = new Callable<Boolean>() {
            public Boolean call() {
                try {
                    return move(lockerA, lockerB, 60, 2, TimeUnit.SECONDS);
                } catch (NotEnoughItemsException e) {
                    System.out.println("Task1 failed: " + e.getMessage());
                    return false;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return false;
                }
            }
        };

        Callable<Boolean> task2 = new Callable<Boolean>() {
            public Boolean call() {
                try {
                    return move(lockerB, lockerA, 80, 2, TimeUnit.SECONDS);
                } catch (NotEnoughItemsException e) {
                    System.out.println("Task2 failed: " + e.getMessage());
                    return false;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return false;
                }
            }
        };

        Future<Boolean> f1 = pool.submit(task1);
        Future<Boolean> f2 = pool.submit(task2);

        Boolean r1 = f1.get();
        Boolean r2 = f2.get();

        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Task1 success: " + r1);
        System.out.println("Task2 success: " + r2);
        System.out.println(lockerA);
        System.out.println(lockerB);
    }

    public static boolean move(Locker source, Locker target, int quantity, long timeout, TimeUnit unit)
            throws InterruptedException, NotEnoughItemsException {
        if (quantity == 0 || source == target) {
            return true;
        }
        final long deadline = System.nanoTime() + unit.toNanos(timeout);
        boolean sourceLocked = false;

        try {
            while (true) {
                long remaining = deadline - System.nanoTime();
                if (remaining <= 0) {
                    return false;
                }

                long slice = Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(100));

                if (!sourceLocked) {
                    sourceLocked = source.lock.tryLock(slice, TimeUnit.NANOSECONDS);
                }

                if (sourceLocked) {
                    remaining = deadline - System.nanoTime();
                    if (remaining <= 0) {
                        return false;
                    }
                    long slice2 = Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(100));
                    if (target.lock.tryLock(slice2, TimeUnit.NANOSECONDS)) {
                        try {
                            if (source.parcels.get() < quantity) {
                                throw new NotEnoughItemsException("Not enough items in " + source.name + ": have "
                                        + source.parcels.get() + ", need " + quantity);
                            }
                            source.parcels.add(-quantity);
                            target.parcels.add(quantity);
                            return true;
                        } finally {
                            target.lock.unlock();
                        }
                    } else {
                        source.lock.unlock();
                        sourceLocked = false;
                    }
                }

                remaining = deadline - System.nanoTime();
                if (remaining <= 0) {
                    return false;
                }
                pauseBeforeRetry(remaining);
            }
        } finally {
            if (sourceLocked) {
                source.lock.unlock();
            }
        }
    }

    private static long computeFixedDelayNanos() {
        return TimeUnit.MILLISECONDS.toNanos(2);
    }

    private static long computeRandomDelayNanos() {
        return ThreadLocalRandom.current().nextLong(TimeUnit.MILLISECONDS.toNanos(8));
    }

    private static void pauseBeforeRetry(long remainingNanos) throws InterruptedException {
        long delay = Math.min(remainingNanos, computeFixedDelayNanos() + computeRandomDelayNanos());
        if (delay <= 0) {
            return;
        }
        long ms = TimeUnit.NANOSECONDS.toMillis(delay);
        int ns = (int) (delay - TimeUnit.MILLISECONDS.toNanos(ms));
        Thread.sleep(ms, ns);
    }

    static class ParcelCount {
        private final AtomicInteger count = new AtomicInteger(0);

        ParcelCount(int initial) {
            count.set(initial);
        }

        int get() {
            return count.get();
        }

        void add(int delta) {
            count.addAndGet(delta);
        }

        public String toString() {
            return String.valueOf(count.get());
        }
    }

    static class Locker {
        final String name;
        final ReentrantLock lock = new ReentrantLock();
        final ParcelCount parcels;

        Locker(String name, int initial) {
            this.name = name;
            this.parcels = new ParcelCount(initial);
        }

        public String toString() {
            return "Locker{name='" + name + "', parcels=" + parcels.get() + "}";
        }
    }

    static class NotEnoughItemsException extends Exception {
        NotEnoughItemsException(String message) {
            super(message);
        }
    }
