        }
        if (origin == target || elements == 0) {
            return true;
        }

        long timeoutNanos = unit.toNanos(timeout);
        final long deadline = System.nanoTime() + timeoutNanos;

        while (true) {
            long remaining = deadline - System.nanoTime();
            if (remaining <= 0L) {
