    public static boolean swap(Container origin, Container target, int elements, long timeout, TimeUnit unit)
            throws InsufficientElementsException, InterruptedException {
        if (origin == null || target == null) throw new IllegalArgumentException("Containers must not be null");
        if (elements <= 0) throw new IllegalArgumentException("Elements must be > 0");
        long deadline = System.nanoTime() + unit.toNanos(timeout);
        long remaining = unit.toNanos(timeout);

        while (remaining > 0L) {
            long perAttempt = Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(50));
            boolean oLocked = false;
            boolean tLocked = false;
            try {
