import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class DeadlockAvoidanceSwap {
    public static void main(String[] args) throws Exception {
        Container a = new Container("A", 100);
        Container b = new Container("B", 50);

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable task1 = new Runnable() {
            public void run() {
                for (int i = 0; i < 40; i++) {
                    try {
                        boolean ok = swap(a, b, 1, 300, TimeUnit.MILLISECONDS);
                        if (!ok) {
                            System.out.println("Task1: timeout swapping A->B");
                        }
                    } catch (InsufficientElementsException e) {
                        System.out.println("Task1: " + e.getMessage());
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
            }
        };

        Runnable task2 = new Runnable() {
            public void run() {
                for (int i = 0; i < 60; i++) {
                    try {
                        boolean ok = swap(b, a, 1, 300, TimeUnit.MILLISECONDS);
                        if (!ok) {
                            System.out.println("Task2: timeout swapping B->A");
                        }
                    } catch (InsufficientElementsException e) {
                        System.out.println("Task2: " + e.getMessage());
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
            }
        };

        pool.submit(task1);
        pool.submit(task2);

        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);

        System.out.println("Final counts: A=" + a.safeCount() + ", B=" + b.safeCount());
    }

    public static boolean swap(Container origin, Container target, int amount, long timeout, TimeUnit unit)
            throws InsufficientElementsException, InterruptedException {
        if (amount <= 0) throw new IllegalArgumentException("amount must be > 0");
        long deadline = System.nanoTime() + unit.toNanos(timeout);
        int attempts = 0;

        while (true) {
            long remaining = deadline - System.nanoTime();
            if (remaining <= 0) {
                return false;
            }

            long perAttempt = Math.min(TimeUnit.MILLISECONDS.toNanos(50), remaining);
            boolean gotOrigin = false;
            boolean gotTarget = false;

            try {
                gotOrigin = origin.lock.tryLock(perAttempt, TimeUnit.NANOSECONDS);
                if (!gotOrigin) {
                    attempts++;
                    pauseBeforeRetry(attempts, remaining);
                    continue;
                }

                remaining = deadline - System.nanoTime();
                if (remaining <= 0) {
                    return false;
                }

                long perAttempt2 = Math.min(TimeUnit.MILLISECONDS.toNanos(50), remaining);
                gotTarget = target.lock.tryLock(perAttempt2, TimeUnit.NANOSECONDS);
                if (!gotTarget) {
                    attempts++;
                    continue;
                }

                if (origin.elements.get() < amount) {
                    throw new InsufficientElementsException("Insufficient elements in " + origin.name + ": have " + origin.elements.get() + ", need " + amount);
                }

                origin.elements.add(-amount);
                target.elements.add(amount);
                return true;
            } finally {
                if (gotTarget) target.lock.unlock();
                if (gotOrigin) origin.lock.unlock();
                long rem = deadline - System.nanoTime();
                if (!(gotOrigin && gotTarget) && rem > 0) {
                    attempts++;
                    pauseBeforeRetry(attempts, rem);
                }
            }
        }
    }

    private static void pauseBeforeRetry(int attempts, long remainingNanos) throws InterruptedException {
        long delay = fixedDelayNanos(attempts) + randomDelayNanos();
        long sleepNanos = Math.min(delay, Math.max(0, remainingNanos));
        if (sleepNanos > 0) {
            TimeUnit.NANOSECONDS.sleep(sleepNanos);
        }
    }

    private static long fixedDelayNanos(int attempts) {
        long baseMillis = 2L * attempts;
        long cappedMillis = Math.min(20L, baseMillis);
        return TimeUnit.MILLISECONDS.toNanos(cappedMillis);
    }

    private static long randomDelayNanos() {
        long extraMillis = ThreadLocalRandom.current().nextLong(0, 5);
        long extraNanos = ThreadLocalRandom.current().nextLong(0, 1_000_000);
        return TimeUnit.MILLISECONDS.toNanos(extraMillis) + extraNanos;
    }

    static class InsufficientElementsException extends Exception {
        public InsufficientElementsException(String msg) {
            super(msg);
        }
    }

    static class ElementCount {
        private int count;
        ElementCount(int initial) {
            this.count = initial;
        }
        int get() {
            return count;
        }
        void add(int delta) {
            this.count += delta;
        }
    }

    static class Container {
        private final String name;
        private final ReentrantLock lock = new ReentrantLock();
        private final ElementCount elements;

        Container(String name, int initial) {
            this.name = name;
            this.elements = new ElementCount(initial);
        }

        int safeCount() {
            lock.lock();
            try {
                return elements.get();
            } finally {
                lock.unlock();
            }
        }
    }
}
