import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import java.util.concurrent.atomic.AtomicInteger;

public class DeadlockAvoidanceDemo {

    public static class NotEnoughWidgetsException extends Exception {
        public NotEnoughWidgetsException(String message) {
            super(message);
        }
    }

    public static class WidgetCount {
        private int value;

        public WidgetCount(int initial) {
            this.value = initial;
        }

        public int get() {
            return value;
        }

        public void add(int delta) {
            value += delta;
        }

        public void subtract(int delta) {
            value -= delta;
        }
    }

    public static class Bin {
        private final String name;
        private final WidgetCount count;
        private final ReentrantLock lock = new ReentrantLock();

        public Bin(String name, int initialWidgets) {
            this.name = name;
            this.count = new WidgetCount(initialWidgets);
        }

        public String getName() {
            return name;
        }

        public int getCount() {
            return count.get();
        }

        public void deposit(int n) {
            count.add(n);
        }

        public void withdraw(int n) throws NotEnoughWidgetsException {
            if (count.get() < n) {
                throw new NotEnoughWidgetsException("Bin " + name + " has " + count.get() + " widgets, requested " + n);
            }
            count.subtract(n);
        }

        public ReentrantLock getLock() {
            return lock;
        }
    }

    public static boolean move(Bin from, Bin to, int widgets, long timeout, TimeUnit unit)
            throws NotEnoughWidgetsException, InterruptedException {
        long totalNanos = unit.toNanos(timeout);
        long deadline = System.nanoTime() + totalNanos;
        for (;;) {
            long remaining = deadline - System.nanoTime();
            if (remaining <= 0L) {
                return false;
            }
            long window1 = Math.min(remaining, fixedDelayComponentNanos(totalNanos) + randomDelayComponentNanos(totalNanos));
            if (from.getLock().tryLock(window1, TimeUnit.NANOSECONDS)) {
                try {
                    remaining = deadline - System.nanoTime();
                    if (remaining <= 0L) {
                        return false;
                    }
                    long window2 = Math.min(remaining, fixedDelayComponentNanos(totalNanos) + randomDelayComponentNanos(totalNanos));
                    if (to.getLock().tryLock(window2, TimeUnit.NANOSECONDS)) {
                        try {
                            if (from.getCount() < widgets) {
                                throw new NotEnoughWidgetsException("Not enough widgets in " + from.getName());
                            }
                            from.withdraw(widgets);
                            to.deposit(widgets);
                            return true;
                        } finally {
                            to.getLock().unlock();
                        }
                    }
                } finally {
                    from.getLock().unlock();
                }
            }
            long pause = Math.min(deadline - System.nanoTime(), fixedDelayComponentNanos(totalNanos) + randomDelayComponentNanos(totalNanos));
            if (pause > 0L) {
                LockSupport.parkNanos(pause);
            }
        }
    }

    private static long fixedDelayComponentNanos(long totalTimeoutNanos) {
        long fixed = TimeUnit.MILLISECONDS.toNanos(2);
        long fraction = totalTimeoutNanos / 10L;
        return Math.min(fixed, Math.max(1L, fraction));
    }

    private static long randomDelayComponentNanos(long totalTimeoutNanos) {
        long cap = Math.min(TimeUnit.MILLISECONDS.toNanos(8), Math.max(2L, totalTimeoutNanos / 5L));
        return ThreadLocalRandom.current().nextLong(1L, cap);
    }

    public static void main(String[] args) throws Exception {
        final Bin binA = new Bin("A", 100);
        final Bin binB = new Bin("B", 100);

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable task1 = new Runnable() {
            @Override
            public void run() {
                try {
                    boolean moved = move(binA, binB, 70, 1500, TimeUnit.MILLISECONDS);
                    System.out.println("Task1 A->B moved: " + moved + " | A=" + binA.getCount() + " B=" + binB.getCount());
                } catch (NotEnoughWidgetsException e) {
                    System.out.println("Task1 failed: " + e.getMessage());
