import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class WidgetMoverApp {

    public static void main(String[] args) throws Exception {
        final Bin binA = new Bin("A", 100);
        final Bin binB = new Bin("B", 100);

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable moveAToB = () -> {
            for (int i = 0; i < 50; i++) {
                try {
                    boolean moved = move(binA, binB, 1, 1, TimeUnit.SECONDS);
                    if (!moved) {
                        // timed out acquiring locks
                    }
                } catch (NotEnoughWidgetsException e) {
                    // not expected in this scenario
                    break;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        };

        Runnable moveBToA = () -> {
            for (int i = 0; i < 50; i++) {
                try {
                    boolean moved = move(binB, binA, 1, 1, TimeUnit.SECONDS);
                    if (!moved) {
                        // timed out acquiring locks
                    }
                } catch (NotEnoughWidgetsException e) {
                    // not expected in this scenario
                    break;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        };

        pool.submit(moveAToB);
        pool.submit(moveBToA);

        pool.shutdown();
        pool.awaitTermination(15, TimeUnit.SECONDS);

        System.out.println("Final counts:");
        System.out.println("Bin " + binA.getName() + " = " + binA.getCount());
        System.out.println("Bin " + binB.getName() + " = " + binB.getCount());
    }

    public static boolean move(Bin from, Bin to, int qty, long timeout, TimeUnit unit)
            throws NotEnoughWidgetsException, InterruptedException {
        if (qty < 0) throw new IllegalArgumentException("qty must be >= 0");
        final long deadline = System.nanoTime() + unit.toNanos(timeout);
        int attempts = 0;

        while (true) {
            long remaining = deadline - System.nanoTime();
            if (remaining <= 0L) {
                return false;
            }

            if (from.lock.tryLock(remaining, TimeUnit.NANOSECONDS)) {
                try {
                    long remainingForSecond = deadline - System.nanoTime();
                    if (remainingForSecond <= 0L) {
                        return false;
                    }
                    if (to.lock.tryLock(remainingForSecond, TimeUnit.NANOSECONDS)) {
                        try {
                            if (from.widgets.get() < qty) {
                                throw new NotEnoughWidgetsException("Not enough widgets in " + from.name
                                        + ": have " + from.widgets.get() + ", need " + qty);
                            }
                            from.widgets.add(-qty);
                            to.widgets.add(qty);
                            return true;
                        } finally {
                            to.lock.unlock();
                        }
                    }
                } finally {
                    from.lock.unlock();
                }
            }

            attempts++;
            long backoff = computeBackoffNanos(attempts);
            long remainingAfter = deadline - System.nanoTime();
            if (remainingAfter <= 0L) {
                return false;
            }
            long sleepNanos = Math.min(backoff, remainingAfter);
            if (sleepNanos > 0) {
                sleepNanos(sleepNanos);
            }
        }
    }

    private static long computeBackoffNanos(int attempts) {
        long fixed = calcFixedDelayComponent(attempts);
        long rand = calcRandomDelayComponent(attempts);
        return fixed + rand;
    }

    private static long calcFixedDelayComponent(int attempts) {
        long base = TimeUnit.MILLISECONDS.toNanos(2);
        long max = TimeUnit.MILLISECONDS.toNanos(8);
        long value = base * attempts;
        return Math.min(value, max);
    }

    private static long calcRandomDelayComponent(int attempts) {
        int factor = Math.min(attempts, 4);
        long max = TimeUnit.MILLISECONDS.toNanos(3L * factor);
        if (max <= 0) return 0L;
        return ThreadLocalRandom.current().nextLong(max + 1L);
    }

    private static void sleepNanos(long nanos) throws InterruptedException {
        long ms = TimeUnit.NANOSECONDS.toMillis(nanos);
        int ns = (int) (nanos - TimeUnit.MILLISECONDS.toNanos(ms));
        Thread.sleep(ms, ns);
    }

    static class NotEnoughWidgetsException extends Exception {
        NotEnoughWidgetsException(String msg) {
            super(msg);
        }
    }

    static class WidgetCount {
        private int count;

        WidgetCount(int initial) {
            this.count = initial;
        }

        int get() {
            return count;
        }

        void add(int delta) {
            this.count += delta;
        }
    }

    static class Bin {
        private final String name;
        private final ReentrantLock lock = new ReentrantLock();
        private final WidgetCount widgets;

        Bin(String name, int initialWidgets) {
            this.name = name;
            this.widgets = new WidgetCount(initialWidgets);
        }

        String getName() {
            return name;
        }

        int getCount() {
            lock.lock();
            try {
                return widgets.get();
            } finally {
                lock.unlock();
            }
        }
    }
}

