import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class PersonSet {
    private final Set<Person> set = new HashSet<>();

    public static interface Person {
        String getId();
        String getName();
    }

    public synchronized void register(Person p) {
        if (p != null) {
            set.add(p);
        }
    }

    public synchronized boolean contains(Person p) {
        return set.contains(p);
    }

    static final class PersonImpl implements Person {
        private final String id;
        private final String name;

        PersonImpl(String id, String name) {
            this.id = id;
            this.name = name;
        }

        public String getId() {
            return id;
        }

        public String getName() {
            return name;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof PersonImpl)) return false;
            PersonImpl other = (PersonImpl) o;
            return id != null ? id.equals(other.id) : other.id == null;
        }

        public int hashCode() {
            return id != null ? id.hashCode() : 0;
        }

        public String toString() {
            return "Person{id='" + id + "', name='" + name + "'}";
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final PersonSet personSet = new PersonSet();

        final List<Person> toRegister = Arrays.asList(
                new PersonImpl("u-101", "Alice"),
                new PersonImpl("u-102", "Bob"),
                new PersonImpl("u-103", "Carol"),
                new PersonImpl("u-104", "Dave"),
                new PersonImpl("u-105", "Eve")
        );

        final Person unknown = new PersonImpl("u-999", "Ghost");

        ExecutorService exec = Executors.newFixedThreadPool(2);

        exec.submit(new Runnable() {
            public void run() {
                for (Person p : toRegister) {
                    personSet.register(p);
                    System.out.println("Registered: " + p);
                    try {
                        Thread.sleep(150);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
            }
        });

        exec.submit(new Runnable() {
            public void run() {
                List<Person> queries = Arrays.asList(
                        toRegister.get(2),
                        unknown,
                        toRegister.get(0),
                        toRegister.get(4)
                );
                for (int i = 0; i < 10; i++) {
                    Person target = queries.get(i % queries.size());
                    boolean present = personSet.contains(target);
                    System.out.println("contains(" + target + ") -> " + present);
                    try {
                        Thread.sleep(120);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
            }
        });

        exec.shutdown();
        exec.awaitTermination(10, TimeUnit.SECONDS);

        System.out.println("Final verification:");
        for (Person p : toRegister) {
            System.out.println(p + " present: " + personSet.contains(p));
        }
        System.out.println(unknown + " present: " + personSet.contains(unknown));
    }
}

