import java.util.concurrent.TimeUnit;

public class PersonSet {

    public interface Person {
        String getName();
        int getId();
    }

    private final Set<Person> set = new HashSet<>();

    public synchronized void add(Person p) {
        set.add(p);
    }

    public synchronized boolean contains(Person p) {
        return set.contains(p);
    }

    static class SimplePerson implements Person {
        private final int id;
        private final String name;

        SimplePerson(int id, String name) {
            this.id = id;
            this.name = name;
        }

        public String getName() {
            return name;
        }

        public int getId() {
            return id;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof PersonSet.SimplePerson)) {
                if (o instanceof PersonSet.Person) {
                    Person other = (Person) o;
                    if (this.id != other.getId()) return false;
                    if (this.name == null) return other.getName() == null;
                    return this.name.equals(other.getName());
                }
                return false;
            }
            SimplePerson other = (SimplePerson) o;
            if (id != other.id) return false;
            if (name == null) return other.name == null;
            return name.equals(other.name);
        }

        public int hashCode() {
            int result = Integer.hashCode(id);
            result = 31 * result + (name == null ? 0 : name.hashCode());
            return result;
        }

        public String toString() {
            return "SimplePerson{id=" + id + ", name='" + name + "'}";
        }
    }

    public static void main(String[] args) throws Exception {
        final PersonSet personSet = new PersonSet();
        final int n = 1000;

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Future<?> fAdd = pool.submit(new Runnable() {
            public void run() {
                for (int i = 0; i < n; i++) {
                    personSet.add(new SimplePerson(i, "Person-" + i));
                    if ((i & 63) == 0) {
                        try {
                            Thread.sleep(1);
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                            return;
                        }
                    }
                }
            }
        });

        Future<Integer> fCheck = pool.submit(new Callable<Integer>() {
            public Integer call() {
                int found = 0;
                for (int i = 0; i < n; i++) {
                    if (personSet.contains(new SimplePerson(i, "Person-" + i))) {
                        found++;
                    }
                    if ((i & 127) == 0) {
                        try {
                            Thread.sleep(1);
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                            break;
                        }
                    }
                }
                return found;
            }
        });

        fAdd.get();
        int foundDuring = fCheck.get();

        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        int finalCount = 0;
        for (int i = 0; i < n; i++) {
            if (personSet.contains(new SimplePerson(i, "Person-" + i))) {
                finalCount++;
            }
        }

        System.out.println("Found during concurrent checks: " + foundDuring);
        System.out.println("Final contains count: " + finalCount + " of " + n);
    }
}

