public class PublishingVehicleTracker {
    private final ConcurrentHashMap<String, SafePoint> locations;
    private final Map<String, Coordinates> unmodifiableLocationsView;

    public PublishingVehicleTracker(Map<String, int[]> initialLocations) {
        if (initialLocations == null) {
            throw new NullPointerException("initialLocations");
        }
        this.locations = new ConcurrentHashMap<>();
        for (Map.Entry<String, int[]> e : initialLocations.entrySet()) {
            String id = e.getKey();
            int[] xy = e.getValue();
            if (id == null || xy == null || xy.length != 2) {
                throw new IllegalArgumentException("Invalid initial location for vehicle: " + id);
            }
            this.locations.put(id, new SafePoint(xy[0], xy[1]));
        }
        Map<String, Coordinates> views = new LinkedHashMap<>();
        for (Map.Entry<String, SafePoint> e : locations.entrySet()) {
            views.put(e.getKey(), new CoordinatesView(e.getValue()));
        }
        this.unmodifiableLocationsView = Collections.unmodifiableMap(views);
    }

    public Map<String, Coordinates> getLocations() {
        return unmodifiableLocationsView;
    }

    public int[] getLocation(String id) {
        SafePoint p = locations.get(id);
        if (p == null) {
            throw new NoSuchElementException("No such vehicle: " + id);
        }
        return p.get();
    }

    public void setLocation(String id, int x, int y) {
        SafePoint p = locations.get(id);
        if (p == null) {
            throw new NoSuchElementException("No such vehicle: " + id);
        }
        p.set(x, y);
    }

    private static final class SafePoint {
        private int x;
        private int y;

        SafePoint(int x, int y) {
            set(x, y);
        }

        synchronized int[] get() {
            return new int[]{x, y};
        }

        synchronized int getX() {
            return x;
        }

        synchronized int getY() {
            return y;
        }

        synchronized void set(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public interface Coordinates {
        int getX();
        int getY();
    }

    private static final class CoordinatesView implements Coordinates {
        private final SafePoint target;

        CoordinatesView(SafePoint target) {
            this.target = target;
        }

        public int getX() {
            return target.getX();
        }

        public int getY() {
            return target.getY();
        }

        public String toString() {
            return "(" + getX() + "," + getY() + ")";
        }
    }

    public static void main(String[] args) throws Exception {
        Map<String, int[]> initial = new LinkedHashMap<>();
        initial.put("truck-1", new int[]{0, 0});
        initial.put("truck-2", new int[]{10, 10});
        initial.put("truck-3", new int[]{-5, 3});

        final PublishingVehicleTracker tracker = new PublishingVehicleTracker(initial);

        ExecutorService exec = Executors.newFixedThreadPool(2);

        Runnable updater = new Runnable() {
            public void run() {
                try {
                    for (int i = 0; i < 5; i++) {
                        tracker.setLocation("truck-1", i, i);
                        tracker.setLocation("truck-2", 10 + i, 10 - i);
                        Thread.sleep(100);
                    }
                } catch (InterruptedException ignored) {
                }
            }
        };

        Runnable reader = new Runnable() {
            public void run() {
                try {
                    for (int i = 0; i < 5; i++) {
                        Map<String, Coordinates> m = tracker.getLocations();
                        for (Map.Entry<String, Coordinates> e : m.entrySet()) {
                            System.out.println(e.getKey() + " -> " + e.getValue());
                        }
                        int[] p = tracker.getLocation("truck-1");
                        System.out.println("truck-1 snapshot: (" + p[0] + "," + p[1] + ")");
                        Thread.sleep(120);
                    }
                } catch (InterruptedException ignored) {
                }
            }
        };

        exec.submit(updater);
        exec.submit(reader);

        try {
