                if (c != 0) return c;
                return a.getResonance().compareTo(b.getResonance());
            }
        };
        Collections.sort(sorted, runeOrder);

        List<int[]> ranges = new ArrayList<int[]>();
        int i = 0;
        while (i < sorted.size()) {
            int j = i + 1;
