            Callable<Map<Constellation, int[]>> countTask = new Callable<Map<Constellation, int[]>>() {
                public Map<Constellation, int[]> call() {
                    Map<Constellation, int[]> counts = new EnumMap<Constellation, int[]>(Constellation.class);
                    for (Rune r : candidates) {
                        int[] arr = counts.get(r.getConstellation());
                        if (arr == null) {
