                        if (r.getResonance() == Resonance.SOLAR) arr[0]++; else arr[1]++;
                    }
                    return counts;
                }
            };

            Future<List<Rune>> sortedFuture = pool.submit(sortTask);
            Future<Map<Constellation, int[]>> countsFuture = pool.submit(countTask);

            List<Rune> sortedRunes = sortedFuture.get();
            // counts computed concurrently; available if needed
            countsFuture.get();

            Grimoire grimoire = new Grimoire();

            int n = sortedRunes.size();
            int i = 0;
