class Channeler {

    public static int channelTheGrimoire(Collection<Rune> candidates) {
        if (candidates == null || candidates.isEmpty()) return 0;

        final List<Rune> source = new ArrayList<Rune>(candidates);

        final Comparator<Rune> order = new Comparator<Rune>() {
            public int compare(Rune a, Rune b) {
                int c = a.getConstellation().ordinal() - b.getConstellation().ordinal();
                if (c != 0) return c;
                return a.getResonance().ordinal() - b.getResonance().ordinal();
            }
        };

        Collections.sort(source, order);

        final List<Range> ranges = computeConstellationRanges(source);
        final List<Range> partA = new ArrayList<Range>();
        final List<Range> partB = new ArrayList<Range>();
        for (int i = 0; i < ranges.size(); i++) {
            if ((i & 1) == 0) partA.add(ranges.get(i));
            else partB.add(ranges.get(i));
        }

        ExecutorService pool = Executors.newFixedThreadPool(2);
        Future<PairingResult> fa = null;
        Future<PairingResult> fb = null;
        try {
            fa = pool.submit(new Callable<PairingResult>() {
                public PairingResult call() {
                    return pairRanges(source, partA);
                }
            });
            fb = pool.submit(new Callable<PairingResult>() {
                public PairingResult call() {
                    return pairRanges(source, partB);
                }
            });

            PairingResult ra = fa.get();
            PairingResult rb = fb.get();

            List<RuneHarmony> all = new ArrayList<RuneHarmony>();
            if (ra != null && ra.harmonies != null) all.addAll(ra.harmonies);
            if (rb != null && rb.harmonies != null) all.addAll(rb.harmonies);

            Grimoire grimoire = new Grimoire();
            grimoire.crystallize(all);

            return all.size();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Channeling interrupted", e);
        } catch (ExecutionException e) {
            throw new RuntimeException("Channeling failed", e.getCause());
        } finally {
            pool.shutdown();
        }
    }

    private static PairingResult pairRanges(List<Rune> source, List<Range> ranges) {
        List<RuneHarmony> harmonies = new ArrayList<RuneHarmony>();
        for (Range r : ranges) {
            List<Rune> solar = new ArrayList<Rune>();
            List<Rune> lunar = new ArrayList<Rune>();
            for (int i = r.startInclusive; i < r.endExclusive; i++) {
                Rune rune = source.get(i);
                if (rune.getResonance() == Resonance.SOLAR) solar.add(rune);
                else lunar.add(rune);
            }
            int pairs = Math.min(solar.size(), lunar.size());
            for (int i = 0; i < pairs; i++) {
                harmonies.add(new RuneHarmony(solar.get(i), lunar.get(i)));
            }
        }
        return new PairingResult(harmonies);
    }

    private static List<Range> computeConstellationRanges(List<Rune> source) {
        List<Range> ranges = new ArrayList<Range>();
        if (source.isEmpty()) return ranges;
        int start = 0;
        Constellation current = source.get(0).getConstellation();
        for (int i = 1; i < source.size(); i++) {
            Constellation c = source.get(i).getConstellation();
            if (c != current) {
                ranges.add(new Range(start, i, current));
                start = i;
                current = c;
            }
        }
        ranges.add(new Range(start, source.size(), current));
        return ranges;
    }

    private static class Range {
        final int startInclusive;
        final int endExclusive;
        final Constellation constellation;

        Range(int s, int e, Constellation c) {
            this.startInclusive = s;
            this.endExclusive = e;
            this.constellation = c;
        }
    }

    private static class PairingResult {
        final List<RuneHarmony> harmonies;

        PairingResult(List<RuneHarmony> harmonies) {
            this.harmonies = harmonies;
        }
    }
}

