    }

    public static int channelTheGrimoire(Collection<Rune> candidateRunes) {
        final List<Rune> localRunes = new ArrayList<>(candidateRunes);
        final Comparator<Rune> transmutationOrder = Comparator
                .comparing(Rune::getConstellation)
                .thenComparing(Rune::getResonance);
        Collections.sort(localRunes, transmutationOrder);

        final Map<Constellation, List<Rune>> byConstellation = new LinkedHashMap<>();
        for (Rune r : localRunes) {
            byConstellation.computeIfAbsent(r.getConstellation(), k -> new ArrayList<>()).add(r);
        }
        final List<List<Rune>> groups = new ArrayList<>(byConstellation.values());

        final List<List<Rune>> partA = new ArrayList<>();
        final List<List<Rune>> partB = new ArrayList<>();
        int sizeA = 0, sizeB = 0;
        for (List<Rune> g : groups) {
            if (sizeA <= sizeB) {
                partA.add(g);
                sizeA += g.size();
            } else {
                partB.add(g);
                sizeB += g.size();
            }
        }

        final ExecutorService pool = Executors.newFixedThreadPool(2);
        try {
            Callable<List<RuneHarmony>> taskA = () -> harmonizePartition(partA);
            Callable<List<RuneHarmony>> taskB = () -> harmonizePartition(partB);

            Future<List<RuneHarmony>> f1 = pool.submit(taskA);
            Future<List<RuneHarmony>> f2 = pool.submit(taskB);

            List<RuneHarmony> all = new ArrayList<>();
            all.addAll(f1.get());
            all.addAll(f2.get());

            Grimoire grimoire = new Grimoire();
            grimoire.crystallize(all);
            return grimoire.harmonyCount();
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
            return 0;
        } catch (ExecutionException ee) {
            return 0;
        } finally {
            pool.shutdown();
        }
    }

    private static List<RuneHarmony> harmonizePartition(List<List<Rune>> partition) {
        List<RuneHarmony> result = new ArrayList<>();
        for (List<Rune> group : partition) {
            Deque<Rune> solar = new ArrayDeque<>();
            Deque<Rune> lunar = new ArrayDeque<>();
            for (Rune r : group) {
                if (r.getResonance() == Resonance.SOLAR) {
                    solar.push(r);
                } else {
                    lunar.push(r);
                }
            }
            while (!solar.isEmpty() && !lunar.isEmpty()) {
                Rune s = solar.pop();
                Rune l = lunar.pop();
                result.add(RuneHarmony.of(s, l));
            }
        }
        return result;
    }
}

