        final int[][] bounds = new int[constellations.length][2];
        int i = 0;
        for (int c = 0; c < constellations.length; c++) {
            int start = i;
            while (i < runes.size() && runes.get(i).getConstellation() == constellations[c]) {
                i++;
            }
            int end = i;
            bounds[c][0] = start;
            bounds[c][1] = end;
        }

        ExecutorService pool = Executors.newFixedThreadPool(2);
        try {
            int mid = constellations.length / 2;
            Constellation[] firstHalf = Arrays.copyOfRange(constellations, 0, mid);
            Constellation[] secondHalf = Arrays.copyOfRange(constellations, mid, constellations.length);

            Callable<Integer> taskA = () -> crystallizeForConstellations(runes, bounds, firstHalf);
            Callable<Integer> taskB = () -> crystallizeForConstellations(runes, bounds, secondHalf);

            Future<Integer> fa = pool.submit(taskA);
            Future<Integer> fb = pool.submit(taskB);

            int a = getFuture(fa);
            int b = getFuture(fb);
            return a + b;
        } finally {
            pool.shutdown();
        }
    }

    private static int crystallizeForConstellations(List<Rune> runes, int[][] bounds, Constellation[] subset) {
