                new Rune(Constellation.DRACO, Resonance.SOLAR),
                new Rune(Constellation.LYRA, Resonance.LUNAR),
                new Rune(Constellation.LYRA, Resonance.SOLAR),
                new Rune(Constellation.LYRA, Resonance.SOLAR),
                new Rune(Constellation.PHOENIX, Resonance.LUNAR),
                new Rune(Constellation.CORVUS, Resonance.SOLAR)
        );

        int harmonies = channelTheGrimoire(candidates);
        System.out.println("Harmonies crystallized: " + harmonies);
    }

    public static int channelTheGrimoire(Collection<Rune> candidateRunes) {
        ExecutorService exec = Executors.newFixedThreadPool(2);
        try {
            final Comparator<Rune> runeOrder = new Comparator<Rune>() {
                @Override
                public int compare(Rune a, Rune b) {
                    int c = a.getConstellation().compareTo(b.getConstellation());
                    return (c != 0) ? c : a.getResonance().compareTo(b.getResonance());
                }
            };

            Future<List<Rune>> sortedFuture = exec.submit(new Callable<List<Rune>>() {
                @Override
                public List<Rune> call() {
                    List<Rune> local = new ArrayList<>(candidateRunes);
                    local.sort(runeOrder);
                    return Collections.unmodifiableList(local);
                }
            });

            List<Rune> sorted = sortedFuture.get();

            final int n = sorted.size();
            final int boundary = findConstellationBoundary(sorted);

            Callable<List<Harmony>> partOne = new Callable<List<Harmony>>() {
                @Override
                public List<Harmony> call() {
                    return pairRange(sorted, 0, boundary);
                }
            };
            Callable<List<Harmony>> partTwo = new Callable<List<Harmony>>() {
                @Override
                public List<Harmony> call() {
                    return pairRange(sorted, boundary, n);
                }
            };

            Future<List<Harmony>> f1 = exec.submit(partOne);
            Future<List<Harmony>> f2 = exec.submit(partTwo);

            List<Harmony> all = new ArrayList<>();
            all.addAll(f1.get());
            all.addAll(f2.get());

            Grimoire grimoire = new Grimoire();
            return grimoire.crystallize(all);
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Interrupted while channeling the grimoire", ie);
        } catch (ExecutionException ee) {
            throw new RuntimeException("Failed while channeling the grimoire", ee.getCause());
        } finally {
            exec.shutdown();
            try {
                exec.awaitTermination(2, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private static int findConstellationBoundary(List<Rune> sorted) {
        int n = sorted.size();
        if (n == 0) return 0;
        int mid = n / 2;
        if (mid >= n) return n;
        Constellation midConst = sorted.get(mid).getConstellation();

        int left = mid;
        while (left - 1 >= 0 && sorted.get(left - 1).getConstellation() == midConst) {
            left--;
        }
        int right = mid;
        while (right + 1 < n && sorted.get(right + 1).getConstellation() == midConst) {
            right++;
        }
        return right + 1;
    }

    private static List<Harmony> pairRange(List<Rune> sorted, int start, int end) {
        List<Harmony> results = new ArrayList<>();
        int i = start;
        while (i < end) {
            Constellation c = sorted.get(i).getConstellation();
            List<Rune> solar = new ArrayList<>();
            List<Rune> lunar = new ArrayList<>();
            while (i < end && sorted.get(i).getConstellation() == c) {
                Rune r = sorted.get(i);
                if (r.getResonance() == Resonance.SOLAR) {
                    solar.add(r);
                } else if (r.getResonance() == Resonance.LUNAR) {
                    lunar.add(r);
                }
                i++;
            }
            int pairs = Math.min(solar.size(), lunar.size());
            for (int k = 0; k < pairs; k++) {
                results.add(Harmony.of(solar.get(k), lunar.get(k)));
            }
        }
        return results;
    }
}

