public class RuneHarmoniesApp {

    public static void main(String[] args) {
        List<Rune> candidates = Arrays.asList(
                new Rune(Constellation.ORION, Resonance.SOLAR),
                new Rune(Constellation.ORION, Resonance.LUNAR),
                new Rune(Constellation.ORION, Resonance.SOLAR),
                new Rune(Constellation.DRACO, Resonance.SOLAR),
                new Rune(Constellation.DRACO, Resonance.LUNAR),
                new Rune(Constellation.DRACO, Resonance.SOLAR),
                new Rune(Constellation.LYRA, Resonance.LUNAR),
                new Rune(Constellation.LYRA, Resonance.SOLAR),
                new Rune(Constellation.LYRA, Resonance.SOLAR),
                new Rune(Constellation.PHOENIX, Resonance.LUNAR),
                new Rune(Constellation.CORVUS, Resonance.SOLAR)
        );

        int harmonies = channelTheGrimoire(candidates);
        System.out.println("Harmonies crystallized: " + harmonies);
    }

    public static int channelTheGrimoire(Collection<Rune> candidateRunes) {
        ExecutorService exec = Executors.newFixedThreadPool(2);
        try {
            final Comparator<Rune> runeOrder = new Comparator<Rune>() {
                @Override
                public int compare(Rune a, Rune b) {
                    int c = a.getConstellation().compareTo(b.getConstellation());
                    return (c != 0) ? c : a.getResonance().compareTo(b.getResonance());
                }
            };

            Future<List<Rune>> sortedFuture = exec.submit(new Callable<List<Rune>>() {
                @Override
                public List<Rune> call() {
                    List<Rune> local = new ArrayList<>(candidateRunes);
                    local.sort(runeOrder);
                    return Collections.unmodifiableList(local);
                }
            });

            List<Rune> sorted = sortedFuture.get();

            final int n = sorted.size();
            final int boundary = findConstellationBoundary(sorted);

            Callable<List<Harmony>> partOne = new Callable<List<Harmony>>() {
                @Override
                public List<Harmony> call() {
                    return pairRange(sorted, 0, boundary);
                }
            };
            Callable<List<Harmony>> partTwo = new Callable<List<Harmony>>() {
                @Override
                public List<Harmony> call() {
                    return pairRange(sorted, boundary, n);
                }
            };

            Future<List<Harmony>> f1 = exec.submit(partOne);
            Future<List<Harmony>> f2 = exec.submit(partTwo);

            List<Harmony> all = new ArrayList<>();
            all.addAll(f1.get());
            all.addAll(f2.get());

            Grimoire grimoire = new Grimoire();
            return grimoire.crystallize(all);
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Interrupted while channeling the grimoire", ie);
        } catch (ExecutionException ee) {
            throw new RuntimeException("Failed while channeling the grimoire", ee.getCause());
        } finally {
            exec.shutdown();
            try {
                exec.awaitTermination(2, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private static int findConstellationBoundary(List<Rune> sorted) {
        int n = sorted.size();
        if (n == 0) return 0;
        int mid = n / 2;
        if (mid >= n) return n;
        Constellation midConst = sorted.get(mid).getConstellation();

        int left = mid;
        while (left - 1 >= 0 && sorted.get(left - 1).getConstellation() == midConst) {
            left--;
        }
        int right = mid;
        while (right + 1 < n && sorted.get(right + 1).getConstellation() == midConst) {
            right++;
        }
        return right + 1;
    }

    private static List<Harmony> pairRange(List<Rune> sorted, int start, int end) {
        List<Harmony> results = new ArrayList<>();
        int i = start;
        while (i < end) {
            Constellation c = sorted.get(i).getConstellation();
            List<Rune> solar = new ArrayList<>();
            List<Rune> lunar = new ArrayList<>();
            while (i < end && sorted.get(i).getConstellation() == c) {
                Rune r = sorted.get(i);
                if (r.getResonance() == Resonance.SOLAR) {
                    solar.add(r);
                } else if (r.getResonance() == Resonance.LUNAR) {
                    lunar.add(r);
                }
                i++;
            }
            int pairs = Math.min(solar.size(), lunar.size());
            for (int k = 0; k < pairs; k++) {
                results.add(Harmony.of(solar.get(k), lunar.get(k)));
            }
        }
        return results;
    }
}

enum Constellation {
    ORION, DRACO, LYRA, PHOENIX, CORVUS
}

enum Resonance {
    SOLAR, LUNAR;

    public boolean isOpposite(Resonance other) {
        return (this == SOLAR && other == LUNAR) || (this == LUNAR && other == SOLAR);
    }
}

class Rune {
    private final Constellation constellation;
    private final Resonance resonance;

    public Rune(Constellation constellation, Resonance resonance) {
        if (constellation == null || resonance == null) {
            throw new IllegalArgumentException("Constellation and Resonance must be non-null");
        }
        this.constellation = constellation;
        this.resonance = resonance;
    }

    public Constellation getConstellation() {
        return constellation;
    }

    public Resonance getResonance() {
        return resonance;
    }

    @Override
    public String toString() {
        return "Rune{" + constellation + ", " + resonance + "}";
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Rune)) return false;
        Rune other = (Rune) o;
        return constellation == other.constellation && resonance == other.resonance;
    }

    @Override
    public int hashCode() {
        return Objects.hash(constellation, resonance);
    }
}

class Harmony {
    private final Rune first;
    private final Rune second;

    private Harmony(Rune first, Rune second) {
        this.first = first;
        this.second = second;
    }

    public static Harmony of(Rune a, Rune b) {
        if (a == null || b == null) {
            throw new IllegalArgumentException("Runes must be non-null");
        }
        if (a.getConstellation() != b.getConstellation()) {
            throw new IllegalArgumentException("Runes must share the same constellation");
        }
        if (!a.getResonance().isOpposite(b.getResonance())) {
            throw new IllegalArgumentException("Runes must have opposite resonances");
        }
        return new Harmony(a, b);
    }

    public Rune getFirst() {
        return first;
    }

    public Rune getSecond() {
        return second;
    }

    @Override
    public String toString() {
        return "Harmony{" + first + " ~ " + second + "}";
    }
}

class Grimoire {
    private final List<Harmony> harmonies = new ArrayList<>();

    public int crystallize(List<Harmony> toAdd) {
        if (toAdd == null || toAdd.isEmpty()) return harmonies.size();
        harmonies.addAll(toAdd);
        return harmonies.size();
    }

    public List<Harmony> getHarmonies() {
        return Collections.unmodifiableList(harmonies);
    }
}
