class ForgeTask implements Callable<List<Whisker>> {
    private final int seedIndex;

    public ForgeTask(int seedIndex) {
        this.seedIndex = seedIndex;
    }

    @Override
    public List<Whisker> call() {
        Random rnd = new Random(42L + seedIndex);
        List<Whisker> local = new ArrayList<>();
        for (int j = 0; j < 50; j++) {
            int spark = rnd.nextInt(200) - 100;
            int glimmer = rnd.nextInt(200) - 100;
            local.add(new Whisker(spark, glimmer));
        }
        return local;
    }
}

class BoundsTask implements Callable<int[]> {
    private final List<Whisker> data;

    public BoundsTask(List<Whisker> data) {
        this.data = data;
    }

    @Override
    public int[] call() {
        int minS = Integer.MAX_VALUE, maxS = Integer.MIN_VALUE;
        int minG = Integer.MAX_VALUE, maxG = Integer.MIN_VALUE;
        for (Whisker w : data) {
            if (w.spark < minS) minS = w.spark;
            if (w.spark > maxS) maxS = w.spark;
            if (w.glimmer < minG) minG = w.glimmer;
            if (w.glimmer > maxG) maxG = w.glimmer;
        }
        return new int[]{minS, maxS, minG, maxG};
    }
}

class SumsTask implements Callable<long[]> {
    private final List<Whisker> data;

    public SumsTask(List<Whisker> data) {
        this.data = data;
    }

    @Override
    public long[] call() {
        long sumS = 0;
        long sumG = 0;
        int count = data.size();
        for (Whisker w : data) {
            sumS += w.spark;
            sumG += w.glimmer;
        }
        return new long[]{sumS, sumG, count};
    }
}

class FarthestTask implements Callable<Whisker> {
    private final List<Whisker> data;

    public FarthestTask(List<Whisker> data) {
        this.data = data;
    }

    @Override
    public Whisker call() {
        Whisker best = null;
        long bestD2 = -1;
        for (Whisker w : data) {
            long d2 = 1L * w.spark * w.spark + 1L * w.glimmer * w.glimmer;
            if (d2 > bestD2) {
                bestD2 = d2;
                best = w;
            }
        }
        return best;
    }
}

