public class SkyGarden {
    public static void main(String[] args) {
        int total = 1000;
        List<Whisker> whiskers = new ArrayList<>(total);
        for (int i = 0; i < total; i++) {
            whiskers.add(new Whisker(i, total - i));
        }

        ConcurrentLinkedQueue<Whisker> queue = new ConcurrentLinkedQueue<>(whiskers);
        AtomicInteger processed = new AtomicInteger(0);
        AtomicLong sumSpark = new AtomicLong(0);
        AtomicLong sumGlimmer = new AtomicLong(0);
        AtomicLong sumPairProduct = new AtomicLong(0);

        int workers = 4;
        ExecutorService pool = Executors.newFixedThreadPool(workers);
        for (int w = 0; w < workers; w++) {
            pool.submit(new Runnable() {
                public void run() {
                    for (;;) {
                        Whisker next = queue.poll();
                        if (next == null) break;
                        sumSpark.addAndGet(next.spark);
                        sumGlimmer.addAndGet(next.glimmer);
                        sumPairProduct.addAndGet(next.spark * (long) next.glimmer);
                        processed.incrementAndGet();
                    }
                }
            });
        }

        pool.shutdown();
        try {
            pool.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Processed: " + processed.get());
        System.out.println("Sum spark: " + sumSpark.get());
        System.out.println("Sum glimmer: " + sumGlimmer.get());
        System.out.println("Sum spark*glimmer: " + sumPairProduct.get());
    }
}

