import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

public class Main {
    public static void main(String[] args) {
        final int producersCount = 2;
        final int consumersCount = 3;
        final int itemsPerProducer = 50;
        final int capacity = 64;

        final BlockingQueue<Fungloon> queue = new LinkedBlockingQueue<>(capacity);
        final Fungloon poison = new Fungloon(Integer.MIN_VALUE, Integer.MIN_VALUE);

        final AtomicInteger processedCount = new AtomicInteger(0);
        final AtomicLong energySum = new AtomicLong(0);

        Thread[] producers = new Thread[producersCount];
        for (int i = 0; i < producersCount; i++) {
            final int idx = i + 1;
            Runnable producer = new Runnable() {
                public void run() {
                    ThreadLocalRandom rnd = ThreadLocalRandom.current();
                    for (int j = 0; j < itemsPerProducer; j++) {
                        int flint = rnd.nextInt(-1000, 1001);
                        int drizzle = rnd.nextInt(-1000, 1001);
                        Fungloon f = new Fungloon(flint, drizzle);
                        try {
                            queue.put(f);
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                            break;
                        }
                    }
                }
            };
            producers[i] = new Thread(producer, "Producer-" + idx);
        }

        Thread[] consumers = new Thread[consumersCount];
        for (int i = 0; i < consumersCount; i++) {
            final int idx = i + 1;
            Runnable consumer = new Runnable() {
                public void run() {
                    try {
                        while (true) {
                            Fungloon f = queue.take();
                            if (f == poison) {
                                break;
                            }
                            long energy = 1L * f.flint * f.flint + 1L * f.drizzle * f.drizzle;
                            energySum.addAndGet(energy);
                            processedCount.incrementAndGet();
                        }
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                }
            };
            consumers[i] = new Thread(consumer, "Consumer-" + idx);
        }

        for (Thread c : consumers) c.start();
        for (Thread p : producers) p.start();

        for (Thread p : producers) {
            try {
                p.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        for (int i = 0; i < consumersCount; i++) {
            try {
                queue.put(poison);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        for (Thread c : consumers) {
            try {
                c.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        int expected = producersCount * itemsPerProducer;
        System.out.println("Processed Fungloons: " + processedCount.get() + " / " + expected);
        System.out.println("Aggregate energy: " + energySum.get());
    }
}

