    public final int flint;
    public final int drizzle;

    public Fungloon(int flint, int drizzle) {
        this.flint = flint;
        this.drizzle = drizzle;
    }

    public String toString() {
        return "Fungloon(" + flint + "," + drizzle + ")";
    }
}

