                crimbles.add(f.get());
            }
            List<Future<Integer>> metricFutures = new ArrayList<>();
            for (final Crimble c : crimbles) {
                metricFutures.add(pool.submit(new Callable<Integer>() {
                    public Integer call() {
                        return c.twine + c.glint;
                    }
                }));
            }
            int total = 0;
            int max = Integer.MIN_VALUE;
            for (Future<Integer> mf : metricFutures) {
                int val = mf.get();
                total += val;
                if (val > max) {
                    max = val;
                }
            }
            StringBuilder sb = new StringBuilder();
            sb.append("Crimbles:\n");
            for (Crimble c : crimbles) {
                sb.append(c.toString()).append('\n');
