import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CompletionService;
import java.util.concurrent.ExecutorCompletionService;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadLocalRandom;

public class Main {
    public static void main(String[] args) throws Exception {
        int workers = 4;
        ExecutorService pool = Executors.newFixedThreadPool(workers);
        try {
            int taskCount = 12;
            CompletionService<Crimble> creation = new ExecutorCompletionService<>(pool);
            for (int i = 0; i < taskCount; i++) {
                final int seed = i;
                creation.submit(new Callable<Crimble>() {
                    public Crimble call() {
                        ThreadLocalRandom rnd = ThreadLocalRandom.current();
                        int tw = rnd.nextInt(1, 1000) + seed * 17;
                        int gl = rnd.nextInt(1, 1000) + seed * 23;
                        return new Crimble(tw, gl);
                    }
                });
            }

            List<Crimble> all = new ArrayList<>(taskCount);
            for (int i = 0; i < taskCount; i++) {
                Future<Crimble> f = creation.take();
                all.add(f.get());
            }

            List<List<Crimble>> parts = partition(all, workers);
            CompletionService<int[]> processing = new ExecutorCompletionService<>(pool);
            for (List<Crimble> part : parts) {
                processing.submit(new Callable<int[]>() {
                    public int[] call() {
                        int twSum = 0, glSum = 0;
                        for (Crimble c : part) {
                            twSum += c.twine;
                            glSum += c.glint;
                        }
                        return new int[]{twSum, glSum};
                    }
                });
            }

            int totalTw = 0, totalGl = 0;
            for (int i = 0; i < parts.size(); i++) {
                int[] sums = processing.take().get();
                totalTw += sums[0];
                totalGl += sums[1];
            }

            System.out.println("Crimbles created: " + all.size());
            System.out.println("Twine sum: " + totalTw);
            System.out.println("Glint sum: " + totalGl);
            for (int i = 0; i < Math.min(5, all.size()); i++) {
                Crimble c = all.get(i);
                System.out.println("Crimble " + i + " -> twine=" + c.twine + ", glint=" + c.glint);
            }
        } finally {
            pool.shutdown();
        }
    }

    private static List<List<Crimble>> partition(List<Crimble> list, int parts) {
        int size = list.size();
        if (size == 0) {
            List<List<Crimble>> single = new ArrayList<>(1);
            single.add(Collections.<Crimble>emptyList());
            return single;
        }
        int per = Math.max(1, (size + parts - 1) / parts);
        List<List<Crimble>> res = new ArrayList<>();
        int from = 0;
        while (from < size) {
            int to = Math.min(size, from + per);
            res.add(list.subList(from, to));
            from = to;
        }
        return res;
    }
}

