import java.util.ArrayList;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Callable;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

public class CelestialCaravanTracker {

    private final ConcurrentHashMap<String, Starlight> havens;

    public CelestialCaravanTracker(Map<String, Starlight> initial) {
        if (initial == null) {
            throw new NullPointerException("Initial map cannot be null");
        }
        this.havens = new ConcurrentHashMap<>();
        for (Map.Entry<String, Starlight> e : initial.entrySet()) {
            if (e.getKey() == null || e.getValue() == null) {
                throw new NullPointerException("Glyph and Starlight cannot be null");
            }
            this.havens.put(e.getKey(), e.getValue());
        }
    }

    public Map<String, Starlight> getHavens() {
        return Collections.unmodifiableMap(havens);
    }

    public Starlight getHaven(String glyph) {
        return havens.get(glyph);
    }

    public void setHaven(String glyph, int shimmer, int pulse) {
        if (glyph == null) {
            throw new NullPointerException("Glyph cannot be null");
        }
        Starlight prev = havens.replace(glyph, new Starlight(shimmer, pulse));
        if (prev == null) {
            throw new IllegalArgumentException("Beast with glyph '" + glyph + "' does not exist");
        }
    }

    public Map<String, Starlight> getHavensAsStatic() {
        return Collections.unmodifiableMap(new HashMap<>(havens));
    }

    public static void main(String[] args) throws Exception {
        Map<String, Starlight> initial = new LinkedHashMap<>();
        initial.put("Orion", new Starlight(10, 20));
        initial.put("Lyra", new Starlight(30, 40));
        initial.put("Vega", new Starlight(50, 60));
        initial.put("Sirius", new Starlight(70, 80));

        CelestialCaravanTracker tracker = new CelestialCaravanTracker(initial);

        System.out.println("Initial live havens view: " + tracker.getHavens());
        System.out.println("Initial static snapshot: " + tracker.getHavensAsStatic());

        ExecutorService pool = Executors.newFixedThreadPool(4);

        List<Callable<Void>> tasks = new ArrayList<>();
        tasks.add(new HavenMover(tracker, "Orion", 100, 200, 6, 30));
        tasks.add(new HavenMover(tracker, "Lyra", 300, 400, 6, 35));
        tasks.add(new HavenReader(tracker, "Vega", 8, 25));
        tasks.add(new Snapshotter(tracker, 5, 40));
        tasks.add(new FailingMover(tracker, "Rigel", 999, 999));

        List<Future<Void>> futures = new ArrayList<>();
        for (Callable<Void> c : tasks) {
            futures.add(pool.submit(c));
        }
        for (Future<Void> f : futures) {
            try {
                f.get();
            } catch (Exception e) {
                e.printStackTrace(System.out);
            }
        }

        System.out.println("Final live havens view: " + tracker.getHavens());
        System.out.println("Final static snapshot: " + tracker.getHavensAsStatic());

        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);
    }
}

