import java.util.Collections;
import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

public class CelestialCaravanTracker {

    private final ConcurrentHashMap<String, Starlight> havens;

    public CelestialCaravanTracker(Map<String, Starlight> initial) {
        if (initial == null) {
            this.havens = new ConcurrentHashMap<String, Starlight>();
        } else {
            this.havens = new ConcurrentHashMap<String, Starlight>(initial);
        }
    }

    public Map<String, Starlight> getHavens() {
        return Collections.unmodifiableMap(havens);
    }

    public Starlight getHaven(String glyph) {
        return havens.get(glyph);
    }

    public void setHaven(String glyph, int shimmer, int pulse) {
        Starlight prev = havens.replace(glyph, new Starlight(shimmer, pulse));
        if (prev == null) {
            throw new IllegalArgumentException("Beast with glyph not found: " + glyph);
        }
    }

    public Map<String, Starlight> getHavensAsStatic() {
        return Collections.unmodifiableMap(new HashMap<String, Starlight>(havens));
    }

    public static void main(String[] args) throws Exception {
        Map<String, Starlight> initial = new HashMap<String, Starlight>();
        initial.put("alpha", new Starlight(1, 10));
        initial.put("beta", new Starlight(2, 20));
        initial.put("gamma", new Starlight(3, 30));
        initial.put("delta", new Starlight(4, 40));

        CelestialCaravanTracker tracker = new CelestialCaravanTracker(initial);

        ExecutorService pool = Executors.newFixedThreadPool(4);

        AtomicLong readAccum = new AtomicLong(0L);

        pool.execute(new Runnable() {
            public void run() {
                for (int i = 0; i < 5000; i++) {
                    tracker.setHaven("alpha", i, i + 1);
                }
            }
        });

        pool.execute(new Runnable() {
            public void run() {
                for (int i = 0; i < 5000; i++) {
                    tracker.setHaven("beta", i * 2, i * 2 + 2);
                }
            }
        });

        pool.execute(new Runnable() {
            public void run() {
                for (int i = 0; i < 5000; i++) {
                    Starlight s1 = tracker.getHaven("alpha");
                    Starlight s2 = tracker.getHaven("beta");
                    if (s1 != null) {
                        readAccum.addAndGet(s1.getShimmer() + s1.getPulse());
                    }
                    if (s2 != null) {
                        readAccum.addAndGet(s2.getShimmer() + s2.getPulse());
                    }
                }
            }
        });

        pool.execute(new Runnable() {
            public void run() {
                long local = 0L;
                for (int i = 0; i < 500; i++) {
                    Map<String, Starlight> snap = tracker.getHavensAsStatic();
                    for (Map.Entry<String, Starlight> e : snap.entrySet()) {
                        local += e.getValue().getShimmer() ^ e.getValue().getPulse();
                    }
                }
                readAccum.addAndGet(local);
            }
        });

        pool.shutdown();
        pool.awaitTermination(20, TimeUnit.SECONDS);

        try {
            tracker.setHaven("omega", 99, 99);
        } catch (IllegalArgumentException ex) {
            System.out.println("Expected: " + ex.getMessage());
        }

        Map<String, Starlight> liveView = tracker.getHavens();
        System.out.println("Live view:");
        for (Map.Entry<String, Starlight> e : liveView.entrySet()) {
            System.out.println(e.getKey() + " -> " + e.getValue());
        }

        Map<String, Starlight> snapshot = tracker.getHavensAsStatic();
        System.out.println("Snapshot:");
        for (Map.Entry<String, Starlight> e : snapshot.entrySet()) {
            System.out.println(e.getKey() + " -> " + e.getValue());
        }

        try {
            liveView.put("epsilon", new Starlight(7, 70));
        } catch (UnsupportedOperationException uoe) {
            System.out.println("Live view is unmodifiable as expected");
        }

        System.out.println("Accumulated reads: " + readAccum.get());
    }
}

