        try {
            return futureTask.get();
        } catch (ExecutionException e) {
            Throwable c = e.getCause();
            if (c instanceof ConstellationCastException) throw (ConstellationCastException) c;
            if (c instanceof RuntimeException) throw (RuntimeException) c;
            if (c instanceof Error) throw (Error) c;
            throw new RuntimeException("Unexpected exception during constellation weaving", c);
        }
    }

    public Constellation loadConstellation() throws ConstellationCastException {
        Random rnd = new Random(System.nanoTime());
        long stars = 0;
