class Enchanter {
    public static <R> List<R> weaveSequential(List<? extends Talisman<R>> talismans) {
        List<R> results = new ArrayList<>(talismans.size());
        for (Talisman<R> t : talismans) {
            results.add(t.enchant());
        }
        return results;
    }

    public static <R> List<R> conjureParallel(List<? extends Talisman<R>> talismans, ExecutorService executor) {
        List<Future<R>> futures = new ArrayList<>(talismans.size());
        for (Talisman<R> t : talismans) {
            futures.add(executor.submit(new Callable<R>() {
                public R call() {
                    return t.enchant();
                }
            }));
        }
        List<R> results = new ArrayList<>(talismans.size());
        for (Future<R> f : futures) {
            try {
                results.add(f.get());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Interrupted while waiting for talisman enchantment", e);
            } catch (ExecutionException e) {
                throw new RuntimeException("Error during talisman enchantment", e.getCause());
            }
        }
        return results;
    }

    public static <R> List<R> traverseSequential(SigilNode<R> root) {
        List<R> results = new ArrayList<>();
        traverseSequentialRec(root, results);
        return results;
    }

    private static <R> void traverseSequentialRec(SigilNode<R> node, List<R> acc) {
        acc.add(node.compute());
        for (SigilNode<R> child : node.children()) {
            traverseSequentialRec(child, acc);
        }
    }

    public static <R> Collection<R> traverseParallel(SigilNode<R> root, ExecutorService executor) {
        ConcurrentLinkedQueue<R> results = new ConcurrentLinkedQueue<>();
        List<Future<?>> futures = new ArrayList<>();
        submitAll(root, executor, results, futures);
        waitAll(futures);
        return results;
    }

    private static <R> void submitAll(SigilNode<R> node, ExecutorService executor, ConcurrentLinkedQueue<R> results, List<Future<?>> futures) {
        futures.add(executor.submit(new Runnable() {
            public void run() {
                results.add(node.compute());
            }
        }));
        for (SigilNode<R> child : node.children()) {
            submitAll(child, executor, results, futures);
        }
    }

    private static void waitAll(List<Future<?>> futures) {
        for (Future<?> f : futures) {
            try {
                f.get();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Interrupted while waiting for sigil tasks", e);
            } catch (ExecutionException e) {
                throw new RuntimeException("Error during sigil computation", e.getCause());
            }
        }
    }
}

