    public static <R> List<R> weaveRecursiveParallel(SigilNode<R> root, ExecutorService executor) throws InterruptedException {
        final Queue<R> results = new ConcurrentLinkedQueue<>();
        final AtomicInteger remaining = new AtomicInteger(1);
        final CountDownLatch done = new CountDownLatch(1);

        executor.execute(new Runnable() {
            public void run() {
                runSigilTask(root, executor, results, remaining, done);
            }
        });

        done.await();
        return new ArrayList<>(results);
    }

    private static <R> void runSigilTask(SigilNode<R> node,
                                         ExecutorService executor,
                                         Queue<R> results,
                                         AtomicInteger remaining,
                                         CountDownLatch done) {
        try {
            R r = node.compute();
            results.add(r);
            List<? extends SigilNode<R>> children = node.getChildren();
            if (children != null && !children.isEmpty()) {
                for (SigilNode<R> child : children) {
                    remaining.incrementAndGet();
                    executor.execute(new Runnable() {
                        public void run() {
                            runSigilTask(child, executor, results, remaining, done);
                        }
                    });
                }
            }
        } finally {
            if (remaining.decrementAndGet() == 0) {
                done.countDown();
            }
        }
    }
