            List<Integer> parCharmResults = SpellProcessor.castInParallel(charms, executor);
            System.out.println("Parallel charms:   " + parCharmResults);

            AtomicInteger idGen = new AtomicInteger(1);
            RuneNode<String> root = buildSampleTree(idGen, 3, 2);

            List<String> seqRunes = SpellProcessor.traverseSequential(root);
            System.out.println("Sequential runes: " + seqRunes);

