    private static RuneNode<String> buildSampleTree(final AtomicInteger ids, int breadth, int depth) {
        if (depth <= 0) {
            return new SimpleRuneNode<>(new Callable<String>() {
                @Override
                public String call() throws Exception {
                    Thread.sleep(50);
                    return "Rune-" + ids.getAndIncrement();
                }
            }, Collections.<RuneNode<String>>emptyList());
