                @Override
                public R call() {
                    return c.invoke();
                }
            }));
        }
        List<R> results = new ArrayList<R>(charms.size());
        for (Future<R> f : futures) {
            results.add(f.get());
        }
        return results;
    }

    public static <T> List<T> traverseSequential(RuneNode<T> root) {
        List<T> results = new ArrayList<T>();
        traverseSequentialRecursive(root, results);
        return results;
    }

    private static <T> void traverseSequentialRecursive(RuneNode<T> node, List<T> results) {
        results.add(node.compute());
        for (RuneNode<T> child : node.children()) {
            traverseSequentialRecursive(child, results);
        }
    }

    public static <T> Collection<T> traverseParallel(RuneNode<T> root, ExecutorService executor) throws InterruptedException {
        final ConcurrentLinkedQueue<T> results = new ConcurrentLinkedQueue<T>();
        final AtomicInteger pending = new AtomicInteger(1);
        final CountDownLatch done = new CountDownLatch(1);

        executor.execute(buildRuneTask(root, executor, results, pending, done));

        done.await();
        return results;
    }

    private static <T> Runnable buildRuneTask(final RuneNode<T> node,
                                              final ExecutorService executor,
                                              final ConcurrentLinkedQueue<T> results,
                                              final AtomicInteger pending,
                                              final CountDownLatch done) {
        return new Runnable() {
            @Override
            public void run() {
                try {
                    results.add(node.compute());
                    List<RuneNode<T>> children = node.children();
                    for (RuneNode<T> child : children) {
                        pending.incrementAndGet();
                        executor.execute(buildRuneTask(child, executor, results, pending, done));
                    }
                } finally {
                    if (pending.decrementAndGet() == 0) {
                        done.countDown();
                    }
                }
            }
        };
    }
