        List<Future<?>> futures = new ArrayList<>(charms.size());
        for (Charm c : charms) {
            futures.add(executor.submit(new Runnable() {
                @Override
                public void run() {
                    c.invoke();
                }
            }));
        }
        // Ensure completion
        for (Future<?> f : futures) {
            try {
                f.get();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            } catch (ExecutionException e) {
                throw new RuntimeException(e.getCause());
            }
        }
    }

    public static <T> List<T> collectRunesSequential(RuneNode<T> root) {
        List<T> results = new ArrayList<>();
        collectRunesSequentialHelper(root, results);
        return results;
    }

    private static <T> void collectRunesSequentialHelper(RuneNode<T> node, List<T> sink) {
        if (node == null) return;
        T value = node.compute();
        sink.add(value);
        List<RuneNode<T>> children = node.children();
        if (children != null) {
            for (RuneNode<T> child : children) {
                collectRunesSequentialHelper(child, sink);
            }
        }
    }

    public static <T> Collection<T> collectRunesParallel(RuneNode<T> root, ExecutorService executor) {
        if (root == null) return Collections.emptyList();
        RuneParallelCollector<T> collector = new RuneParallelCollector<>(executor);
        return collector.collect(root);
    }

    private static final class RuneParallelCollector<T> {
        private final ExecutorService executor;
        private final ConcurrentLinkedQueue<T> results = new ConcurrentLinkedQueue<>();
        private final AtomicInteger pending = new AtomicInteger(0);
        private final CountDownLatch done = new CountDownLatch(1);

        RuneParallelCollector(ExecutorService executor) {
            this.executor = executor;
        }

        Collection<T> collect(RuneNode<T> root) {
            schedule(root);
            awaitDone();
            return results;
        }

        private void schedule(final RuneNode<T> node) {
            pending.incrementAndGet();
            executor.execute(new Runnable() {
                @Override
                public void run() {
                    try {
                        T value = node.compute();
                        results.add(value);
                        List<RuneNode<T>> children = node.children();
                        if (children != null && !children.isEmpty()) {
                            for (RuneNode<T> child : children) {
                                if (child != null) {
                                    schedule(child);
                                }
                            }
                        }
                    } finally {
                        if (pending.decrementAndGet() == 0) {
                            done.countDown();
                        }
                    }
                }
            });
        }

        private void awaitDone() {
            try {
                done.await();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

