    public static <R> List<R> processTalismansInParallel(List<? extends Talisman<R>> talismans, ExecutorService executor) {
        List<Callable<R>> tasks = new ArrayList<Callable<R>>(talismans.size());
        for (final Talisman<R> t : talismans) {
            tasks.add(new Callable<R>() {
                @Override
                public R call() {
                    return t.activate();
                }
            });
        }
        try {
            List<Future<R>> futures = executor.invokeAll(tasks);
            List<R> results = new ArrayList<R>(futures.size());
            for (Future<R> f : futures) {
                try {
                    results.add(f.get());
                } catch (ExecutionException e) {
                    throw new RuntimeException(e.getCause());
                }
            }
            return results;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Interrupted while invoking talismans", e);
        }
