        List<SigilNode<R>> children = node.getChildren();
        if (children != null) {
            for (SigilNode<R> child : children) {
                traverseNodeSequential(child, out);
            }
        }
    }

    public static <R> Collection<R> traverseForestInParallel(List<? extends SigilNode<R>> roots, ExecutorService executor) {
        final Queue<R> results = new ConcurrentLinkedQueue<R>();
        final AtomicInteger inFlight = new AtomicInteger(0);
        final CountDownLatch done = new CountDownLatch(1);

        for (SigilNode<R> root : roots) {
            inFlight.incrementAndGet();
            submitNode(root, executor, results, inFlight, done);
        }

        if (inFlight.get() == 0) {
            done.countDown();
        }

        try {
            done.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Interrupted while traversing forest", e);
        }
        return results;
    }

    private static <R> void submitNode(final SigilNode<R> node,
                                       final ExecutorService executor,
                                       final Queue<R> results,
                                       final AtomicInteger inFlight,
                                       final CountDownLatch done) {
        executor.execute(new Runnable() {
            @Override
            public void run() {
                try {
                    R value = node.compute();
                    results.add(value);
                    List<SigilNode<R>> children = node.getChildren();
                    if (children != null && !children.isEmpty()) {
                        for (SigilNode<R> child : children) {
                            inFlight.incrementAndGet();
                            submitNode(child, executor, results, inFlight, done);
                        }
                    }
                } finally {
                    if (inFlight.decrementAndGet() == 0) {
                        done.countDown();
                    }
                }
            }
        });
    }
