    static final class SigilTask<R> implements Runnable {
        private final SigilNode<R> node;
        private final ConcurrentLinkedQueue<R> results;
        private final ExecutorService executor;
        private final Phaser phaser;

        SigilTask(SigilNode<R> node, ConcurrentLinkedQueue<R> results, ExecutorService executor, Phaser phaser) {
            this.node = node;
            this.results = results;
            this.executor = executor;
            this.phaser = phaser;
        }

        public void run() {
            try {
                results.add(node.compute());
                List<? extends SigilNode<R>> kids = node.children();
                if (kids != null && !kids.isEmpty()) {
                    for (SigilNode<R> child : kids) {
                        phaser.register();
                        executor.execute(new SigilTask<R>(child, results, executor, phaser));
                    }
                }
            } finally {
                phaser.arriveAndDeregister();
            }
        }
    }

    private static Supplier<String> delayedCompute(final String value, final long millis) {
        return new Supplier<String>() {
            public String get() {
                sleepQuietly(millis);
                return value + "@" + Thread.currentThread().getName();
            }
        };
    }

    private static void sleepQuietly(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException ignored) {
            Thread.currentThread().interrupt();
        }
    }
}

