    private Conclave() {}

    public static <R> List<R> activateTalismansSequentially(List<? extends Talisman<R>> talismans) {
        List<R> results = new ArrayList<>();
        for (Talisman<R> t : talismans) {
            results.add(t.activate());
        }
        return results;
    }

    public static <R> List<R> activateTalismansInParallel(List<? extends Talisman<R>> talismans, ExecutorService executor) {
        List<Future<R>> futures = new ArrayList<>();
        for (Talisman<R> t : talismans) {
            futures.add(submitTalisman(t, executor));
        }
        List<R> results = new ArrayList<>(futures.size());
        for (Future<R> f : futures) {
            try {
                results.add(f.get());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            } catch (ExecutionException e) {
                throw new RuntimeException(e.getCause());
            }
        }
        return results;
    }

    private static <R> Future<R> submitTalisman(final Talisman<R> t, ExecutorService executor) {
        return executor.submit(new Callable<R>() {
            public R call() {
                return t.activate();
            }
        });
    }

    public static <R> List<R> traverseSigilsSequentially(List<? extends SigilNode<R>> forest) {
        List<R> results = new ArrayList<>();
        for (SigilNode<R> root : forest) {
            traverseNodeSequential(root, results);
        }
        return results;
    }

    private static <R> void traverseNodeSequential(SigilNode<R> node, Collection<R> out) {
        out.add(node.compute());
        List<? extends SigilNode<R>> children = node.getChildren();
        if (children != null) {
            for (SigilNode<R> child : children) {
                traverseNodeSequential(child, out);
            }
        }
    }

    public static <R> List<R> traverseSigilsInParallel(List<? extends SigilNode<R>> forest, ExecutorService executor) {
        Queue<R> results = new ConcurrentLinkedQueue<>();
        Phaser phaser = new Phaser(1);
        for (SigilNode<R> root : forest) {
            phaser.register();
            executor.execute(new Runnable() {
                public void run() {
                    try {
                        processNodeParallel(root, results, executor, phaser);
                    } finally {
                        phaser.arriveAndDeregister();
                    }
                }
            });
        }
        phaser.arriveAndAwaitAdvance();
        return new ArrayList<>(results);
    }

    private static <R> void processNodeParallel(SigilNode<R> node, Queue<R> results, ExecutorService executor, Phaser phaser) {
        results.add(node.compute());
        List<? extends SigilNode<R>> children = node.getChildren();
        if (children != null && !children.isEmpty()) {
            for (SigilNode<R> child : children) {
                phaser.register();
                executor.execute(new Runnable() {
                    public void run() {
                        try {
                            processNodeParallel(child, results, executor, phaser);
                        } finally {
                            phaser.arriveAndDeregister();
                        }
                    }
                });
            }
        }
    }
}

