                        System.out.println("Task2 failed: " + e.getMessage());
                    }
                }
            }
        };

        pool.execute(task1);
        pool.execute(task2);
        pool.shutdown();
        try {
            pool.awaitTermination(30, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println(alpha.getName() + " final crystals: " + alpha.getBalance().getUnits());
        System.out.println(beta.getName() + " final crystals: " + beta.getBalance().getUnits());
    }
}

interface VaultNode {
    void deposit(CrystalAmount amount);
    void withdraw(CrystalAmount amount) throws InsufficientCrystalsException;
    CrystalAmount getBalance();
    String getName();
}

interface CrystalAmount {
    long getUnits();
}

class SimpleCrystalAmount implements CrystalAmount {
    private final long units;

    private SimpleCrystalAmount(long units) {
        this.units = units;
    }

    public static SimpleCrystalAmount of(long units) {
        if (units < 0) {
            throw new IllegalArgumentException("Amount cannot be negative");
        }
        return new SimpleCrystalAmount(units);
    }

    @Override
    public long getUnits() {
        return units;
    }

    @Override
    public String toString() {
        return String.valueOf(units);
    }
}

class SimpleVaultNode implements VaultNode {
    private final String name;
    private long crystals;

    public SimpleVaultNode(String name, CrystalAmount initial) {
        if (initial == null) {
            throw new IllegalArgumentException("Initial amount cannot be null");
        }
        this.name = name == null ? "Vault" : name;
        this.crystals = initial.getUnits();
        if (this.crystals < 0) {
            throw new IllegalArgumentException("Initial crystals cannot be negative");
        }
    }

    @Override
    public synchronized void deposit(CrystalAmount amount) {
        if (amount == null) throw new IllegalArgumentException("Amount cannot be null");
        long v = amount.getUnits();
        if (v <= 0) throw new IllegalArgumentException("Deposit amount must be positive");
        crystals += v;
    }

    @Override
    public synchronized void withdraw(CrystalAmount amount) throws InsufficientCrystalsException {
        if (amount == null) throw new IllegalArgumentException("Amount cannot be null");
        long v = amount.getUnits();
        if (v <= 0) throw new IllegalArgumentException("Withdraw amount must be positive");
        if (crystals < v) throw new InsufficientCrystalsException("Not enough crystals in " + name);
        crystals -= v;
    }

    @Override
    public synchronized CrystalAmount getBalance() {
        return SimpleCrystalAmount.of(crystals);
    }

    @Override
    public String getName() {
        return name;
    }
}

class TransferHelper {
    private final Object tieLock = new Object();

    public void transfer(VaultNode from, VaultNode to, CrystalAmount amount) throws InsufficientCrystalsException {
        if (from == null || to == null || amount == null) throw new IllegalArgumentException("Null arguments");
        if (from == to) throw new IllegalArgumentException("Cannot transfer to the same node");
        long v = amount.getUnits();
        if (v <= 0) throw new IllegalArgumentException("Transfer amount must be positive");

        int fromHash = System.identityHashCode(from);
        int toHash = System.identityHashCode(to);

        if (fromHash < toHash) {
            synchronized (from) {
                synchronized (to) {
                    performTransfer(from, to, v);
                }
            }
        } else if (fromHash > toHash) {
            synchronized (to) {
                synchronized (from) {
                    performTransfer(from, to, v);
                }
            }
        } else {
            synchronized (tieLock) {
                synchronized (from) {
                    synchronized (to) {
                        performTransfer(from, to, v);
                    }
                }
            }
        }
    }

    private void performTransfer(VaultNode from, VaultNode to, long v) throws InsufficientCrystalsException {
        if (from.getBalance().getUnits() < v) {
            throw new InsufficientCrystalsException("Insufficient crystals in " + from.getName());
        }
        from.withdraw(SimpleCrystalAmount.of(v));
        to.deposit(SimpleCrystalAmount.of(v));
    }
}

class InsufficientCrystalsException extends Exception {
    public InsufficientCrystalsException(String message) {
        super(message);
    }
}
