                int s = cache.size();
                System.out.println(ts() + " " + tn() + " size before clear=" + s);
                cache.clear();
                System.out.println(ts() + " " + tn() + " clear done");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
