                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        };

        Runnable reader2 = () -> {
            for (int i = 0; i < 12; i++) {
                boolean empty = cache.isEmpty();
                boolean hasGlow = cache.containsValue("glow");
                String orb = cache.get("orb");
                System.out.println(ts() + " " + tn() + " isEmpty=" + empty + ", containsValue(glow)=" + hasGlow + ", get orb -> " + orb);
                try {
                    Thread.sleep(120);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        };

        exec.submit(writer);
