                    Thread.sleep(30);
                }
            } catch (InterruptedException ignored) { Thread.currentThread().interrupt(); }
        };

        Runnable writerB = () -> {
            try {
                start.await();
                Thread.sleep(120);
                Map<String, String> batch = new HashMap<>();
                batch.put("rune-A", "glyph-A");
                batch.put("rune-B", "glyph-B");
                ledger.putAll(batch);
                System.out.println(Thread.currentThread().getName() + " putAll " + batch);
