            } catch (InterruptedException ignored) { Thread.currentThread().interrupt(); }
        };

        pool.submit(writerA);
        pool.submit(reader);
        pool.submit(writerB);

        start.countDown();
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final size: " + ledger.size());
        System.out.println("Final snapshot: " + ledger.snapshot());
    }
}

