import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class EnchantedRegistry<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock rwLock;
    private final Lock readLock;
    private final Lock writeLock;

    public EnchantedRegistry(Map<K, V> existing) {
        if (existing == null) {
            throw new NullPointerException("Existing map cannot be null");
        }
        this.map = existing;
        this.rwLock = new ReentrantReadWriteLock();
        this.readLock = rwLock.readLock();
        this.writeLock = rwLock.writeLock();
    }

    public V put(K key, V value) {
        writeLock.lock();
        try {
            return map.put(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public V remove(Object key) {
        writeLock.lock();
        try {
            return map.remove(key);
        } finally {
            writeLock.unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        writeLock.lock();
        try {
            map.putAll(m);
        } finally {
            writeLock.unlock();
        }
    }

    public void clear() {
        writeLock.lock();
        try {
            map.clear();
        } finally {
            writeLock.unlock();
        }
    }

    public V get(Object key) {
        readLock.lock();
        try {
            return map.get(key);
        } finally {
            readLock.unlock();
        }
    }

    public int size() {
        readLock.lock();
        try {
            return map.size();
        } finally {
            readLock.unlock();
        }
    }

    public boolean isEmpty() {
        readLock.lock();
        try {
            return map.isEmpty();
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsKey(Object key) {
        readLock.lock();
        try {
            return map.containsKey(key);
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsValue(Object value) {
        readLock.lock();
        try {
            return map.containsValue(value);
        } finally {
            readLock.unlock();
        }
    }

    public String toString() {
        readLock.lock();
        try {
            return map.toString();
        } finally {
            readLock.unlock();
        }
    }

    public static void main(String[] args) throws Exception {
        Map<String, String> base = new HashMap<String, String>();
        EnchantedRegistry<String, String> registry = new EnchantedRegistry<String, String>(base);

        ExecutorService pool = Executors.newFixedThreadPool(3);
        AtomicBoolean running = new AtomicBoolean(true);

        Runnable writer = new Runnable() {
            public void run() {
                try {
                    for (int i = 1; i <= 5; i++) {
                        String k = "artifact" + i;
                        String v = "power" + i;
                        registry.put(k, v);
                        System.out.println("Writer put: " + k + " -> " + v + " | size=" + registry.size());
                        Thread.sleep(60);
                    }

                    Map<String, String> extra = new HashMap<String, String>();
                    extra.put("orb", "illumination");
                    extra.put("ring", "protection");
                    registry.putAll(extra);
                    System.out.println("Writer putAll: " + extra + " | size=" + registry.size());
                    Thread.sleep(80);

                    registry.remove("artifact3");
                    System.out.println("Writer removed: artifact3 | size=" + registry.size());
                    Thread.sleep(80);

                    registry.clear();
                    System.out.println("Writer clear all | size=" + registry.size());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } finally {
                    running.set(false);
                }
            }
        };

        Runnable reader1 = new Runnable() {
            public void run() {
                try {
                    while (running.get()) {
                        String key = "artifact" + (1 + (int) (Math.random() * 6));
                        boolean hasKey = registry.containsKey(key);
                        String val = registry.get(key);
                        System.out.println("Reader1 checks: " + key + " present=" + hasKey + " value=" + val);
                        Thread.sleep(30);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        Runnable reader2 = new Runnable() {
            public void run() {
                try {
                    while (running.get()) {
                        int s = registry.size();
                        boolean empty = registry.isEmpty();
                        boolean hasValue = registry.containsValue("power3");
                        System.out.println("Reader2 size=" + s + " empty=" + empty + " containsValue(power3)=" + hasValue);
                        Thread.sleep(40);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        pool.submit(writer);
        pool.submit(reader1);
        pool.submit(reader2);

        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
        System.out.println("Final registry: " + registry.toString() + " | size=" + registry.size());
    }
}

