public class ChronomanticDragonApp {
    public static void main(String[] args) {
        Constellation<String, MutableOrb> initial = new Constellation<>();
        initial.put("Azuron", new MutableOrb(10, 20));
        initial.put("Blazewing", new MutableOrb(30, 40));
        initial.put("Cipherscale", new MutableOrb(50, 60));

        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(initial);

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable updater = new Runnable() {
            @Override
            public void run() {
                Random rnd = new Random();
                String[] sigils = {"Azuron", "Blazewing", "Cipherscale"};
                for (int i = 0; i < 20; i++) {
                    String s = sigils[i % sigils.length];
                    int nx = rnd.nextInt(100);
                    int ny = rnd.nextInt(100);
                    tracker.setOrb(s, nx, ny);
                    try {
                        if (i % 7 == 0) {
                            tracker.setOrb("Unknown", nx, ny);
                        }
                    } catch (IllegalArgumentException ex) {
                        // intentionally ignored
                    }
                    try { Thread.sleep(20); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                }
            }
        };

        Runnable reader = new Runnable() {
            @Override
            public void run() {
                AtomicInteger checksum = new AtomicInteger();
                for (int i = 0; i < 20; i++) {
                    MutableOrb orb = tracker.getOrb("Azuron");
                    if (orb != null) {
                        checksum.addAndGet(orb.getShimmerX() + orb.getShimmerY());
                    }
                    Constellation<String, MutableOrb> snapshot = tracker.getConstellations();
                    int count = snapshot.size();
                    if (i % 5 == 0) {
                        System.out.println("Snapshot(" + i + "): " + snapshot + " | Count=" + count);
                    }
                    try { Thread.sleep(15); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                }
            }
        };

        pool.execute(updater);
        pool.execute(reader);
        pool.shutdown();
        try {
            pool.awaitTermination(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Final snapshot: " + tracker.getConstellations());
        MutableOrb azuron = tracker.getOrb("Azuron");
