class ChronomanticDragonTracker {
    private final Constellation<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(Constellation<String, MutableOrb> initial) {
        if (initial == null) throw new NullPointerException("initial");
        this.constellation = deepClone(initial);
    }

    public synchronized Constellation<String, MutableOrb> getConstellations() {
        Constellation<String, MutableOrb> deep = deepClone(this.constellation);
        return deep.copy(true);
    }

    public synchronized MutableOrb getOrb(String sigil) {
        MutableOrb orb = constellation.get(sigil);
        return orb == null ? null : new MutableOrb(orb);
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        if (!constellation.containsKey(sigil)) {
            throw new IllegalArgumentException("Sigil not found: " + sigil);
        }
        MutableOrb existing = constellation.get(sigil);
        if (existing != null) {
            existing.setShimmerX(shimmerX);
            existing.setShimmerY(shimmerY);
        } else {
            constellation.put(sigil, new MutableOrb(shimmerX, shimmerY));
        }
    }

    private static Constellation<String, MutableOrb> deepClone(Constellation<String, MutableOrb> source) {
        Constellation<String, MutableOrb> copy = new Constellation<>();
        for (Map.Entry<String, MutableOrb> e : source.entrySet()) {
            MutableOrb v = e.getValue();
            copy.put(e.getKey(), v == null ? null : new MutableOrb(v));
        }
        return copy;
    }
}

class Constellation<K, V> {
    private final Map<K, V> map;
    private final boolean unmodifiable;

    public Constellation() {
        this.map = new HashMap<>();
        this.unmodifiable = false;
    }

    private Constellation(Map<K, V> backing, boolean unmodifiable) {
        this.map = backing;
        this.unmodifiable = unmodifiable;
    }

    public void put(K key, V value) {
        if (unmodifiable) throw new UnsupportedOperationException("Unmodifiable constellation");
        map.put(key, value);
    }

    public V get(K key) {
        return map.get(key);
    }

    public boolean containsKey(K key) {
        return map.containsKey(key);
    }

    public int size() {
        return map.size();
    }

    public Set<Map.Entry<K, V>> entrySet() {
        Set<Map.Entry<K, V>> set = map.entrySet();
        return unmodifiable ? Collections.unmodifiableSet(set) : set;
    }

    public Constellation<K, V> copy(boolean asUnmodifiable) {
        return new Constellation<>(new HashMap<>(this.map), asUnmodifiable);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("{");
        Iterator<Map.Entry<K, V>> it = map.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<K, V> e = it.next();
            sb.append(String.valueOf(e.getKey())).append("=").append(String.valueOf(e.getValue()));
            if (it.hasNext()) sb.append(", ");
        }
        sb.append("}");
        return sb.toString();
    }
}

