public class SummonChaosOrbs {

    static final int NUM_THREADS = 2;
    static final int NUM_ORBS = 5;
    static final int ITERATIONS = 10;
    static final int INITIAL_MANA = 1000;
    static final int MAX_TRANSFER = 50;

    static class FluxThread extends Thread {
        private final Orb[] orbs;
        private final int iterations;
        private final java.util.Random rnd;

        FluxThread(Orb[] orbs, int iterations, long seed) {
            this.orbs = orbs;
            this.iterations = iterations;
            this.rnd = new java.util.Random(seed);
        }

        public void run() {
            for (int i = 0; i < iterations; i++) {
                int idxA = rnd.nextInt(orbs.length);
                int idxB = rnd.nextInt(orbs.length);
                Orb from = orbs[idxA];
                Orb to = orbs[idxB];
                int amount = 1 + rnd.nextInt(MAX_TRANSFER);
                try {
                    EtherealFlux.transferEnergy(from, to, new ManaShard(amount));
                } catch (InsufficientManaException e) {
                    // ignored by design
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Orb[] orbs = new Orb[NUM_ORBS];
        for (int i = 0; i < NUM_ORBS; i++) {
            orbs[i] = new Orb(i, INITIAL_MANA);
        }

        int initialTotal = 0;
        for (Orb o : orbs) initialTotal += o.getMana();
        System.out.println("Initial total mana: " + initialTotal);

        FluxThread t1 = new FluxThread(orbs, ITERATIONS, System.nanoTime());
        FluxThread t2 = new FluxThread(orbs, ITERATIONS, System.nanoTime() + 1);

        t1.start();
        t2.start();

        t1.join();
        t2.join();

        int finalTotal = 0;
        for (Orb o : orbs) {
            int mana = o.getMana();
            System.out.println("Orb " + o.getId() + " mana: " + mana);
            finalTotal += mana;
        }
        System.out.println("Final total mana: " + finalTotal);
    }
}

class Orb {
    private final int id;
    private int mana;
    private final java.util.concurrent.locks.ReentrantLock lock = new java.util.concurrent.locks.ReentrantLock();

    Orb(int id, int initialMana) {
        this.id = id;
        this.mana = initialMana;
    }

    int getId() {
        return id;
    }

    void lock() {
        lock.lock();
    }

    void unlock() {
        lock.unlock();
    }

    int getMana() {
        lock.lock();
        try {
            return mana;
        } finally {
            lock.unlock();
        }
    }

    int getManaUnlocked() {
        return mana;
    }

    void addManaUnlocked(int val) {
        mana += val;
    }

    void subtractManaUnlocked(int val) {
        mana -= val;
    }
}

class ManaShard {
    private final int value;

    ManaShard(int value) {
        if (value <= 0) throw new IllegalArgumentException("ManaShard value must be positive");
        this.value = value;
    }

    int getValue() {
        return value;
    }
}

class InsufficientManaException extends Exception {
    InsufficientManaException(String message) {
        super(message);
    }
}

class EtherealFlux {
    public static void transferEnergy(Orb from, Orb to, ManaShard amount) throws InsufficientManaException {
        if (from == to) return;

        Orb first = from.getId() < to.getId() ? from : to;
        Orb second = from.getId() < to.getId() ? to : from;

        first.lock();
        try {
            second.lock();
            try {
                if (from.getManaUnlocked() < amount.getValue()) {
                    throw new InsufficientManaException("Insufficient mana in orb " + from.getId());
                }
                from.subtractManaUnlocked(amount.getValue());
                to.addManaUnlocked(amount.getValue());
            } finally {
                second.unlock();
            }
        } finally {
            first.unlock();
        }
    }
}

