public class ChronoCrystalBalancer {
    static final int NUM_CRYSTALS = 5;
    static final int NUM_THREADS = 2;
    static final int ITERATIONS = 10;
    static final long INITIAL_SHARDS_PER_CRYSTAL = 1000L;

    public static void main(String[] args) throws InterruptedException {
        Crystal[] crystals = new Crystal[NUM_CRYSTALS];
        for (int i = 0; i < NUM_CRYSTALS; i++) {
            crystals[i] = new Crystal(i, INITIAL_SHARDS_PER_CRYSTAL);
        }

        long initialTotal = total(crystals);

        ResonanceThread[] threads = new ResonanceThread[NUM_THREADS];
        for (int i = 0; i < NUM_THREADS; i++) {
            threads[i] = new ResonanceThread("ResonanceThread-" + i, crystals, ITERATIONS);
            threads[i].setDaemon(true);
            threads[i].start();
        }

        for (ResonanceThread t : threads) {
            t.join(3000);
        }

        System.out.println("Initial total shards: " + initialTotal);
        System.out.println("Final total shards: " + total(crystals));
        for (Crystal c : crystals) {
            System.out.println("Crystal " + c.id + " balance: " + c.getBalance());
        }

        for (ResonanceThread t : threads) {
            if (t.isAlive()) {
                System.out.println("Potential temporal deadlock detected involving " + t.getName());
            }
        }
    }

    static long total(Crystal[] crystals) {
        long sum = 0L;
        for (Crystal c : crystals) {
            sum += c.getBalance();
        }
        return sum;
    }

    static class ResonanceThread extends Thread {
