import java.util.Random;

public class GoblinGoldShuffle {

    private static final int THREAD_COUNT = 2;
    private static final int POUCH_COUNT = 5;
    private static final int DEFAULT_GOLD = 100;
    private static final int ITERATIONS = 1000;

    static class GoblinPouch {
        private int gold;

        GoblinPouch(int initialGold) {
            this.gold = initialGold;
        }

        public int getGold() {
            synchronized (this) {
                return gold;
            }
        }
    }

    static class GoldClump {
        private final int amount;

        GoldClump(int amount) {
            if (amount < 0) {
                throw new IllegalArgumentException("Gold amount must be non-negative");
            }
            this.amount = amount;
        }

        int getAmount() {
            return amount;
        }
    }

    static class InsufficientGoldException extends Exception {
        InsufficientGoldException(String message) {
            super(message);
        }
    }

    static class SneakyTrade {
        static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
            if (from == to) {
                return;
            }
            synchronized (from) {
                Thread.yield();
                synchronized (to) {
                    int amt = amount.getAmount();
                    if (amt <= 0) {
                        return;
                    }
                    if (from.gold < amt) {
                        throw new InsufficientGoldException("Not enough gold to transfer");
                    }
                    from.gold -= amt;
                    to.gold += amt;
                }
            }
        }
    }

    static class TradeThread extends Thread {
        private final GoblinPouch[] pouches;
        private final int iterations;
        private final Random random;

        TradeThread(GoblinPouch[] pouches, int iterations, long seed) {
            this.pouches = pouches;
            this.iterations = iterations;
            this.random = new Random(seed);
        }

        @Override
        public void run() {
            for (int i = 0; i < iterations; i++) {
                int fromIdx = random.nextInt(pouches.length);
                int toIdx = random.nextInt(pouches.length);
                if (fromIdx == toIdx) {
                    continue;
                }
                int amt = 1 + random.nextInt(DEFAULT_GOLD / 2);
                try {
                    SneakyTrade.transferGold(pouches[fromIdx], pouches[toIdx], new GoldClump(amt));
                } catch (InsufficientGoldException ignored) {
                }
            }
        }
    }

    public static void main(String[] args) {
        GoblinPouch[] pouches = new GoblinPouch[POUCH_COUNT];
        for (int i = 0; i < POUCH_COUNT; i++) {
            pouches[i] = new GoblinPouch(DEFAULT_GOLD);
        }

        Thread t1 = new TradeThread(pouches, ITERATIONS, 1L);
        Thread t2 = new TradeThread(pouches, ITERATIONS, 2L);

        t1.start();
        t2.start();

        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        int total = 0;
        StringBuilder sb = new StringBuilder();
        sb.append("Final pouch balances: ");
        for (int i = 0; i < pouches.length; i++) {
            int g = pouches[i].getGold();
            total += g;
            sb.append("P").append(i).append("=").append(g);
            if (i < pouches.length - 1) sb.append(", ");
        }
        sb.append("\nTotal gold after trades: ").append(total);
        System.out.println(sb.toString());
    }
}

import java.util.ArrayList;
