public class GoblinGoldShuffle {

    private static final int NUM_POUCHES = 5;
    private static final int NUM_THREADS = 2;
    private static final int ITERATIONS = 10;
    private static final long INITIAL_GOLD_PER_POUCH = 100L;

    public static void main(String[] args) throws InterruptedException {
        List<GoblinPouch> pouches = new ArrayList<>();
        for (int i = 0; i < NUM_POUCHES; i++) {
            pouches.add(new GoblinPouch(i, INITIAL_GOLD_PER_POUCH));
        }

        long initialTotal = totalGold(pouches);
        System.out.println("Initial total gold: " + initialTotal);

        TradeThread[] threads = new TradeThread[NUM_THREADS];
        for (int i = 0; i < NUM_THREADS; i++) {
            threads[i] = new TradeThread(pouches, ITERATIONS, System.nanoTime() + i);
            threads[i].setDaemon(true); // allows JVM to exit even if a deadlock occurs
            threads[i].start();
        }

        // Join with timeout to avoid indefinite wait if a deadlock occurs
        for (Thread t : threads) {
            t.join(3000L);
        }

        boolean anyAlive = false;
        for (Thread t : threads) {
            if (t.isAlive()) {
                anyAlive = true;
                break;
            }
        }

        long finalTotal = totalGold(pouches);
        System.out.println("Final total gold: " + finalTotal);
        for (GoblinPouch p : pouches) {
            System.out.println("Pouch " + p.getId() + " gold: " + p.getGold());
        }

        if (anyAlive) {
            System.out.println("Some trade threads are still running (possible deadlock demonstrated).");
        } else {
            System.out.println("All trade threads have completed.");
        }
    }

    private static long totalGold(List<GoblinPouch> pouches) {
        long sum = 0;
        for (GoblinPouch p : pouches) {
            sum += p.getGold();
        }
        return sum;
    }

