        private final List<GoblinPouch> pouches;
        private final int iterations;
        private final Random random;

        TradeThread(List<GoblinPouch> pouches, int iterations, long seed) {
            this.pouches = pouches;
            this.iterations = iterations;
            this.random = new Random(seed);
        }

        @Override
        public void run() {
            for (int i = 0; i < iterations; i++) {
                int a = random.nextInt(pouches.size());
                int b = random.nextInt(pouches.size() - 1);
                if (b >= a) {
                    b++;
                }
                GoblinPouch from = pouches.get(a);
                GoblinPouch to = pouches.get(b);

                long amount = 1 + random.nextInt(50);
                try {
                    SneakyTrade.transferGold(from, to, new GoldClump(amount));
                } catch (InsufficientGoldException e) {
                    // ignore and continue
                }
            }
        }
    }

    static class SneakyTrade {
        static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
            from.lock();
            try {
                try {
                    Thread.sleep(1L);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                to.lock();
                try {
                    from.withdraw(amount.getNuggets());
                    to.deposit(amount.getNuggets());
                } finally {
                    to.unlock();
                }
            } finally {
                from.unlock();
            }
        }
    }

    static class GoblinPouch {
        private final int id;
        private long gold;
        private final ReentrantLock lock = new ReentrantLock();

        GoblinPouch(int id, long initialGold) {
            this.id = id;
            this.gold = initialGold;
        }

        void lock() {
            lock.lock();
        }

        void unlock() {
            lock.unlock();
        }

        int getId() {
            return id;
        }

        long getGold() {
            lock.lock();
            try {
                return gold;
            } finally {
                lock.unlock();
            }
        }

        void deposit(long amount) {
            gold += amount;
        }

        void withdraw(long amount) throws InsufficientGoldException {
            if (gold < amount) {
                throw new InsufficientGoldException("Insufficient gold");
            }
            gold -= amount;
        }
    }

    static class GoldClump {
        private final long nuggets;

        GoldClump(long nuggets) {
            if (nuggets < 0) {
                throw new IllegalArgumentException("Amount must be non-negative");
            }
            this.nuggets = nuggets;
        }

        long getNuggets() {
            return nuggets;
        }
    }

    static class InsufficientGoldException extends Exception {
        InsufficientGoldException(String message) {
            super(message);
        }
    }
}

