class GoblinPouch {
    private final int id;
    private final ReentrantLock lock = new ReentrantLock();
    private long balance;

    GoblinPouch(int id, long initialGold) {
        this.id = id;
        this.balance = initialGold;
    }

    public int getId() {
        return id;
    }

    public void lock() {
        lock.lock();
    }

    public void unlock() {
        lock.unlock();
    }

    public long getBalance() {
        lock.lock();
        try {
            return balance;
        } finally {
            lock.unlock();
        }
    }

    public void deposit(long amount) {
        if (amount < 0) {
            throw new IllegalArgumentException("Negative deposit");
        }
        lock.lock();
        try {
            balance += amount;
        } finally {
            lock.unlock();
        }
    }

    public void withdraw(long amount) throws InsufficientGoldException {
        if (amount < 0) {
            throw new IllegalArgumentException("Negative withdraw");
        }
        lock.lock();
        try {
            if (balance < amount) {
                throw new InsufficientGoldException("Not enough gold");
            }
            balance -= amount;
        } finally {
            lock.unlock();
        }
    }
}

