            Thread.currentThread().interrupt();
        }

        long total = 0L;
        for (GoblinPouch p : pouches) {
            long bal = p.getBalance();
            total += bal;
            System.out.println("Pouch #" + p.getId() + " balance: " + bal);
        }
        System.out.println("Total gold across all pouches: " + total);
    }

    static class TradeThread extends Thread {
        private final GoblinPouch[] pouches;
        private final int iterations;
        private final Random rnd;

        TradeThread(GoblinPouch[] pouches, int iterations, long seed) {
            this.pouches = pouches;
            this.iterations = iterations;
            this.rnd = new Random(seed);
        }

        @Override
        public void run() {
            for (int i = 0; i < iterations; i++) {
                int fromIdx = rnd.nextInt(pouches.length);
                int toIdx = rnd.nextInt(pouches.length);
                if (fromIdx == toIdx) {
                    continue;
                }
                GoblinPouch from = pouches[fromIdx];
                GoblinPouch to = pouches[toIdx];
                long amount = 1 + rnd.nextInt(START_GOLD);
                GoldClump clump = new GoldClump(amount);
                try {
                    SneakyTrade.transferGold(from, to, clump);
                } catch (InsufficientGoldException e) {
                    // ignore and continue
                }
            }
        }
    }
}

class GoblinPouch {
    private final int id;
    private final ReentrantLock lock = new ReentrantLock();
    private long balance;

    GoblinPouch(int id, long initialGold) {
        this.id = id;
        this.balance = initialGold;
    }

    public int getId() {
        return id;
    }

    public void lock() {
        lock.lock();
    }

    public void unlock() {
        lock.unlock();
    }

    public long getBalance() {
        lock.lock();
        try {
            return balance;
        } finally {
            lock.unlock();
        }
    }

    public void deposit(long amount) {
        if (amount < 0) {
            throw new IllegalArgumentException("Negative deposit");
        }
        lock.lock();
        try {
            balance += amount;
        } finally {
            lock.unlock();
        }
    }

    public void withdraw(long amount) throws InsufficientGoldException {
        if (amount < 0) {
            throw new IllegalArgumentException("Negative withdraw");
        }
        lock.lock();
        try {
            if (balance < amount) {
                throw new InsufficientGoldException("Not enough gold");
            }
            balance -= amount;
        } finally {
            lock.unlock();
        }
    }
}

class GoldClump {
    private final long grains;

    GoldClump(long grains) {
        if (grains <= 0) {
            throw new IllegalArgumentException("Gold clump must be positive");
        }
        this.grains = grains;
    }

    public long getGrains() {
        return grains;
    }
}

class InsufficientGoldException extends Exception {
    InsufficientGoldException() {
        super();
    }

    InsufficientGoldException(String message) {
        super(message);
    }
}

class SneakyTrade {
    public static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
        from.lock();
        try {
            to.lock();
            try {
                if (from.getBalance() < amount.getGrains()) {
                    throw new InsufficientGoldException("Insufficient gold in source pouch");
                }
                from.withdraw(amount.getGrains());
                to.deposit(amount.getGrains());
            } finally {
                to.unlock();
            }
        } finally {
            from.unlock();
        }
    }
}
