import java.lang.ref.WeakReference;
import java.util.Objects;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

public class GoblinEcho {

    private final TreasureSource source;
    private final ExecutorService worker;
    private final AtomicBoolean closed = new AtomicBoolean(false);
    private WhisperListener listener;

    private GoblinEcho(TreasureSource source) {
        this.source = source;
        this.worker = Executors.newSingleThreadExecutor(new java.util.concurrent.ThreadFactory() {
            @Override
            public Thread newThread(Runnable r) {
                Thread t = new Thread(r, "GoblinEcho-Worker");
                t.setDaemon(false);
                return t;
            }
        });
    }

    public static GoblinEcho summonEcho(TreasureSource source) {
        Objects.requireNonNull(source, "TreasureSource must not be null");
        final GoblinEcho echo = new GoblinEcho(source);

        final WeakReference<GoblinEcho> ref = new WeakReference<>(echo);
        WhisperListener whisperListener = new WhisperListener() {
            @Override
            public void onWhisper(String message) {
                GoblinEcho e = ref.get();
                if (e != null && !e.closed.get()) {
                    e.performMischief(message);
                }
            }
        };

        echo.listener = whisperListener;
        source.registerWhisperListener(whisperListener);
        return echo;
    }

    private void performMischief(final String message) {
        if (closed.get()) {
            return;
        }
        worker.execute(new Runnable() {
            @Override
            public void run() {
                String transformed = new StringBuilder(message).reverse().toString();
                System.out.println("[Mischief] " + transformed + " | by " + Thread.currentThread().getName());
            }
        });
    }

    public void close() {
        if (closed.compareAndSet(false, true)) {
            if (listener != null) {
                source.unregisterWhisperListener(listener);
            }
            worker.shutdown();
            try {
                if (!worker.awaitTermination(2, TimeUnit.SECONDS)) {
                    worker.shutdownNow();
                }
            } catch (InterruptedException ie) {
                worker.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
    }

    public static void main(String[] args) throws Exception {
        SimpleTreasureSource source = new SimpleTreasureSource();
        GoblinEcho echo = GoblinEcho.summonEcho(source);

        System.out.println("[Main] Whispering starts on thread " + Thread.currentThread().getName());
        source.whisper("The golden key lies under the old oak.");
        source.whisper("Beware the dragon that sleeps.");
        source.whisper("Treasure favors the bold.");

        Thread.sleep(300); // allow background processing

        echo.close();
        System.out.println("[Main] GoblinEcho closed. Exiting.");
    }
}

