                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    System.out.println("Transfer A->B interrupted");
                }
            }
        });

        Future<?> f2 = pool.submit(new Runnable() {
            @Override
            public void run() {
                try {
                    boolean ok = transfer(b, a, new DollarAmount(900_00), 2, TimeUnit.SECONDS);
                    System.out.println("Transfer B->A 900 result: " + ok);
                } catch (InsufficientFundsException e) {
                    System.out.println("Transfer B->A failed: insufficient funds");
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    System.out.println("Transfer B->A interrupted");
                }
            }
        });

        try {
            f1.get();
            f2.get();
        } catch (Exception e) {
            System.out.println("Error waiting for tasks: " + e);
        } finally {
            pool.shutdown();
            try {
                pool.awaitTermination(5, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        System.out.println("Final balances:");
        System.out.println("A: " + a.getBalance());
        System.out.println("B: " + b.getBalance());
    }

    public static boolean transfer(Account from, Account to, DollarAmount amount, long timeout, TimeUnit unit)
            throws InsufficientFundsException, InterruptedException {
        long deadline = System.nanoTime() + unit.toNanos(timeout);
        long lockSlice = TimeUnit.MILLISECONDS.toNanos(50);

        for (;;) {
            long remaining = deadline - System.nanoTime();
            if (remaining <= 0) {
                return false;
            }

            if (from.lock.tryLock(Math.min(lockSlice, remaining), TimeUnit.NANOSECONDS)) {
                try {
                    remaining = deadline - System.nanoTime();
                    if (remaining <= 0) {
                        return false;
                    }
                    if (to.lock.tryLock(Math.min(lockSlice, remaining), TimeUnit.NANOSECONDS)) {
                        try {
                            if (from.balance.cents < amount.cents) {
                                throw new InsufficientFundsException();
                            }
                            from.balance = from.balance.minus(amount);
                            to.balance = to.balance.plus(amount);
                            return true;
                        } finally {
                            to.lock.unlock();
                        }
                    }
                } finally {
                    from.lock.unlock();
                }
            }

            remaining = deadline - System.nanoTime();
            if (remaining <= 0) {
                return false;
            }
            long backoff = Math.min(remaining, fixedDelayComponentNanos() + randomDelayComponentNanos());
            TimeUnit.NANOSECONDS.sleep(backoff);
        }
    }

    private static long fixedDelayComponentNanos() {
        return TimeUnit.MILLISECONDS.toNanos(2);
    }

    private static long randomDelayComponentNanos() {
        int ms = ThreadLocalRandom.current().nextInt(1, 4);
        return TimeUnit.MILLISECONDS.toNanos(ms);
    }

    static class DollarAmount implements Comparable<DollarAmount> {
        private final long cents;

        DollarAmount(long cents) {
            this.cents = cents;
        }

        DollarAmount plus(DollarAmount other) {
            return new DollarAmount(this.cents + other.cents);
        }

        DollarAmount minus(DollarAmount other) {
            return new DollarAmount(this.cents - other.cents);
        }

        @Override
        public int compareTo(DollarAmount o) {
            return Long.compare(this.cents, o.cents);
        }

        @Override
        public String toString() {
            return String.format("$%.2f", cents / 100.0);
        }
    }

    static class Account {
        private final ReentrantLock lock = new ReentrantLock();
        private DollarAmount balance;

        Account(DollarAmount initial) {
            this.balance = initial;
        }

        DollarAmount getBalance() {
            lock.lock();
            try {
                return balance;
            } finally {
                lock.unlock();
            }
        }
    }

    static class InsufficientFundsException extends Exception {
        private static final long serialVersionUID = 1L;
    }
}

