                return false;
            }
        };

        Callable<Boolean> t2 = () -> {
            try {
                boolean ok = TransferService.transfer(b, a, new DollarAmount(50_00), 2, TimeUnit.SECONDS);
                System.out.println("B->A transfer 50.00 result: " + ok);
                return ok;
            } catch (InsufficientFundsException e) {
                System.out.println("B->A transfer failed: " + e.getMessage());
                return false;
            }
        };

        Future<Boolean> f1 = exec.submit(t1);
        Future<Boolean> f2 = exec.submit(t2);

        f1.get();
        f2.get();

        try {
            boolean ok = TransferService.transfer(a, b, new DollarAmount(1_000_00), 1, TimeUnit.SECONDS);
            System.out.println("A->B large transfer result: " + ok);
        } catch (InsufficientFundsException e) {
            System.out.println("A->B large transfer failed: " + e.getMessage());
        }

        System.out.println("Final A balance: " + a.safeGetBalance());
        System.out.println("Final B balance: " + b.safeGetBalance());

        exec.shutdown();
        exec.awaitTermination(5, TimeUnit.SECONDS);
    }

    static class InsufficientFundsException extends Exception {
        public InsufficientFundsException(String message) {
            super(message);
        }
    }

    static class DollarAmount implements Comparable<DollarAmount> {
        private final long cents;

        public DollarAmount(long cents) {
            this.cents = cents;
        }

        public DollarAmount add(DollarAmount other) {
            return new DollarAmount(this.cents + other.cents);
        }

        public DollarAmount subtract(DollarAmount other) {
            return new DollarAmount(this.cents - other.cents);
        }

        @Override
        public int compareTo(DollarAmount o) {
            return Long.compare(this.cents, o.cents);
        }

        @Override
        public String toString() {
            boolean negative = cents < 0;
            long abs = Math.abs(cents);
            long dollars = abs / 100;
            long rem = abs % 100;
            return (negative ? "-" : "") + "$" + dollars + "." + (rem < 10 ? "0" + rem : rem);
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof DollarAmount)) return false;
            DollarAmount other = (DollarAmount) obj;
            return this.cents == other.cents;
        }

        @Override
        public int hashCode() {
            return Long.hashCode(cents);
        }
    }

    static class Account {
        private final String id;
        private final ReentrantLock lock = new ReentrantLock();
        private DollarAmount balance;

        public Account(String id, DollarAmount initial) {
            this.id = id;
            this.balance = initial;
        }

        void debit(DollarAmount amt) {
            this.balance = this.balance.subtract(amt);
        }

        void credit(DollarAmount amt) {
            this.balance = this.balance.add(amt);
        }

        public DollarAmount safeGetBalance() {
            lock.lock();
            try {
                return balance;
            } finally {
                lock.unlock();
            }
        }

        @Override
        public String toString() {
            return "Account(" + id + ")";
        }
    }

    static class TransferService {

        public static boolean transfer(Account from, Account to, DollarAmount amount, long timeout, TimeUnit unit)
                throws InterruptedException, InsufficientFundsException {

            if (from == to) {
                return true;
            }

            long nanos = unit.toNanos(timeout);
            final long deadline = System.nanoTime() + nanos;
            int attempt = 0;

            while (true) {
                if (nanos <= 0L) {
                    return false;
                }

                boolean fromLocked = false;
                boolean toLocked = false;

                try {
                    fromLocked = from.lock.tryLock(nanos, TimeUnit.NANOSECONDS);
                    if (!fromLocked) {
                        return false;
                    }

                    nanos = deadline - System.nanoTime();
                    if (nanos <= 0L) {
                        return false;
                    }

                    toLocked = to.lock.tryLock(nanos, TimeUnit.NANOSECONDS);
                    if (toLocked) {
                        if (from.balance.compareTo(amount) < 0) {
                            throw new InsufficientFundsException("Insufficient funds in " + from);
                        }
                        from.debit(amount);
                        to.credit(amount);
                        return true;
                    }

                } finally {
                    if (toLocked) {
                        to.lock.unlock();
                    }
                    if (fromLocked) {
                        from.lock.unlock();
                    }
                }

                attempt++;
                long fixed = fixedDelayComponentNanos(attempt);
                long random = randomDelayComponentNanos(fixed);
                long backoff = Math.min(deadline - System.nanoTime(), fixed + random);
                if (backoff > 0L) {
                    TimeUnit.NANOSECONDS.sleep(backoff);
                }
                nanos = deadline - System.nanoTime();
            }
        }

        private static long fixedDelayComponentNanos(int attempt) {
            long baseMillis = 1L << Math.min(attempt, 6);
            long cappedMillis = Math.min(baseMillis, 64L);
            return TimeUnit.MILLISECONDS.toNanos(cappedMillis);
        }

        private static long randomDelayComponentNanos(long upperBoundNanos) {
            if (upperBoundNanos <= 0L) return 0L;
            return ThreadLocalRandom.current().nextLong(upperBoundNanos);
        }
    }
}

