    public static boolean transferMoney(Account fromAcct,
                                        Account toAcct,
                                        DollarAmount amount,
                                        long timeout,
                                        TimeUnit unit) throws InsufficientFundsException, InterruptedException {
        final long deadline = System.nanoTime() + unit.toNanos(timeout);
        final long fixedDelay = getFixedDelayComponentNanos();
        final long randMod = Math.max(1L, getRandomDelayComponentNanos());

        while (true) {
            long remaining = deadline - System.nanoTime();
            if (remaining <= 0L) {
                return false;
            }

            long slice = Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(50));

            boolean fromLocked = false;
            boolean toLocked = false;

            try {
                fromLocked = fromAcct.lock.tryLock(slice, TimeUnit.NANOSECONDS);
                if (fromLocked) {
                    remaining = deadline - System.nanoTime();
                    if (remaining <= 0L) {
                        return false;
                    }
                    slice = Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(50));
                    toLocked = toAcct.lock.tryLock(slice, TimeUnit.NANOSECONDS);
                    if (toLocked) {
                        if (fromAcct.balance.compareTo(amount) < 0) {
                            throw new InsufficientFundsException("Insufficient funds in account " + fromAcct.id);
                        }
                        fromAcct.debit(amount);
                        toAcct.credit(amount);
                        return true;
                    }
                }
            } finally {
                if (toLocked && toAcct.lock.isHeldByCurrentThread()) {
                    toAcct.lock.unlock();
                }
                if (fromLocked && fromAcct.lock.isHeldByCurrentThread()) {
                    fromAcct.lock.unlock();
                }
            }

            long backoff = fixedDelay + ThreadLocalRandom.current().nextLong(randMod);
            remaining = deadline - System.nanoTime();
            if (remaining <= 0L) {
                return false;
            }
            TimeUnit.NANOSECONDS.sleep(Math.min(backoff, remaining));
        }
    }

    private static long getFixedDelayComponentNanos() {
        return TimeUnit.MILLISECONDS.toNanos(1);
    }

