import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class BarrierTimerDemo {
    public static void main(String[] args) throws InterruptedException {
        final BarrierTimer timer = new BarrierTimer();
        timer.clear();

        final int parties = 2;
        CyclicBarrier barrier = new CyclicBarrier(parties, timer);

        ExecutorService pool = Executors.newFixedThreadPool(parties);
        try {
            for (int i = 0; i < parties; i++) {
                pool.submit(new Worker(barrier, i));
            }
        } finally {
            pool.shutdown();
            pool.awaitTermination(10, TimeUnit.SECONDS);
        }

        long elapsedNs = timer.getTime();
        System.out.println("Elapsed time (ns): " + elapsedNs);
        System.out.println("Elapsed time (ms): " + (elapsedNs / 1_000_000.0));
    }
}

class BarrierTimer implements Runnable {
    private boolean started;
    private long startTime;
    private long endTime;

    public synchronized void run() {
        long t = System.nanoTime();
        if (!started) {
            started = true;
            startTime = t;
        } else {
            endTime = t;
        }
    }

    public synchronized void clear() {
        started = false;
    }

    public synchronized long getTime() {
        return endTime - startTime;
    }
}

