import java.util.concurrent.Semaphore;

class BoundedBuffer<E> {
    private final Object[] data;
    private final int capacity;
    private int head = 0;
    private int tail = 0;
    private final Semaphore items;
    private final Semaphore spaces;
    private final Object lock = new Object();

    BoundedBuffer(int capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("capacity must be > 0");
        this.capacity = capacity;
        this.data = new Object[capacity];
        this.items = new Semaphore(0);
        this.spaces = new Semaphore(capacity);
    }

    public void put(E x) throws InterruptedException {
        if (x == null) throw new NullPointerException("null elements not allowed");
        spaces.acquire();
        synchronized (lock) {
            data[tail] = x;
            tail = (tail + 1) % capacity;
        }
        items.release();
    }

    @SuppressWarnings("unchecked")
    public E take() throws InterruptedException {
        items.acquire();
        E x;
        synchronized (lock) {
            x = (E) data[head];
            data[head] = null;
            head = (head + 1) % capacity;
        }
        spaces.release();
        return x;
    }

    public boolean isEmpty() {
        return items.availablePermits() == 0;
    }

    public boolean isFull() {
        return spaces.availablePermits() == 0;
    }
}

