BigInteger[] factors = cache.getFactors(input);
if (factors == null) {
factors = factor(input);
cache = new OneValueCache(input, factors);
System.out.println(Thread.currentThread().getName() + ": computed and cached " + input);
} else {
System.out.println(Thread.currentThread().getName() + ": cache hit for " + input);
}
encodeIntoResponse(factors);
}

void encodeIntoResponse(BigInteger[] factors) {
System.out.println(Thread.currentThread().getName() + ": response = " + factors[0]);
}

BigInteger[] factor(BigInteger i) {
return new BigInteger[]{i};
}

private static final class OneValueCache {
private final BigInteger lastNumber;
private final BigInteger[] lastFactors;

public OneValueCache(BigInteger number, BigInteger[] factors) {
this.lastNumber = number;
this.lastFactors = (factors == null) ? null : factors.clone();
}

public BigInteger[] getFactors(BigInteger input) {
if (lastNumber == null || !lastNumber.equals(input)) {
return null;
}
return lastFactors.clone();
}
}

public static void main(String[] args) {
final VolatileCachedFactorizer servlet = new VolatileCachedFactorizer();

Thread t1 = new Thread(() -> servlet.service(new BigInteger("3")), "T1");
Thread t2 = new Thread(() -> servlet.service(new BigInteger("5")), "T2");

t1.start();
t2.start();

try {
t1.join();
t2.join();
} catch (InterruptedException e) {
System.out.println("Interrupted");
}
}
}

