        ExecutorService pool = Executors.newFixedThreadPool(4);
        List<Callable<String>> tasks = new ArrayList<String>();

        tasks.add(new Callable<String>() {
            public String call() {
                return "isStooge(\"Moe\"): " + stooges.isStooge("Moe");
            }
        });
        tasks.add(new Callable<String>() {
            public String call() {
