class NamedTask implements Runnable {
    private final String name;
    private final int steps;
    private final long pauseMs;
    private static final Logger LOGGER = Logger.getLogger(NamedTask.class.getName());

    NamedTask(String name, int steps, long pauseMs) {
        this.name = name;
        this.steps = steps;
        this.pauseMs = pauseMs;
    }

    @Override
    public void run() {
        for (int i = 1; i <= steps; i++) {
            LOGGER.info(name + " step " + i + " on " + Thread.currentThread().getName());
