class MyAppThread extends Thread {
    private static final ConcurrentMap<String, ThreadGroup> GROUPS = new ConcurrentHashMap<>();
    private static final ConcurrentMap<String, AtomicInteger> COUNTERS = new ConcurrentHashMap<>();
    public MyAppThread(Runnable target, String poolName) {
        super(getOrCreateGroup(poolName), target, nextThreadName(poolName));
        setDaemon(false);
        setPriority(NORM_PRIORITY);
        setUncaughtExceptionHandler(new UncaughtExceptionHandler() {
            @Override
            public void uncaughtException(Thread t, Throwable e) {
                System.err.println("Uncaught exception in " + t.getName() + ": " + e);
            }
        });
    }
    private static ThreadGroup getOrCreateGroup(String poolName) {
        return GROUPS.computeIfAbsent(poolName, ThreadGroup::new);
    }
    private static String nextThreadName(String poolName) {
        AtomicInteger c = COUNTERS.computeIfAbsent(poolName, k -> new AtomicInteger(0));
        return poolName + "-t" + c.incrementAndGet();
    }
}

class RangeSumTask implements Runnable {
    private final long start;
    private final long end;
    private final LongAdder adder;
    public RangeSumTask(long start, long end, LongAdder adder) {
        this.start = start;
        this.end = end;
        this.adder = adder;
    }
    @Override
    public void run() {
        long local = 0L;
        for (long i = start; i <= end; i++) {
            local += i;
        }
        adder.add(local);
        System.out.println(Thread.currentThread().getName() + " summed range [" + start + ", " + end + "] -> " + local);
    }
}

