import java.util.concurrent.TimeUnit;

public class DelegatingVehicleTracker {

    private final ConcurrentHashMap<String, Point> locations;
    private final Map<String, Point> unmodifiableMapView;

    public DelegatingVehicleTracker(Map<String, Point> initial) {
        Map<String, Point> safeInitial = (initial == null) ? Collections.<String, Point>emptyMap() : initial;
        this.locations = new ConcurrentHashMap<>(safeInitial);
        this.unmodifiableMapView = Collections.unmodifiableMap(this.locations);
    }

    public Map<String, Point> getLocations() {
        return unmodifiableMapView;
    }

    public Point getLocation(String id) {
        if (id == null) return null;
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        if (id == null) throw new IllegalArgumentException("id cannot be null");
        Point prev = locations.replace(id, new Point(x, y));
        if (prev == null) {
            throw new IllegalArgumentException("No such vehicle: " + id);
        }
    }

    public Map<String, Point> getLocationsAsStatic() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

