public class DelegatingVehicleTracker {
    private final ConcurrentMap<String, Point> locations;
    private final Map<String, Point> unmodifiableMapView;

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        Map<String, Point> copy = new HashMap<>();
        if (initialLocations != null) {
            for (Map.Entry<String, Point> e : initialLocations.entrySet()) {
                Point p = e.getValue();
                copy.put(e.getKey(), p == null ? null : new Point(p.getX(), p.getY()));
            }
        }
        this.locations = new ConcurrentHashMap<>(copy);
        this.unmodifiableMapView = Collections.unmodifiableMap(this.locations);
    }

    public Map<String, Point> getLocations() {
        return unmodifiableMapView;
    }

    public Point getLocation(String id) {
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        Point prev = locations.replace(id, new Point(x, y));
        if (prev == null) {
            throw new IllegalArgumentException("Vehicle not found: " + id);
        }
    }

    public Map<String, Point> getLocationsAsStatic() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, Point> initial = new HashMap<>();
        initial.put("v1", new Point(0, 0));
        initial.put("v2", new Point(10, 10));
        initial.put("v3", new Point(-5, 5));

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initial);

