        pool.submit(() -> {
            for (int i = 0; i < 10; i++) {
                Map<String, Point> live = tracker.getLocations();
                System.out.println("Dynamic view: " + live);
                sleepSilently(40);
            }
        });

        pool.submit(() -> {
            for (int i = 0; i < 5; i++) {
                Map<String, Point> snap = tracker.getLocationsAsStatic();
                System.out.println("Snapshot: " + snap);
                sleepSilently(80);
            }
            try {
                tracker.setLocation("unknown", 0, 0);
            } catch (IllegalArgumentException ex) {
                System.out.println("Expected exception: " + ex.getMessage());
            }
        });

        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final live view: " + tracker.getLocations());
        System.out.println("Final snapshot: " + tracker.getLocationsAsStatic());
    }

    private static void sleepSilently(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException ignored) {
            Thread.currentThread().interrupt();
        }
    }

    static final class Point {
        private final int x;
        private final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

