import java.util.Random;

public class DemonstrateDeadlock {

    private static final int NUM_ACCOUNTS = 5;
    private static final int NUM_THREADS = 2;
    private static final int ITERATIONS = 10;
    private static final int INITIAL_BALANCE_CENTS = 100_00;

    public static void main(String[] args) {
        Account[] accounts = new Account[NUM_ACCOUNTS];
        for (int i = 0; i < NUM_ACCOUNTS; i++) {
            accounts[i] = new Account(i, INITIAL_BALANCE_CENTS);
        }

        printBalances("Starting balances", accounts);

        TransferThread t1 = new TransferThread("Transfer-1", accounts, ITERATIONS, System.nanoTime());
        TransferThread t2 = new TransferThread("Transfer-2", accounts, ITERATIONS, System.nanoTime() + 1);

        t1.start();
        t2.start();

        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        printBalances("Final balances", accounts);
    }

    private static void printBalances(String title, Account[] accounts) {
        System.out.println(title + ":");
        int total = 0;
        for (Account a : accounts) {
            DollarAmount bal = a.getBalance();
            total += bal.getCents();
            System.out.println("  Account " + a.getId() + " -> " + bal);
        }
        System.out.println("  Total -> " + new DollarAmount(total));
    }

    static class TransferThread extends Thread {
        private final Account[] accounts;
        private final int iterations;
        private final Random random;

        TransferThread(String name, Account[] accounts, int iterations, long seed) {
            super(name);
            this.accounts = accounts;
            this.iterations = iterations;
            this.random = new Random(seed);
        }

        @Override
        public void run() {
            for (int i = 0; i < iterations; i++) {
                int fromIdx = random.nextInt(accounts.length);
                int toIdx;
                do {
                    toIdx = random.nextInt(accounts.length);
                } while (toIdx == fromIdx);

                Account from = accounts[fromIdx];
                Account to = accounts[toIdx];
                int amountCents = 1 + random.nextInt(500); // up to $5.00

                try {
                    DynamicOrderDeadlock.transferMoney(from, to, new DollarAmount(amountCents));
                } catch (InsufficientFundsException ignored) {
                }
            }
        }
    }
}

class Account {
    private final int id;
    private int balanceCents;

    Account(int id, int initialBalanceCents) {
        this.id = id;
        this.balanceCents = initialBalanceCents;
    }

    int getId() {
        return id;
    }

    DollarAmount getBalance() {
        return new DollarAmount(balanceCents);
    }

    void debit(DollarAmount amount) {
        balanceCents -= amount.getCents();
    }

    void credit(DollarAmount amount) {
        balanceCents += amount.getCents();
    }
}

class DollarAmount implements Comparable<DollarAmount> {
    private final int cents;

    DollarAmount(int cents) {
        if (cents < 0) throw new IllegalArgumentException("Negative amount");
        this.cents = cents;
    }

    int getCents() {
        return cents;
    }

    @Override
    public int compareTo(DollarAmount other) {
        return Integer.compare(this.cents, other.cents);
    }

    @Override
    public String toString() {
        return String.format("$%.2f", cents / 100.0);
    }
}

class InsufficientFundsException extends Exception {
    InsufficientFundsException() {
        super("Insufficient funds");
    }
}

class DynamicOrderDeadlock {
    public static void transferMoney(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
        synchronized (from) {
            synchronized (to) {
                if (from.getBalance().compareTo(amount) < 0) {
                    throw new InsufficientFundsException();
                }
                from.debit(amount);
                to.credit(amount);
            }
        }
    }
}

import java.util.Random;

public class DemonstrateDeadlock {
    public static void main(String[] args) throws InterruptedException {
        int numThreads = 2;
        int numAccounts = 5;
        int iterations = 10;

        Account[] accounts = new Account[numAccounts];
        for (int i = 0; i < numAccounts; i++) {
            accounts[i] = new Account(i, new DollarAmount(100));
        }

        Thread t1 = new TransferThread(accounts, iterations, System.nanoTime());
        Thread t2 = new TransferThread(accounts, iterations, System.nanoTime() + 1);

        t1.start();
        t2.start();

        t1.join();
        t2.join();

        for (Account a : accounts) {
            System.out.println("Account " + a.getId() + " balance: " + a.getBalance());
        }
    }

    public static class TransferThread extends Thread {
        private final Account[] accounts;
        private final int iterations;
        private final Random random;

        public TransferThread(Account[] accounts, int iterations, long seed) {
            this.accounts = accounts;
            this.iterations = iterations;
            this.random = new Random(seed);
        }

        @Override
        public void run() {
            int n = accounts.length;
            for (int i = 0; i < iterations; i++) {
                int fromIdx = random.nextInt(n);
                int toIdx = random.nextInt(n);
                while (toIdx == fromIdx) {
                    toIdx = random.nextInt(n);
                }
                DollarAmount amount = new DollarAmount(1 + random.nextInt(50));
                try {
                    DynamicOrderDeadlock.transferMoney(accounts[fromIdx], accounts[toIdx], amount);
                } catch (InsufficientFundsException ignore) {
                }
            }
        }
    }
}

class DynamicOrderDeadlock {
    public static void transferMoney(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
        synchronized (from) {
            synchronized (to) {
                if (from.getBalance().compareTo(amount) < 0) {
                    throw new InsufficientFundsException("Insufficient funds in account " + from.getId());
                }
                from.debit(amount);
                to.credit(amount);
            }
        }
    }
}

class Account {
    private final int id;
    private long balance;

    public Account(int id, DollarAmount initialBalance) {
        this.id = id;
        this.balance = initialBalance.asLong();
    }

    public int getId() {
        return id;
    }

    public synchronized DollarAmount getBalance() {
        return new DollarAmount(balance);
    }

    public void debit(DollarAmount amount) {
        balance -= amount.asLong();
