import java.util.Random;

public class DemonstrateDeadlock {

    private static final int NUM_ACCOUNTS = 5;
    private static final int NUM_THREADS = 2;
    private static final int ITERATIONS_PER_THREAD = 1_000_000;
    private static final int DEFAULT_BALANCE = 1000;
    private static final long RANDOM_SEED_BASE = 12345L;

    public static void main(String[] args) throws InterruptedException {
        Account[] accounts = new Account[NUM_ACCOUNTS];
        for (int i = 0; i < NUM_ACCOUNTS; i++) {
            accounts[i] = new Account(i, new DollarAmount(DEFAULT_BALANCE));
        }

        TransferThread[] threads = new TransferThread[NUM_THREADS];
        for (int i = 0; i < NUM_THREADS; i++) {
            threads[i] = new TransferThread(accounts, ITERATIONS_PER_THREAD, RANDOM_SEED_BASE + i);
            threads[i].start();
        }

        for (TransferThread t : threads) {
            t.join();
        }
    }

    static class TransferThread extends Thread {
        private final Account[] accounts;
        private final int iterations;
        private final Random random;

        TransferThread(Account[] accounts, int iterations, long seed) {
            this.accounts = accounts;
            this.iterations = iterations;
            this.random = new Random(seed);
        }

        @Override
        public void run() {
            for (int i = 0; i < iterations; i++) {
                int fromIdx = random.nextInt(accounts.length);
                int toIdx = random.nextInt(accounts.length - 1);
                if (toIdx >= fromIdx) {
                    toIdx++;
                }
                Account from = accounts[fromIdx];
                Account to = accounts[toIdx];

                int amountUnits = random.nextInt(100) + 1;
                DollarAmount amount = new DollarAmount(amountUnits);
                try {
                    DynamicOrderDeadlock.transferMoney(from, to, amount);
                } catch (InsufficientFundsException ignored) {
                }
            }
        }
    }
}

class DynamicOrderDeadlock {
    public static void transferMoney(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
        if (from == to) {
            return;
        }
        synchronized (from) {
            synchronized (to) {
                if (from.getBalance().compareTo(amount) < 0) {
                    throw new InsufficientFundsException("Insufficient funds");
                }
                from.debit(amount);
                to.credit(amount);
            }
        }
    }
}

