import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class StripedMap<K, V> {
    private static final int N_LOCKS = 16;

    private static class Node<K, V> {
        final K key;
        V value;
        Node<K, V> next;

        Node(K key, V value, Node<K, V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    private final int bucketCount;
    @SuppressWarnings("unchecked")
    private final Node<K, V>[] buckets;
    private final Object[] locks;

    public StripedMap(int bucketCount) {
        if (bucketCount <= 0) {
            throw new IllegalArgumentException("bucketCount must be > 0");
        }
        this.bucketCount = bucketCount;
        this.buckets = (Node<K, V>[]) new Node[bucketCount];
        this.locks = new Object[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            this.locks[i] = new Object();
        }
    }

    private int bucketIndex(Object key) {
        int h = (key == null) ? 0 : key.hashCode();
        h ^= (h >>> 16);
        return (h & 0x7fffffff) % bucketCount;
    }

    public V get(K key) {
        int bi = bucketIndex(key);
        Object lock = locks[bi % N_LOCKS];
        synchronized (lock) {
            Node<K, V> e = buckets[bi];
            while (e != null) {
                if (key == e.key || (key != null && key.equals(e.key))) {
                    return e.value;
                }
                e = e.next;
            }
            return null;
        }
    }

    public void put(K key, V value) {
        int bi = bucketIndex(key);
        Object lock = locks[bi % N_LOCKS];
        synchronized (lock) {
            Node<K, V> head = buckets[bi];
            for (Node<K, V> p = head; p != null; p = p.next) {
                if (key == p.key || (key != null && key.equals(p.key))) {
                    p.value = value;
                    return;
                }
            }
            buckets[bi] = new Node<>(key, value, head);
        }
    }

    public void clear() {
        for (int li = 0; li < N_LOCKS; li++) {
            Object lock = locks[li];
            synchronized (lock) {
                for (int bi = li; bi < bucketCount; bi += N_LOCKS) {
                    buckets[bi] = null;
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        final int ENTRIES = 1000;
        final int THREADS = 4;

        StripedMap<Integer, String> map = new StripedMap<>(128);
        ExecutorService pool = Executors.newFixedThreadPool(THREADS);

        List<Callable<Void>> putTasks = new ArrayList<>();
        int chunk = ENTRIES / THREADS;
        for (int t = 0; t < THREADS; t++) {
            final int start = t * chunk;
            final int end = (t == THREADS - 1) ? ENTRIES : start + chunk;
            putTasks.add(() -> {
                for (int i = start; i < end; i++) {
                    map.put(i, "V" + i);
                }
                return null;
            });
        }
        List<Future<Void>> putResults = new ArrayList<>();
        for (Callable<Void> task : putTasks) {
            putResults.add(pool.submit(task));
        }
        for (Future<Void> f : putResults) {
            f.get();
        }

        List<Callable<Integer>> getTasks = new ArrayList<>();
        for (int t = 0; t < THREADS - 1; t++) {
            getTasks.add(() -> {
                int found = 0;
                for (int r = 0; r < 5; r++) {
                    for (int i = 0; i < ENTRIES; i++) {
                        if (map.get(i) != null) {
                            found++;
                        }
                    }
                }
                return found;
            });
        }

        Callable<Void> clearTask = () -> {
            try {
                Thread.sleep(50);
            } catch (InterruptedException ignored) {
            }
            map.clear();
            return null;
        };

        List<Future<Integer>> getFutures = new ArrayList<>();
        for (Callable<Integer> task : getTasks) {
            getFutures.add(pool.submit(task));
        }
        Future<Void> clearFuture = pool.submit(clearTask);

        int totalFound = 0;
        for (Future<Integer> f : getFutures) {
            totalFound += f.get();
        }
        clearFuture.get();

        System.out.println("Total non-null reads before/around clear: " + totalFound);
        System.out.println("Post-clear get(0): " + map.get(0));
        System.out.println("Post-clear get(" + (ENTRIES - 1) + "): " + map.get(ENTRIES - 1));

        pool.shutdown();
    }
}

import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class StripedMap<K, V> {

    private static final int N_LOCKS = 16;

    static class Node {
        final Object key;
        Object value;
        Node next;

        Node(Object key, Object value, Node next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    private final Object[] locks;
    private final Node[] buckets;

    public StripedMap(int bucketCount) {
        if (bucketCount <= 0) {
            throw new IllegalArgumentException("bucketCount must be > 0");
        }
        this.buckets = new Node[bucketCount];
        this.locks = new Object[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            this.locks[i] = new Object();
        }
    }

    public int bucketIndexForKey(Object key) {
        int h = (key == null) ? 0 : key.hashCode();
        h ^= (h >>> 16);
        return (h & 0x7fffffff) % buckets.length;
    }

    private int lockIndexForBucket(int bucketIndex) {
        return bucketIndex % N_LOCKS;
    }

    private boolean keysEqual(Object a, Object b) {
        return a == b || (a != null && a.equals(b));
    }

    public V get(K key) {
        int bi = bucketIndexForKey(key);
        int li = lockIndexForBucket(bi);
        synchronized (locks[li]) {
            Node e = buckets[bi];
            while (e != null) {
                if (keysEqual(key, e.key)) {
                    @SuppressWarnings("unchecked")
                    V val = (V) e.value;
                    return val;
                }
                e = e.next;
            }
        }
        return null;
    }

    public void put(K key, V value) {
        int bi = bucketIndexForKey(key);
        int li = lockIndexForBucket(bi);
        synchronized (locks[li]) {
            Node head = buckets[bi];
            for (Node p = head; p != null; p = p.next) {
                if (keysEqual(key, p.key)) {
                    p.value = value;
                    return;
                }
            }
            buckets[bi] = new Node(key, value, head);
        }
    }

    public void clear() {
        for (int li = 0; li < N_LOCKS; li++) {
            synchronized (locks[li]) {
                for (int bi = li; bi < buckets.length; bi += N_LOCKS) {
                    buckets[bi] = null;
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        final StripedMap<Integer, String> map = new StripedMap<>(64);
        final ExecutorService pool = Executors.newFixedThreadPool(4);

        final AtomicInteger readHits = new AtomicInteger(0);
        final AtomicInteger readMisses = new AtomicInteger(0);

        Runnable writer1 = () -> {
            for (int i = 0; i < 1000; i++) {
                map.put(i, "V" + i);
                if ((i & 127) == 0) {
                    Thread.yield();
                }
            }
        };

        Runnable writer2 = () -> {
            for (int i = 1000; i < 2000; i++) {
                map.put(i, "V" + i);
                if ((i & 127) == 0) {
                    Thread.yield();
                }
            }
        };

        Runnable reader = () -> {
            Random r = new Random();
            for (int i = 0; i < 3000; i++) {
                int k = r.nextInt(2000);
                String v = map.get(k);
                if (v != null) {
                    readHits.incrementAndGet();
                } else {
                    readMisses.incrementAndGet();
                }
                if ((i & 255) == 0) {
                    Thread.yield();
                }
            }
        };

        Runnable clearer = () -> {
            try {
                Thread.sleep(20);
            } catch (InterruptedException ignored) {
            }
            map.clear();
            // Add some entries after clear to show continued usability
            for (int i = 2000; i < 2050; i++) {
                map.put(i, "NV" + i);
            }
        };

        pool.submit(writer1);
        pool.submit(writer2);
        pool.submit(reader);
        pool.submit(clearer);

        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Read hits: " + readHits.get() + ", misses: " + readMisses.get());
        System.out.println("Sample lookups:");
        System.out.println("Key 42 -> " + map.get(42));
        System.out.println("Key 1042 -> " + map.get(1042));
        System.out.println("Key 2005 -> " + map.get(2005));
        System.out.println("Bucket index for key 42: " + map.bucketIndexForKey(42));
    }
}

import java.util.ArrayList;
