        V value;
        Node<K, V> next;

        Node(K key, V value, Node<K, V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    private final Node<K, V>[] buckets;
    private final Object[] locks;

    @SuppressWarnings("unchecked")
    public StripedMap(int numBuckets) {
        if (numBuckets <= 0) {
            throw new IllegalArgumentException("numBuckets must be > 0");
        }
        this.buckets = (Node<K, V>[]) new Node[numBuckets];
        this.locks = new Object[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            this.locks[i] = new Object();
        }
    }

    private int hashIndex(Object key) {
        int h = (key == null) ? 0 : key.hashCode();
        h ^= (h >>> 16);
        return (h & 0x7fffffff) % buckets.length;
    }

    public V get(K key) {
        int idx = hashIndex(key);
        Object lock = locks[idx % N_LOCKS];
        synchronized (lock) {
            Node<K, V> n = buckets[idx];
            while (n != null) {
                if (Objects.equals(n.key, key)) {
                    return n.value;
                }
                n = n.next;
            }
        }
        return null;
    }

    public void put(K key, V value) {
        int idx = hashIndex(key);
        Object lock = locks[idx % N_LOCKS];
        synchronized (lock) {
            Node<K, V> n = buckets[idx];
            while (n != null) {
                if (Objects.equals(n.key, key)) {
                    n.value = value;
                    return;
                }
                n = n.next;
            }
            buckets[idx] = new Node<>(key, value, buckets[idx]);
        }
    }

    public void clear() {
        for (int l = 0; l < N_LOCKS; l++) {
            synchronized (locks[l]) {
                for (int idx = l; idx < buckets.length; idx += N_LOCKS) {
                    buckets[idx] = null;
                }
            }
        }
    }

