import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

public class Main {
    public static void main(String[] args) {
        int totalPoints = 100;
        List<Point> points = new ArrayList<>(totalPoints);
        for (int i = 0; i < totalPoints; i++) {
            int x = i - 50;
            int y = (i * i) % 40 - 20;
            points.add(new Point(x, y));
        }

        int workers = 4;
        ExecutorService pool = Executors.newFixedThreadPool(workers);

        List<Future<List<Point>>> translatedFutures = new ArrayList<>();
        List<Future<List<Point>>> rotatedFutures = new ArrayList<>();
        List<Future<BBox>> bboxFutures = new ArrayList<>();

        int n = points.size();
        for (int t = 0; t < workers; t++) {
            final int start = t * n / workers;
            final int end = (t + 1) * n / workers;

            translatedFutures.add(pool.submit(new Callable<List<Point>>() {
                public List<Point> call() {
                    List<Point> out = new ArrayList<>(end - start);
                    for (int i = start; i < end; i++) {
                        Point p = points.get(i);
                        out.add(new Point(p.x + 5, p.y - 3));
                    }
                    return out;
                }
            }));

            rotatedFutures.add(pool.submit(new Callable<List<Point>>() {
                public List<Point> call() {
                    List<Point> out = new ArrayList<>(end - start);
                    for (int i = start; i < end; i++) {
                        Point p = points.get(i);
                        out.add(new Point(-p.y, p.x));
                    }
                    return out;
                }
            }));

            bboxFutures.add(pool.submit(new Callable<BBox>() {
                public BBox call() {
                    int minX = Integer.MAX_VALUE;
                    int minY = Integer.MAX_VALUE;
                    int maxX = Integer.MIN_VALUE;
                    int maxY = Integer.MIN_VALUE;
                    for (int i = start; i < end; i++) {
                        Point p = points.get(i);
                        if (p.x < minX) minX = p.x;
                        if (p.y < minY) minY = p.y;
                        if (p.x > maxX) maxX = p.x;
                        if (p.y > maxY) maxY = p.y;
                    }
                    return new BBox(minX, minY, maxX, maxY);
                }
            }));
        }

        List<Point> translated = new ArrayList<>(n);
        List<Point> rotated = new ArrayList<>(n);
        BBox globalBox = null;

        try {
            for (Future<List<Point>> f : translatedFutures) {
                translated.addAll(f.get());
            }
            for (Future<List<Point>> f : rotatedFutures) {
                rotated.addAll(f.get());
            }
            for (Future<BBox> f : bboxFutures) {
                BBox local = f.get();
                globalBox = (globalBox == null) ? local : globalBox.merge(local);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            pool.shutdownNow();
            return;
        } catch (ExecutionException e) {
            pool.shutdownNow();
            throw new RuntimeException(e.getCause());
        }

        pool.shutdown();
        try {
            pool.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Original points: " + points.size());
        System.out.println("Translated points: " + translated.size());
        System.out.println("Rotated points: " + rotated.size());
        System.out.println("First 5 translated: " + translated.subList(0, Math.min(5, translated.size())));
        System.out.println("First 5 rotated: " + rotated.subList(0, Math.min(5, rotated.size())));
        System.out.println("Bounding box: " + globalBox);
    }
}

