    BBox(int minX, int minY, int maxX, int maxY) {
        this.minX = minX;
        this.minY = minY;
        this.maxX = maxX;
        this.maxY = maxY;
    }
    BBox merge(BBox other) {
        int nMinX = Math.min(this.minX, other.minX);
        int nMinY = Math.min(this.minY, other.minY);
        int nMaxX = Math.max(this.maxX, other.maxX);
