        Callable<List<Point>> translateTask = new Callable<List<Point>>() {
            public List<Point> call() {
                List<Point> translated = new ArrayList<Point>(points.size());
                for (Point p : points) {
                    translated.add(new Point(p.x + 1, p.y - 1));
                }
                return translated;
            }
        };

        Callable<Bounds> boundsTask = new Callable<Bounds>() {
            public Bounds call() {
                int minX = Integer.MAX_VALUE;
                int maxX = Integer.MIN_VALUE;
                int minY = Integer.MAX_VALUE;
                int maxY = Integer.MIN_VALUE;
                for (Point p : points) {
