                    if (p.x > maxX) maxX = p.x;
                    if (p.y < minY) minY = p.y;
                    if (p.y > maxY) maxY = p.y;
                }
                return new Bounds(minX, maxX, minY, maxY);
            }
        };

        Future<Long> sumXFuture = pool.submit(sumXTask);
        Future<Long> sumYFuture = pool.submit(sumYTask);
