import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class Main {
    public static void main(String[] args) {
        int poolSize = 4;
        int totalPoints = 200000;
        int half = totalPoints / 2;

        ExecutorService executor = Executors.newFixedThreadPool(poolSize);
        try {
            Future<List<Point>> f1 = executor.submit(new PointGenerator(half, 42L));
            Future<List<Point>> f2 = executor.submit(new PointGenerator(totalPoints - half, 4242L));

            List<Point> list1 = getUnchecked(f1);
            List<Point> list2 = getUnchecked(f2);

            List<Point> all = new ArrayList<>(list1.size() + list2.size());
            all.addAll(list1);
            all.addAll(list2);
            List<Point> readOnly = Collections.unmodifiableList(all);

            Future<BoundingBox> bbF = executor.submit(new BoundingBoxTask(readOnly));
            Future<Long> sumF = executor.submit(new DistanceSumTask(readOnly));
            Future<QuadrantCount> qF = executor.submit(new QuadrantCountTask(readOnly));

            BoundingBox bb = getUnchecked(bbF);
            long sumSqDist = getUnchecked(sumF);
            QuadrantCount qc = getUnchecked(qF);

            System.out.println("Total points: " + readOnly.size());
            System.out.println("Bounding box: minX=" + bb.minX + ", maxX=" + bb.maxX + ", minY=" + bb.minY + ", maxY=" + bb.maxY);
            System.out.println("Sum of squared distances from origin: " + sumSqDist);
            System.out.println("Quadrants: Q1=" + qc.q1 + ", Q2=" + qc.q2 + ", Q3=" + qc.q3 + ", Q4=" + qc.q4 + ", OnAxes=" + qc.onAxes);
        } finally {
            executor.shutdown();
        }
    }

    private static <T> T getUnchecked(Future<T> future) {
        try {
            return future.get();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        } catch (ExecutionException e) {
            throw new RuntimeException(e.getCause());
        }
    }
}

