    }
}

class PointGenerator implements Callable<List<Point>> {
    private final int count;
    private final long seed;

    public PointGenerator(int count, long seed) {
        this.count = count;
        this.seed = seed;
    }

    public List<Point> call() {
        Random r = new Random(seed);
        List<Point> out = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            int x = r.nextInt(2001) - 1000;
            int y = r.nextInt(2001) - 1000;
            out.add(new Point(x, y));
        }
        return out;
    }
}

class BoundingBox {
    public final int minX;
    public final int maxX;
    public final int minY;
    public final int maxY;

    public BoundingBox(int minX, int maxX, int minY, int maxY) {
        this.minX = minX;
        this.maxX = maxX;
        this.minY = minY;
        this.maxY = maxY;
    }
}

class BoundingBoxTask implements Callable<BoundingBox> {
    private final List<Point> points;

    public BoundingBoxTask(List<Point> points) {
        this.points = points;
    }

    public BoundingBox call() {
        if (points.isEmpty()) {
            return new BoundingBox(0, 0, 0, 0);
        }
        int minX = points.get(0).x;
        int maxX = points.get(0).x;
        int minY = points.get(0).y;
        int maxY = points.get(0).y;
        for (int i = 1; i < points.size(); i++) {
            Point p = points.get(i);
            if (p.x < minX) minX = p.x;
            if (p.x > maxX) maxX = p.x;
            if (p.y < minY) minY = p.y;
            if (p.y > maxY) maxY = p.y;
        }
        return new BoundingBox(minX, maxX, minY, maxY);
    }
}

class DistanceSumTask implements Callable<Long> {
    private final List<Point> points;

    public DistanceSumTask(List<Point> points) {
        this.points = points;
    }

    public Long call() {
        long sum = 0L;
        for (Point p : points) {
            long dx = p.x;
            long dy = p.y;
            sum += dx * dx + dy * dy;
        }
        return sum;
    }
}

class QuadrantCount {
    public final int q1;
    public final int q2;
    public final int q3;
    public final int q4;
    public final int onAxes;

    public QuadrantCount(int q1, int q2, int q3, int q4, int onAxes) {
        this.q1 = q1;
        this.q2 = q2;
        this.q3 = q3;
        this.q4 = q4;
        this.onAxes = onAxes;
    }
}

class QuadrantCountTask implements Callable<QuadrantCount> {
    private final List<Point> points;

    public QuadrantCountTask(List<Point> points) {
        this.points = points;
    }

    public QuadrantCount call() {
        int q1 = 0, q2 = 0, q3 = 0, q4 = 0, onAxes = 0;
        for (Point p : points) {
            if (p.x == 0 || p.y == 0) {
                onAxes++;
            } else if (p.x > 0 && p.y > 0) {
                q1++;
            } else if (p.x < 0 && p.y > 0) {
                q2++;
            } else if (p.x < 0 && p.y < 0) {
                q3++;
            } else {
                q4++;
            }
        }
        return new QuadrantCount(q1, q2, q3, q4, onAxes);
        }
}

