import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.atomic.AtomicReference;

public class ImmutableCacheDemo {
    public static void main(String[] args) {
        AtomicReference<OneValueCache> cacheRef = new AtomicReference<>(new OneValueCache(null, null));
        ExecutorService executor = Executors.newFixedThreadPool(2);
        BigInteger n1 = new BigInteger("360");
        BigInteger n2 = new BigInteger("99991");

        Future<?> f1 = executor.submit(new FactorTask(n1, cacheRef));
        Future<?> f2 = executor.submit(new FactorTask(n2, cacheRef));

        for (int i = 0; i < 3; i++) {
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            BigInteger[] fromCache = cacheRef.get().getFactors(n1);
            if (fromCache != null) {
                System.out.println("Main thread cache hit for " + n1 + ": " + Arrays.toString(fromCache));
                break;
            } else {
                System.out.println("Main thread cache miss for " + n1);
            }
        }

        try {
            f1.get();
            f2.get();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (ExecutionException e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }

        BigInteger[] checkCopy = cacheRef.get().getFactors(n1);
        if (checkCopy != null) {
            if (checkCopy.length > 0) {
                checkCopy[0] = BigInteger.ZERO;
            }
            BigInteger[] recheck = cacheRef.get().getFactors(n1);
            System.out.println("After external modification attempt, cache still returns for " + n1 + ": " + Arrays.toString(recheck));
        }
    }
}

final class OneValueCache {
    private final BigInteger number;
    private final BigInteger[] factors;

    OneValueCache(BigInteger number, BigInteger[] factors) {
        this.number = number;
        this.factors = factors == null ? null : Arrays.copyOf(factors, factors.length);
    }

    BigInteger[] getFactors(BigInteger i) {
        if (number == null || i == null) return null;
        if (number.equals(i)) {
            return factors == null ? null : Arrays.copyOf(factors, factors.length);
        }
        return null;
    }
}

class Factorizer {
    static BigInteger[] factor(BigInteger n) {
        if (n == null) return new BigInteger[0];
        BigInteger num = n.abs();
        List<BigInteger> result = new ArrayList<>();
        if (num.compareTo(BigInteger.ONE) <= 0) {
            result.add(num);
            return result.toArray(new BigInteger[0]);
        }
        BigInteger two = BigInteger.valueOf(2);
        while (num.mod(two).equals(BigInteger.ZERO)) {
            result.add(two);
            num = num.divide(two);
        }
        BigInteger i = BigInteger.valueOf(3);
        while (i.multiply(i).compareTo(num) <= 0) {
            while (num.mod(i).equals(BigInteger.ZERO)) {
                result.add(i);
                num = num.divide(i);
            }
            i = i.add(two);
        }
        if (num.compareTo(BigInteger.ONE) > 0) {
            result.add(num);
        }
        return result.toArray(new BigInteger[0]);
    }
}

class FactorTask implements Runnable {
    private final BigInteger input;
    private final AtomicReference<OneValueCache> cacheRef;

    FactorTask(BigInteger input, AtomicReference<OneValueCache> cacheRef) {
        this.input = input;
        this.cacheRef = cacheRef;
    }

    public void run() {
        BigInteger[] factors = Factorizer.factor(this.input);
        cacheRef.set(new OneValueCache(this.input, factors));
        BigInteger[] fromCache = cacheRef.get().getFactors(this.input);
        System.out.println("Worker computed and cached for " + input + ": " + Arrays.toString(fromCache));
    }
}

