        ExecutorService executor = Executors.newFixedThreadPool(2);

        BigInteger n1 = new BigInteger("360");
        BigInteger n2 = new BigInteger("99991");

        Callable<ImmutableFactorCache> buildCache1 = new Callable<ImmutableFactorCache>() {
            public ImmutableFactorCache call() {
                BigInteger[] factors = Factorizer.factor(n1);
                return new ImmutableFactorCache(n1, factors);
            }
        };

        Callable<ImmutableFactorCache> buildCache2 = new Callable<ImmutableFactorCache>() {
            public ImmutableFactorCache call() {
                BigInteger[] factors = Factorizer.factor(n2);
                return new ImmutableFactorCache(n2, factors);
            }
        };

        Future<ImmutableFactorCache> f1 = executor.submit(buildCache1);
        Future<ImmutableFactorCache> f2 = executor.submit(buildCache2);

        ImmutableFactorCache cache1 = f1.get();
        ImmutableFactorCache cache2 = f2.get();

        Runnable readHitAndTestCopy = new Runnable() {
            public void run() {
                BigInteger[] hit = cache1.getFactorsIfCached(n1);
                System.out.println("Cache1 hit factors for " + n1 + ": " + Arrays.toString(hit));
                if (hit != null && hit.length > 0) {
                    hit[0] = BigInteger.valueOf(999); // attempt to mutate returned array
                }
                BigInteger[] hitAgain = cache1.getFactorsIfCached(n1);
                System.out.println("Cache1 factors after mutation attempt: " + Arrays.toString(hitAgain));
            }
        };

        Runnable readMiss = new Runnable() {
            public void run() {
                BigInteger[] miss = cache1.getFactorsIfCached(n2);
                System.out.println("Cache1 miss for " + n2 + ": " + (miss == null));
                BigInteger[] hitOnCache2 = cache2.getFactorsIfCached(n2);
