        r2.get();

        executor.shutdown();
    }
}

final class ImmutableFactorCache {
    private final BigInteger number;
    private final BigInteger[] factors;

    public ImmutableFactorCache(BigInteger number, BigInteger[] factors) {
        if (number == null || factors == null) {
            throw new IllegalArgumentException("Number and factors must not be null");
        }
        this.number = number;
        this.factors = Arrays.copyOf(factors, factors.length);
    }

    public BigInteger[] getFactorsIfCached(BigInteger input) {
        if (input == null || !input.equals(number)) {
            return null;
        }
        return Arrays.copyOf(factors, factors.length);
    }
}

class Factorizer {
    public static BigInteger[] factor(BigInteger n) {
        if (n == null) {
            throw new IllegalArgumentException("Input must not be null");
        }
        if (n.compareTo(BigInteger.TWO) < 0) {
            return new BigInteger[] { n };
        }
        List<BigInteger> list = new ArrayList<BigInteger>();
        BigInteger two = BigInteger.valueOf(2);

        while (n.mod(two).equals(BigInteger.ZERO)) {
            list.add(two);
            n = n.divide(two);
        }

        BigInteger i = BigInteger.valueOf(3);
        while (i.multiply(i).compareTo(n) <= 0) {
            while (n.mod(i).equals(BigInteger.ZERO)) {
                list.add(i);
                n = n.divide(i);
            }
            i = i.add(two);
        }

        if (n.compareTo(BigInteger.ONE) > 0) {
            list.add(n);
        }

        return list.toArray(new BigInteger[list.size()]);
    }
}

