import java.util.*;
import java.util.concurrent.*;

/**
 * Entry point demonstrating the ImproveList with concurrent operations.
 */
public class Main {
    public static void main(String[] args) {
        ImproveList<Integer> numbers = new ImproveList<>(new ArrayList<Integer>());

        ExecutorService pool = Executors.newFixedThreadPool(2);

        // Task 1: Attempt to put integers 0..49, with duplicates across 0..24 range.
        pool.submit(new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 50; i++) {
                    numbers.putIfAbsent(i % 25);
                    try {
                        Thread.sleep(2);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
            }
        });

        // Task 2: Mix adds and removes to exercise other mutative methods.
        pool.submit(new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 50; i++) {
                    if ((i & 1) == 0) {
                        numbers.add(i);
                    } else {
                        numbers.remove(Integer.valueOf(i - 1));
                    }
                    if (i % 10 == 0) {
                        numbers.addAll(Arrays.asList(-i, -i - 1));
                        numbers.removeAll(Arrays.asList(-i - 1));
                    }
                    try {
                        Thread.sleep(1);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
            }
        });

        pool.shutdown();
        try {
            pool.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        // Safely iterate and display final state.
        List<Integer> snapshot;
        synchronized (numbers) {
            snapshot = new ArrayList<>(numbers);
            System.out.println("Final list size: " + numbers.size());
        }
        System.out.println("Final contents: " + snapshot);
    }
}

/**
 * A thread-safe List wrapper that provides a putIfAbsent operation.
 * All mutative operations are synchronized to preserve atomicity.
 * Iteration must be performed within a synchronized block on this list instance:
 *
 * synchronized (improveList) {
 *     Iterator<E> it = improveList.iterator();
 *     while (it.hasNext()) { ... }
 * }
 *
 * @param <E> element type
 */
class ImproveList<E> implements List<E> {
    private final List<E> list;
    private final Object lock;

    /**
     * Creates a new ImproveList that wraps the given list.
     * @param list the underlying list to wrap (must not be null)
     */
    public ImproveList(List<E> list) {
        if (list == null) {
            throw new NullPointerException("list");
        }
        this.list = list;
        this.lock = this; // use wrapper instance as mutex
    }

    // Internal constructor for sharing the same mutex with sublists
    private ImproveList(List<E> list, Object sharedLock) {
        this.list = list;
        this.lock = sharedLock;
    }

    /**
     * Atomically adds the specified element to this list if it is not already present.
     * @param e element to add if absent
     * @return true if the element was added, false if it was already present
     */
    public boolean putIfAbsent(E e) {
        synchronized (lock) {
            if (!list.contains(e)) {
                return list.add(e);
            }
            return false;
        }
    }

    @Override
    public int size() {
        synchronized (lock) {
            return list.size();
        }
    }

    @Override
    public boolean isEmpty() {
        synchronized (lock) {
            return list.isEmpty();
        }
    }

    @Override
    public boolean contains(Object o) {
        synchronized (lock) {
            return list.contains(o);
        }
    }

    @Override
    public Iterator<E> iterator() {
        // Must be used within synchronized block by the caller.
        return list.iterator();
    }

    @Override
    public Object[] toArray() {
        synchronized (lock) {
            return list.toArray();
        }
    }

    @Override
    public <T> T[] toArray(T[] a) {
        synchronized (lock) {
            return list.toArray(a);
        }
    }

    @Override
    public boolean add(E e) {
        synchronized (lock) {
            return list.add(e);
        }
    }

    @Override
    public boolean remove(Object o) {
        synchronized (lock) {
            return list.remove(o);
        }
    }

    @Override
    public boolean containsAll(Collection<?> c) {
        synchronized (lock) {
            return list.containsAll(c);
        }
    }

    @Override
    public boolean addAll(Collection<? extends E> c) {
        synchronized (lock) {
            return list.addAll(c);
        }
    }

    @Override
    public boolean addAll(int index, Collection<? extends E> c) {
        synchronized (lock) {
            return list.addAll(index, c);
        }
    }

    @Override
    public boolean removeAll(Collection<?> c) {
        synchronized (lock) {
            return list.removeAll(c);
        }
    }

    @Override
    public boolean retainAll(Collection<?> c) {
        synchronized (lock) {
            return list.retainAll(c);
        }
    }

    @Override
    public void clear() {
        synchronized (lock) {
            list.clear();
        }
    }

    @Override
    public E get(int index) {
        synchronized (lock) {
            return list.get(index);
        }
    }

    @Override
    public E set(int index, E element) {
        synchronized (lock) {
            return list.set(index, element);
        }
    }

    @Override
    public void add(int index, E element) {
        synchronized (lock) {
            list.add(index, element);
        }
    }

    @Override
    public E remove(int index) {
        synchronized (lock) {
            return list.remove(index);
        }
    }

    @Override
    public int indexOf(Object o) {
        synchronized (lock) {
            return list.indexOf(o);
        }
    }

    @Override
    public int lastIndexOf(Object o) {
        synchronized (lock) {
            return list.lastIndexOf(o);
        }
    }

    @Override
    public ListIterator<E> listIterator() {
        // Must be used within synchronized block by the caller.
        return list.listIterator();
    }

    @Override
    public ListIterator<E> listIterator(int index) {
        // Must be used within synchronized block by the caller.
        return list.listIterator(index);
    }

    @Override
    public List<E> subList(int fromIndex, int toIndex) {
        synchronized (lock) {
            return new ImproveList<E>(list.subList(fromIndex, toIndex), lock);
        }
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        synchronized (lock) {
            return list.equals(o);
        }
    }

    @Override
    public int hashCode() {
        synchronized (lock) {
            return list.hashCode();
        }
    }
