 */
public class Main {
    public static void main(String[] args) throws Exception {
        ImproveList<Integer> list = new ImproveList<>(new ArrayList<Integer>());

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable taskA = () -> {
            for (int i = 0; i < 1000; i++) {
                list.putIfAbsent(i);
            }
        };

