            for (int i = 500; i < 1500; i++) {
                list.putIfAbsent(i);
            }
        };

        pool.submit(taskA);
        pool.submit(taskB);
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);

        System.out.println("After concurrent putIfAbsent: size=" + list.size() + " (expected 1500)");

        List<Integer> last100 = list.subList(1400, 1500);
        last100.clear();

        System.out.println("After clearing tail subList: size=" + list.size() + " (expected 1400)");

        List<Integer> toAddBack = new ArrayList<>();
        for (int i = 1400; i < 1500; i++) {
            toAddBack.add(i);
        }
        list.addAll(toAddBack);

        System.out.println("After adding back tail: size=" + list.size() + " (expected 1500)");

        int distinctCount;
        synchronized (list) {
            distinctCount = new HashSet<>(list).size();
        }
        System.out.println("Distinct elements count: " + distinctCount + " (expected 1500)");

        boolean containsAll;
        synchronized (list) {
            List<Integer> check = new ArrayList<>();
            for (int i = 0; i < 1500; i++) {
                check.add(i);
            }
            containsAll = list.containsAll(check);
        }
