    public static void main(String[] args) {
        ImproveList<Integer> safeList = new ImproveList<Integer>(new ArrayList<Integer>());

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable producerA = new Runnable() {
            public void run() {
                for (int i = 0; i < 200; i++) {
                    int val = i % 50; // many duplicates intentionally
                    safeList.putIfAbsent(val);
                    if (i % 20 == 0) {
                        safeList.add(val + 1000); // additional mutations
                    }
                }
            }
        };

        Runnable producerB = new Runnable() {
            public void run() {
                for (int i = 0; i < 200; i++) {
                    int val = (i * 3) % 50;
                    safeList.putIfAbsent(val);
                    if (i % 15 == 0) {
                        safeList.remove(Integer.valueOf(val)); // occasional removals
                    }
                }
            }
        };

        Future<?> f1 = pool.submit(producerA);
        Future<?> f2 = pool.submit(producerB);

        try {
            f1.get();
            f2.get();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (ExecutionException e) {
            e.printStackTrace();
        } finally {
            pool.shutdown();
        }

        // Display results
        System.out.println("Final size: " + safeList.size());
        synchronized (safeList) { // External synchronization for safe iteration
            System.out.println("Contents: " + new ArrayList<Integer>(safeList));
        }
    }
