public class Main {

    public static void main(String[] args) {
        Account alice = new BasicAccount("Alice", new SimpleDollarAmount(100000)); // $1000.00
        Account bob = new BasicAccount("Bob", new SimpleDollarAmount(100000));    // $1000.00

        MoneyTransferService service = new MoneyTransferService();

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable task1 = new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 1000; i++) {
                    try {
                        service.transferMoney(alice, bob, new SimpleDollarAmount(100)); // $1.00
                    } catch (InsufficientFundsException e) {
                        System.out.println("Task1 failed: " + e.getMessage());
                    }
                }
            }
        };

        Runnable task2 = new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 1000; i++) {
                    try {
                        service.transferMoney(bob, alice, new SimpleDollarAmount(100)); // $1.00
                    } catch (InsufficientFundsException e) {
                        System.out.println("Task2 failed: " + e.getMessage());
                    }
                }
            }
