interface DollarAmount extends Comparable<DollarAmount> {
    DollarAmount add(DollarAmount other);
    DollarAmount subtract(DollarAmount other);
    long toCents();
}

interface Account {
    DollarAmount getBalance();
    void debit(DollarAmount amount);
    void credit(DollarAmount amount);
    String getName();
}

class InsufficientFundsException extends Exception {
    public InsufficientFundsException(String message) {
        super(message);
    }
}

class SimpleDollarAmount implements DollarAmount {
    private final long cents;

    public SimpleDollarAmount(long cents) {
        if (cents < 0) {
            throw new IllegalArgumentException("Amount cannot be negative");
        }
        this.cents = cents;
    }

    @Override
    public DollarAmount add(DollarAmount other) {
        return new SimpleDollarAmount(this.cents + other.toCents());
    }

    @Override
    public DollarAmount subtract(DollarAmount other) {
        long result = this.cents - other.toCents();
        if (result < 0) {
            throw new IllegalArgumentException("Resulting amount cannot be negative");
        }
        return new SimpleDollarAmount(result);
    }

    @Override
    public int compareTo(DollarAmount other) {
        long diff = this.cents - other.toCents();
        return diff < 0 ? -1 : (diff > 0 ? 1 : 0);
    }

    @Override
    public long toCents() {
        return cents;
    }

    @Override
    public String toString() {
        boolean negative = cents < 0;
        long abs = Math.abs(cents);
        long dollars = abs / 100;
        long rem = abs % 100;
        return (negative ? "-" : "") + "$" + dollars + "." + (rem < 10 ? "0" : "") + rem;
    }

    @Override
    public boolean equals(Object obj) {
        if (!(obj instanceof SimpleDollarAmount)) return false;
        return this.cents == ((SimpleDollarAmount) obj).cents;
    }

    @Override
    public int hashCode() {
        return Long.hashCode(cents);
    }
}

class BasicAccount implements Account {
    private final String name;
    private DollarAmount balance;

    public BasicAccount(String name, DollarAmount openingBalance) {
        if (name == null || openingBalance == null) {
            throw new IllegalArgumentException("Name and opening balance must not be null");
        }
        this.name = name;
        this.balance = openingBalance;
    }

    @Override
    public DollarAmount getBalance() {
        return balance;
    }

    @Override
    public void debit(DollarAmount amount) {
        balance = balance.subtract(amount);
    }

    @Override
    public void credit(DollarAmount amount) {
        balance = balance.add(amount);
    }

    @Override
    public String getName() {
        return name;
    }
}

class TransferHelper {
    public void transfer(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
        if (from.getBalance().compareTo(amount) < 0) {
            throw new InsufficientFundsException("Insufficient funds in account " + from.getName());
        }
        from.debit(amount);
        to.credit(amount);
    }
}

class MoneyTransferService {
    private static final Object tieLock = new Object();
    private final TransferHelper helper = new TransferHelper();

    public void transferMoney(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
        int fromHash = System.identityHashCode(from);
        int toHash = System.identityHashCode(to);

        if (fromHash < toHash) {
            synchronized (from) {
                synchronized (to) {
                    helper.transfer(from, to, amount);
                }
            }
        } else if (fromHash > toHash) {
            synchronized (to) {
                synchronized (from) {
                    helper.transfer(from, to, amount);
                }
            }
        } else {
            synchronized (tieLock) {
                synchronized (from) {
                    synchronized (to) {
                        helper.transfer(from, to, amount);
                    }
                }
            }
        }
    }
}

