    private volatile long balanceCents;

    public SimpleAccount(String name, DollarAmount initial) {
        this.name = name;
        this.balanceCents = initial.toCents();
    }

    @Override
    public DollarAmount getBalance() {
        return new SimpleDollarAmount(balanceCents);
    }

    @Override
    public void debit(DollarAmount amount) {
        long delta = amount.toCents();
        long newBal = balanceCents - delta;
        if (newBal < 0) {
            throw new IllegalArgumentException("Debit would overdraw");
        }
        balanceCents = newBal;
    }

    @Override
    public void credit(DollarAmount amount) {
        long delta = amount.toCents();
        long newBal = balanceCents + delta;
        if (newBal < 0) {
            throw new ArithmeticException("Overflow");
        }
        balanceCents = newBal;
    }

    @Override
