public class TreiberStackDemo {
    static class TreiberStack<T> {
        private static final class Node<E> {
            final E item;
            final Node<E> next;
            Node(E item, Node<E> next) {
                this.item = item;
                this.next = next;
            }
        }

        private final java.util.concurrent.atomic.AtomicReference<Node<T>> top =
                new java.util.concurrent.atomic.AtomicReference<>(null);

        public void push(T item) {
            Node<T> current;
            Node<T> newNode;
            do {
                current = top.get();
                newNode = new Node<>(item, current);
            } while (!top.compareAndSet(current, newNode));
        }

        public T pop() {
            Node<T> current;
            Node<T> next;
            do {
                current = top.get();
                if (current == null) return null;
                next = current.next;
            } while (!top.compareAndSet(current, next));
            return current.item;
        }

        public boolean isEmpty() {
            return top.get() == null;
        }
    }

