import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

public class Secrets {
    public static volatile Set<Secret> knownSecrets;

    public static void initialize() {
        synchronized (Secrets.class) {
            if (knownSecrets == null) {
                knownSecrets = new HashSet<Secret>();
            }
        }
    }

    public static void addSecret(Secret s) {
        Set<Secret> ks = knownSecrets;
        if (ks == null) {
            throw new IllegalStateException("Secrets not initialized");
        }
        synchronized (ks) {
            ks.add(s);
        }
    }

    public static int size() {
        Set<Secret> ks = knownSecrets;
        if (ks == null) {
            return 0;
        }
        synchronized (ks) {
            return ks.size();
        }
    }

    public static void main(String[] args) throws Exception {
        initialize();
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Runnable task = () -> {
            for (int i = 0; i < 1000; i++) {
                addSecret(new Secret());
            }
        };
        Future<?> f1 = executor.submit(task);
        Future<?> f2 = executor.submit(task);
        f1.get();
        f2.get();
        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);
