import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingVehicleTracker {

    // Immutable value object for locations (x, y)
    public static final class Point {
        private final int x;
        private final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() { return x; }

        public int getY() { return y; }

        public String toString() {
            return "(" + x + "," + y + ")";
        }
    }

    // Backing store using a ConcurrentHashMap for thread-safe access
    private final ConcurrentHashMap<String, Point> locations;

    // Initialize with a map of vehicle IDs to initial locations
    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        if (initialLocations == null) {
            throw new IllegalArgumentException("initialLocations must not be null");
        }
        this.locations = new ConcurrentHashMap<>(initialLocations);
    }

    // Get the current location for a vehicle ID (null if not present)
    public Point getLocation(String vehicleId) {
        if (vehicleId == null) return null;
        return locations.get(vehicleId);
    }

    // Update the location of an existing vehicle; fails if ID is unknown
    public void setLocation(String vehicleId, int x, int y) {
        if (vehicleId == null) {
            throw new IllegalArgumentException("vehicleId must not be null");
        }
        Point previous = locations.replace(vehicleId, new Point(x, y));
        if (previous == null) {
            throw new IllegalArgumentException("Unknown vehicle ID: " + vehicleId);
        }
    }

    // Live unmodifiable view backed by the original data; changes will be visible over time
    public Map<String, Point> getLocationsLive() {
        return Collections.unmodifiableMap(locations);
    }

    // Static unmodifiable snapshot of the current state
    public Map<String, Point> getLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<String, Point>(locations));
    }

    // Simple demo using at most 2 worker threads (+ main = 3 total)
    public static void main(String[] args) {
        Map<String, Point> initial = new HashMap<String, Point>();
        initial.put("car-1", new Point(0, 0));
        initial.put("car-2", new Point(10, 10));

        final DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initial);

        System.out.println("Initial snapshot: " + tracker.getLocationsSnapshot());

        ExecutorService pool = Executors.newFixedThreadPool(2); // 2 worker threads

        Runnable writer = new Runnable() {
            public void run() {
                for (int i = 1; i <= 5; i++) {
                    tracker.setLocation("car-1", i, i);
                    tracker.setLocation("car-2", i * 10, i * 10);
                    System.out.println("Writer updated: car-1=" + tracker.getLocation("car-1")
                            + ", car-2=" + tracker.getLocation("car-2"));
                    try {
                        Thread.sleep(100);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
                try {
                    tracker.setLocation("car-404", 1, 1);
                } catch (IllegalArgumentException ex) {
                    System.out.println("Expected failure updating unknown ID: " + ex.getMessage());
                }
            }
        };

        Runnable reader = new Runnable() {
            public void run() {
                for (int i = 1; i <= 5; i++) {
                    Map<String, Point> snap = tracker.getLocationsSnapshot();
                    System.out.println("Reader snapshot: " + snap);

                    Map<String, Point> live = tracker.getLocationsLive();
                    System.out.println("Reader live view: " + live);

                    try {
                        Thread.sleep(120);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
            }
        };

        pool.submit(writer);
        pool.submit(reader);

        pool.shutdown();
        try {
            if (!pool.awaitTermination(5, TimeUnit.SECONDS)) {
                pool.shutdownNow();
            }
        } catch (InterruptedException e) {
            pool.shutdownNow();
            Thread.currentThread().interrupt();
        }

        System.out.println("Final snapshot: " + tracker.getLocationsSnapshot());
    }
}

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingVehicleTracker {

    private final ConcurrentHashMap<String, Location> locations;
    private final Map<String, Location> unmodifiableLiveView;

    public DelegatingVehicleTracker(Map<String, Location> initialLocations) {
        if (initialLocations == null) {
            throw new NullPointerException("initialLocations must not be null");
        }
        this.locations = new ConcurrentHashMap<>(initialLocations);
        this.unmodifiableLiveView = Collections.unmodifiableMap(this.locations);
    }

    // Returns the immutable Location for a vehicle, or null if not present.
    public Location getLocation(String vehicleId) {
        if (vehicleId == null) {
            return null;
        }
        return locations.get(vehicleId);
    }

    // Updates the location only if the vehicleId already exists. Returns true if updated.
    public boolean setLocation(String vehicleId, double latitude, double longitude) {
        if (vehicleId == null) {
            throw new NullPointerException("vehicleId must not be null");
        }
        Location newLoc = new Location(latitude, longitude);
        return locations.replace(vehicleId, newLoc) != null;
    }

    // Returns a live unmodifiable view backed by the underlying ConcurrentHashMap.
    public Map<String, Location> getAllLocationsView() {
        return unmodifiableLiveView;
    }

    // Returns a static, unmodifiable snapshot of the current state.
    public Map<String, Location> getAllLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    public static void main(String[] args) {
        Map<String, Location> initial = new HashMap<>();
        initial.put("truck-1", new Location(34.0522, -118.2437));
        initial.put("van-2", new Location(40.7128, -74.0060));
        initial.put("car-3", new Location(37.7749, -122.4194));

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initial);

        System.out.println("Initial snapshot: " + tracker.getAllLocationsSnapshot());

        // Use at most 2 additional threads beyond the main thread.
        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable updater = () -> {
            try {
                for (int i = 0; i < 5; i++) {
                    boolean u1 = tracker.setLocation("truck-1", 34.0522 + i * 0.01, -118.2437 - i * 0.01);
                    boolean u2 = tracker.setLocation("van-2", 40.7128 + i * 0.02, -74.0060 + i * 0.02);
                    boolean u3 = tracker.setLocation("unknown-9", 0.0, 0.0); // should fail
                    System.out.println("[Updater] truck-1 updated=" + u1 + ", van-2 updated=" + u2 + ", unknown-9 updated=" + u3);
                    Thread.sleep(120);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable reader = () -> {
            try {
                for (int i = 0; i < 5; i++) {
                    Map<String, Location> live = tracker.getAllLocationsView();
                    Map<String, Location> snapshot = tracker.getAllLocationsSnapshot();
                    System.out.println("[Reader] live view: " + live);
                    System.out.println("[Reader] snapshot:  " + snapshot);

                    // Demonstrate that live view is unmodifiable (will throw)
                    if (i == 0) {
                        try {
                            live.put("new-vehicle", new Location(1.0, 1.0));
                        } catch (UnsupportedOperationException ex) {
                            System.out.println("[Reader] Live view is unmodifiable as expected.");
                        }
                    }

                    Thread.sleep(100);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        pool.submit(updater);
        pool.submit(reader);

        pool.shutdown();
        try {
            if (!pool.awaitTermination(10, TimeUnit.SECONDS)) {
                System.out.println("Tasks did not finish in time.");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        // Final state from the main thread
        System.out.println("Final live view: " + tracker.getAllLocationsView());
