    }
}

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingVehicleTracker {

    private final ConcurrentMap<String, Point> locations;
    private final Map<String, Point> unmodifiableLiveView;

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        this.locations = new ConcurrentHashMap<>();
        if (initialLocations != null) {
            for (Map.Entry<String, Point> e : initialLocations.entrySet()) {
                if (e.getKey() != null && e.getValue() != null) {
                    this.locations.put(e.getKey(), e.getValue());
                }
            }
        }
        this.unmodifiableLiveView = Collections.unmodifiableMap(this.locations);
    }

    // Returns the location (immutable) for a specific vehicle ID, or null if not present.
    public Point getLocation(String vehicleId) {
        return locations.get(vehicleId);
    }

    // Updates the location only if the vehicle already exists. Returns true if updated, false otherwise.
    public boolean setLocation(String vehicleId, int x, int y) {
        return locations.replace(vehicleId, new Point(x, y)) != null;
    }

    // Live unmodifiable view backed by the underlying ConcurrentHashMap.
    public Map<String, Point> getLocationsLive() {
        return unmodifiableLiveView;
    }

    // Static snapshot of current state as an unmodifiable map.
    public Map<String, Point> getLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, Point> initial = new HashMap<>();
        initial.put("car-1", new Point(0, 0));
        initial.put("car-2", new Point(10, 10));
        initial.put("car-3", new Point(-5, 15));

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initial);

        // Use at most 2 threads in the pool + the main thread = 3 total threads.
        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable updater = new Runnable() {
            public void run() {
                try {
                    for (int i = 0; i < 6; i++) {
                        boolean ok1 = tracker.setLocation("car-1", i, i);
                        boolean ok2 = tracker.setLocation("car-2", i * 2, i * 3);
                        boolean ok3 = tracker.setLocation("unknown", 99, 99); // should be false
                        System.out.println("[Updater] car-1 updated=" + ok1 + ", car-2 updated=" + ok2 + ", unknown updated=" + ok3);
                        TimeUnit.MILLISECONDS.sleep(120);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        Runnable reader = new Runnable() {
            public void run() {
                try {
                    for (int i = 0; i < 6; i++) {
                        Point p1 = tracker.getLocation("car-1");
                        Map<String, Point> live = tracker.getLocationsLive();
                        Map<String, Point> snap = tracker.getLocationsSnapshot();

                        System.out.println("[Reader] car-1=" + p1 + " | live=" + live + " | snapshot=" + snap);

                        // Demonstrate that returned maps are unmodifiable.
                        try {
                            live.put("new-car", new Point(100, 100));
                        } catch (UnsupportedOperationException ex) {
                            System.out.println("[Reader] Live view is unmodifiable as expected.");
                        }
                        try {
                            snap.put("new-car", new Point(100, 100));
                        } catch (UnsupportedOperationException ex) {
                            System.out.println("[Reader] Snapshot view is unmodifiable as expected.");
                        }

                        TimeUnit.MILLISECONDS.sleep(100);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        pool.submit(updater);
        pool.submit(reader);

        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);

        System.out.println("[Main] Final live: " + tracker.getLocationsLive());
        System.out.println("[Main] Final snapshot: " + tracker.getLocationsSnapshot());
    }
}

