import java.util.*;
import java.util.concurrent.*;

public class ArkApp {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        try {
            Callable<List<Animal>> c1 = new AnimalBatchBuilder(Arrays.asList(
                    new Animal(Species.LION, Gender.MALE),
                    new Animal(Species.LION, Gender.FEMALE),
                    new Animal(Species.DOG, Gender.MALE),
                    new Animal(Species.DOG, Gender.FEMALE),
                    new Animal(Species.CAT, Gender.FEMALE),
                    new Animal(Species.HORSE, Gender.MALE)
            ));
            Callable<List<Animal>> c2 = new AnimalBatchBuilder(Arrays.asList(
                    new Animal(Species.CAT, Gender.MALE),
                    new Animal(Species.TIGER, Gender.MALE),
                    new Animal(Species.TIGER, Gender.FEMALE),
                    new Animal(Species.BEAR, Gender.MALE),
                    new Animal(Species.BEAR, Gender.FEMALE),
                    new Animal(Species.HORSE, Gender.FEMALE)
            ));
            Future<List<Animal>> f1 = pool.submit(c1);
            Future<List<Animal>> f2 = pool.submit(c2);
            List<Animal> candidates = new ArrayList<>();
            candidates.addAll(f1.get());
            candidates.addAll(f2.get());
            int pairs = loadTheArk(candidates);
            System.out.println("Total pairs loaded: " + pairs);
        } finally {
            pool.shutdown();
        }
    }

    public static int loadTheArk(Collection<Animal> candidates) {
        List<Animal> animals = new ArrayList<>(candidates);
        Comparator<Animal> comp = new Comparator<Animal>() {
            @Override
            public int compare(Animal a, Animal b) {
                int s = a.getSpecies().compareTo(b.getSpecies());
                if (s != 0) return s;
                return a.getGender().compareTo(b.getGender());
            }
        };
        Collections.sort(animals, comp);
        Ark ark = new Ark();
        Deque<Animal> waitingMales = new ArrayDeque<>();
        Deque<Animal> waitingFemales = new ArrayDeque<>();
        Species current = null;
        int pairs = 0;
        for (Animal a : animals) {
            if (current != a.getSpecies()) {
                waitingMales.clear();
                waitingFemales.clear();
                current = a.getSpecies();
            }
            if (a.getGender() == Gender.MALE) {
                if (!waitingFemales.isEmpty()) {
                    Animal f = waitingFemales.pop();
                    ark.load(new AnimalPair(f, a));
                    pairs++;
                } else {
                    waitingMales.push(a);
                }
            } else {
                if (!waitingMales.isEmpty()) {
                    Animal m = waitingMales.pop();
                    ark.load(new AnimalPair(m, a));
                    pairs++;
                } else {
                    waitingFemales.push(a);
                }
            }
        }
        System.out.println("Pairs loaded onto the ark:");
        for (AnimalPair p : ark.getPairs()) {
            System.out.println(p);
        }
        return pairs;
    }
}

