import java.util.*;
import java.util.concurrent.*;

public class ArkApp {

    public static void main(String[] args) throws Exception {
        final List<Animal> candidates = generateCandidates();

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Callable<Integer> loaderTask = new Callable<Integer>() {
            public Integer call() {
                return loadTheArk(candidates);
            }
        };

        Callable<String> analyzerTask = new Callable<String>() {
            public String call() {
                Map<Species, Map<Gender, Long>> stats = analyze(candidates);
                StringBuilder sb = new StringBuilder();
                for (Species s : Species.values()) {
                    Map<Gender, Long> byGender = stats.get(s);
                    long males = byGender.getOrDefault(Gender.MALE, 0L);
                    long females = byGender.getOrDefault(Gender.FEMALE, 0L);
                    sb.append(s.name()).append(": M=").append(males).append(", F=").append(females).append('\n');
                }
                return sb.toString();
            }
        };

        Future<Integer> pairsFuture = pool.submit(loaderTask);
        Future<String> analysisFuture = pool.submit(analyzerTask);

        int pairsLoaded = pairsFuture.get();
        String analysisReport = analysisFuture.get();

        pool.shutdown();

        System.out.println("Pairs loaded onto the ark: " + pairsLoaded);
        System.out.println("Candidate distribution by species and gender:");
        System.out.print(analysisReport);
    }

    public static int loadTheArk(Collection<Animal> candidates) {
        List<Animal> animals = new ArrayList<>(candidates);

        Comparator<Animal> bySpeciesThenGender = new Comparator<Animal>() {
            public int compare(Animal a, Animal b) {
                int c = a.getSpecies().compareTo(b.getSpecies());
                if (c != 0) return c;
                return a.getGender().compareTo(b.getGender());
            }
        };

        Collections.sort(animals, bySpeciesThenGender);

        Ark ark = new Ark();
        Animal prev = null;

        for (Animal current : animals) {
            if (prev == null) {
                prev = current;
                continue;
            }
            if (prev.getSpecies() == current.getSpecies() && prev.getGender() != current.getGender()) {
                ark.load(new AnimalPair(prev, current));
                prev = null;
            } else {
                if (prev.getSpecies() != current.getSpecies()) {
                    prev = current;
                }
            }
        }

        return ark.size();
    }

    private static Map<Species, Map<Gender, Long>> analyze(Collection<Animal> candidates) {
        Map<Species, Map<Gender, Long>> result = new EnumMap<>(Species.class);
        for (Species s : Species.values()) {
            result.put(s, new EnumMap<Gender, Long>(Gender.class));
        }
        for (Animal a : candidates) {
            Map<Gender, Long> inner = result.get(a.getSpecies());
            Long count = inner.get(a.getGender());
            inner.put(a.getGender(), count == null ? 1L : count + 1L);
        }
        return result;
    }

    private static List<Animal> generateCandidates() {
        List<Animal> list = new ArrayList<>();
        Random rnd = new Random(12345L);
        for (Species s : Species.values()) {
            int count = 12 + rnd.nextInt(9); // 12..20
            for (int i = 0; i < count; i++) {
                Gender g = rnd.nextBoolean() ? Gender.MALE : Gender.FEMALE;
                list.add(new Animal(s, g));
            }
        }
        return list;
    }
}

