import java.util.concurrent.CountDownLatch;

public class PerformanceTimingTool {
    private static final int MAX_WORKERS = 1;
    private static volatile long SINK;

    public static void main(String[] args) {
        int iterations = args.length > 0 ? parsePositiveInt(args[0], 200000) : 200000;
        int nThreads = args.length > 1 ? parsePositiveInt(args[1], 1) : 1;
        if (nThreads > MAX_WORKERS) {
            nThreads = MAX_WORKERS;
        }
        Runnable task = () -> {
            long acc = 0;
            for (int i = 0; i < iterations; i++) {
                acc ^= (i * 2654435761L) + Long.rotateLeft(acc, 13);
                acc += (acc << 3) ^ (acc >>> 11);
            }
            SINK = acc;
        };
        long nanos = timeTasks(nThreads, task);
        System.out.println("Threads: " + nThreads);
        System.out.println("Iterations per task: " + iterations);
        System.out.println("Elapsed (ns): " + nanos);
        System.out.println("Elapsed (ms): " + (nanos / 1_000_000.0));
        System.out.println("Blackhole: " + SINK);
    }

    public static long timeTasks(int nThreads, Runnable task) {
        if (nThreads < 1 || nThreads > MAX_WORKERS) {
            throw new IllegalArgumentException("nThreads must be between 1 and " + MAX_WORKERS);
        }
        CountDownLatch startGate = new CountDownLatch(1);
        CountDownLatch endGate = new CountDownLatch(nThreads);
        List<Thread> threads = new ArrayList<>(nThreads);
        for (int i = 0; i < nThreads; i++) {
            Thread t = new Thread(() -> {
                boolean interrupted = false;
                try {
                    try {
                        startGate.await();
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        interrupted = true;
                    }
                    if (!interrupted) {
                        try {
                            task.run();
                        } catch (Throwable ignored) {
                        }
                    }
                } finally {
                    endGate.countDown();
                }
            }, "worker-" + i);
            t.start();
            threads.add(t);
        }
        long start = System.nanoTime();
        startGate.countDown();
        boolean restoreInterrupt = false;
        try {
            endGate.await();
        } catch (InterruptedException e) {
            restoreInterrupt = true;
        }
        long end = System.nanoTime();
        if (restoreInterrupt) {
            Thread.currentThread().interrupt();
        }
        return end - start;
    }

    private static int parsePositiveInt(String s, int fallback) {
        try {
            int v = Integer.parseInt(s);
