import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Random;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class PublishingVehicleTracker {

    private final ConcurrentMap<String, SafePoint> locations;

    public PublishingVehicleTracker(Map<String, SafePoint> initial) {
        this.locations = new ConcurrentHashMap<>();
        if (initial != null) {
            for (Map.Entry<String, SafePoint> e : initial.entrySet()) {
                if (e.getKey() != null && e.getValue() != null) {
                    this.locations.put(e.getKey(), new SafePoint(e.getValue()));
                }
            }
        }
    }

    public Map<String, SafePoint> getLocations() {
        Map<String, SafePoint> copy = new HashMap<>();
        for (Map.Entry<String, SafePoint> e : locations.entrySet()) {
            copy.put(e.getKey(), new SafePoint(e.getValue()));
        }
        return Collections.unmodifiableMap(copy);
    }

    public SafePoint getLocation(String id) {
        if (id == null) {
            return null;
        }
        SafePoint sp = locations.get(id);
        if (sp == null) {
            return null;
        }
        return new SafePoint(sp);
    }

    public void setLocation(String id, int x, int y) {
        if (id == null) {
            throw new IllegalArgumentException("Vehicle ID must not be null.");
        }
        SafePoint sp = locations.get(id);
        if (sp == null) {
            throw new NoSuchElementException("Vehicle not found: " + id);
        }
        sp.set(x, y);
    }

    public static void main(String[] args) {
        Map<String, SafePoint> init = new HashMap<>();
        init.put("car-1", new SafePoint(10, 10));
        init.put("car-2", new SafePoint(20, 20));
        PublishingVehicleTracker tracker = new PublishingVehicleTracker(init);

        ExecutorService pool = Executors.newFixedThreadPool(2);

        Runnable writer = new Runnable() {
            @Override
            public void run() {
                Random r = new Random();
                String[] ids = new String[] { "car-1", "car-2" };
                long end = System.currentTimeMillis() + 1500;
                while (System.currentTimeMillis() < end) {
                    String id = ids[r.nextInt(ids.length)];
                    int x = r.nextInt(100);
                    int y = r.nextInt(100);
                    tracker.setLocation(id, x, y);
                    try {
                        Thread.sleep(50);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
                try {
                    tracker.setLocation("non-existent", 0, 0);
                } catch (NoSuchElementException e) {
                    System.out.println(e.getMessage());
                }
            }
        };

        Runnable reader = new Runnable() {
            @Override
            public void run() {
                long end = System.currentTimeMillis() + 1500;
                while (System.currentTimeMillis() < end) {
                    Map<String, SafePoint> snapshot = tracker.getLocations();
                    for (Map.Entry<String, SafePoint> e : snapshot.entrySet()) {
                        int[] xy = e.getValue().get();
                        System.out.println(e.getKey() + ": (" + xy[0] + "," + xy[1] + ")");
                    }
                    try {
                        Thread.sleep(100);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
            }
        };

        pool.submit(writer);
        pool.submit(reader);

        pool.shutdown();
        try {
            pool.awaitTermination(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    static class SafePoint {
        private int x;
        private int y;

        public SafePoint(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public SafePoint(SafePoint p) {
            int[] xy = p.get();
            this.x = xy[0];
            this.y = xy[1];
        }

        public synchronized int[] get() {
            return new int[] { x, y };
        }

        public synchronized void set(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

