interface Element<R> {
    R compute();
}

interface Node<R> {
    R compute();
    List<? extends Node<R>> children();
}

class Processor {
    public static <R> List<R> processSequential(List<? extends Element<R>> elements) {
        List<R> results = new ArrayList<R>(elements.size());
        for (Element<R> e : elements) {
            results.add(e.compute());
        }
        return results;
    }

    public static <R> List<R> processParallel(List<? extends Element<R>> elements, ExecutorService executor) {
        List<Future<?>> futures = new ArrayList<Future<?>>(elements.size());
        List<R> resultList = Collections.synchronizedList(new ArrayList<R>(elements.size()));
        for (final Element<R> e : elements) {
            futures.add(executor.submit(new Runnable() {
                public void run() {
                    R r = e.compute();
                    resultList.add(r);
                }
            }));
        }
        waitAll(futures);
        return resultList;
    }

    public static <R> List<R> traverseSequential(Node<R> root) {
        List<R> results = new ArrayList<R>();
        traverseSequentialRecursive(root, results);
        return results;
    }

    private static <R> void traverseSequentialRecursive(Node<R> node, Collection<R> results) {
        results.add(node.compute());
        for (Node<R> child : node.children()) {
            traverseSequentialRecursive(child, results);
        }
    }

    public static <R> List<R> traverseParallel(Node<R> root, ExecutorService executor) {
        Queue<R> results = new ConcurrentLinkedQueue<R>();
        List<Future<?>> futures = new ArrayList<Future<?>>();
        traverseParallelRecursive(root, executor, results, futures);
        waitAll(futures);
        return new ArrayList<R>(results);
    }

    private static <R> void traverseParallelRecursive(Node<R> node,
                                                      ExecutorService executor,
                                                      Collection<R> results,
                                                      List<Future<?>> futures) {
        futures.add(executor.submit(new Runnable() {
            public void run() {
                R r = node.compute();
                results.add(r);
            }
        }));
        for (Node<R> child : node.children()) {
            traverseParallelRecursive(child, executor, results, futures);
        }
    }

    private static void waitAll(List<? extends Future<?>> futures) {
        for (Future<?> f : futures) {
            try {
                f.get();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            } catch (ExecutionException e) {
                throw new RuntimeException(e.getCause());
            }
        }
    }
}

