class Processor {

    public static <R> List<R> processSequential(List<? extends Element<R>> elements) {
        List<R> results = new ArrayList<>(elements.size());
        for (Element<R> e : elements) {
            results.add(e.compute());
        }
        return results;
    }

    public static <R> List<R> processParallel(List<? extends Element<R>> elements, ExecutorService executor) {
        ConcurrentLinkedQueue<R> results = new ConcurrentLinkedQueue<>();
        List<Future<?>> futures = new ArrayList<>(elements.size());
        for (Element<R> e : elements) {
            futures.add(executor.submit(() -> {
                R r = e.compute();
                results.add(r);
            }));
        }
        for (Future<?> f : futures) {
            try {
                f.get();
            } catch (InterruptedException ie) {
                Thread.currentThread().interrupt();
                break;
            } catch (ExecutionException ee) {
                throw new RuntimeException(ee.getCause());
            }
        }
        return new ArrayList<>(results);
    }

    public static <R> List<R> traverseSequential(Node<R> root) {
        List<R> results = new ArrayList<>();
        traverseSequentialHelper(root, results);
        return results;
    }

    private static <R> void traverseSequentialHelper(Node<R> node, Collection<R> results) {
        results.add(node.compute());
        List<? extends Node<R>> children = node.children();
        if (children != null && !children.isEmpty()) {
            for (Node<R> child : children) {
                traverseSequentialHelper(child, results);
            }
        }
    }

    public static <R> List<R> traverseParallel(Node<R> root, ExecutorService executor) {
        ConcurrentLinkedQueue<R> results = new ConcurrentLinkedQueue<>();
        Phaser phaser = new Phaser(1); // main thread registered
        phaser.register(); // register root task
        executor.execute(makeNodeTask(root, executor, phaser, results));
        int phase = phaser.getPhase();
        phaser.arriveAndDeregister(); // main deregisters and waits for all tasks
        phaser.awaitAdvance(phase);
        return new ArrayList<>(results);
    }

    private static <R> Runnable makeNodeTask(final Node<R> node,
                                             final ExecutorService executor,
                                             final Phaser phaser,
                                             final ConcurrentLinkedQueue<R> results) {
        return new Runnable() {
            @Override
            public void run() {
                try {
                    R r = node.compute();
                    results.add(r);
                    List<? extends Node<R>> children = node.children();
                    if (children != null && !children.isEmpty()) {
                        for (Node<R> child : children) {
                            phaser.register();
                            executor.execute(makeNodeTask(child, executor, phaser, results));
                        }
                    }
                } finally {
                    phaser.arriveAndDeregister();
                }
            }
        };
    }
}

