        traverseSequentialRec(root, results);
        return results;
    }

    private static <R> void traverseSequentialRec(Node<R> node, List<R> results) {
        results.add(node.compute());
        List<? extends Node<R>> children = node.children();
        if (children != null && !children.isEmpty()) {
            for (Node<R> child : children) {
                traverseSequentialRec(child, results);
            }
        }
    }

    public static <R> List<R> traverseParallel(Node<R> root, ExecutorService executor) throws InterruptedException {
        Queue<R> results = new ConcurrentLinkedQueue<>();
        AtomicInteger pending = new AtomicInteger(1);
        CountDownLatch done = new CountDownLatch(1);
        submitNode(root, executor, results, pending, done);
        done.await();
        return new ArrayList<>(results);
    }

    private static <R> void submitNode(Node<R> node,
                                       ExecutorService executor,
                                       Queue<R> results,
                                       AtomicInteger pending,
                                       CountDownLatch done) {
        Runnable task = new Runnable() {
            @Override
            public void run() {
                try {
                    results.add(node.compute());
                    List<? extends Node<R>> children = node.children();
                    if (children != null && !children.isEmpty()) {
                        for (Node<R> child : children) {
                            pending.incrementAndGet();
                            executor.execute(new Runnable() {
                                @Override
                                public void run() {
                                    submitNode(child, executor, results, pending, done);
                                }
                            });
                        }
                    }
                } finally {
                    if (pending.decrementAndGet() == 0) {
                        done.countDown();
                    }
                }
            }
        };
        task.run();
    }
}

