import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock rwLock = new ReentrantReadWriteLock();
    private final Lock readLock = rwLock.readLock();
    private final Lock writeLock = rwLock.writeLock();

    public ReadWriteMap(Map<K, V> backing) {
        if (backing == null) {
            throw new NullPointerException("Backing map must not be null");
        }
        this.map = backing;
    }

    public V put(K key, V value) {
        writeLock.lock();
        try {
            return map.put(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public V remove(Object key) {
        writeLock.lock();
        try {
            return map.remove(key);
        } finally {
            writeLock.unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        writeLock.lock();
        try {
            map.putAll(m);
        } finally {
            writeLock.unlock();
        }
    }

    public void clear() {
        writeLock.lock();
        try {
            map.clear();
        } finally {
            writeLock.unlock();
        }
    }

    public V get(Object key) {
        readLock.lock();
        try {
            return map.get(key);
        } finally {
            readLock.unlock();
        }
    }

    public int size() {
        readLock.lock();
        try {
            return map.size();
        } finally {
            readLock.unlock();
        }
    }

    public boolean isEmpty() {
        readLock.lock();
        try {
            return map.isEmpty();
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsKey(Object key) {
        readLock.lock();
        try {
            return map.containsKey(key);
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsValue(Object value) {
        readLock.lock();
        try {
            return map.containsValue(value);
        } finally {
            readLock.unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ReadWriteMap<String, Integer> rwMap = new ReadWriteMap<>(new HashMap<String, Integer>());
        ExecutorService pool = Executors.newFixedThreadPool(3);
        CountDownLatch start = new CountDownLatch(1);

        Runnable writer = () -> {
            try {
                start.await();
                for (int i = 1; i <= 50; i++) {
                    rwMap.put("k" + i, i);
                    if (i % 10 == 0) {
                        rwMap.remove("k" + (i - 5));
                    }
                    if (i % 15 == 0) {
                        Map<String, Integer> batch = new HashMap<>();
                        batch.put("batch" + i, i * 100);
                        rwMap.putAll(batch);
                    }
                    Thread.sleep(4);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable reader1 = () -> {
            try {
                start.await();
                for (int i = 0; i < 70; i++) {
                    String key = "k" + ThreadLocalRandom.current().nextInt(1, 51);
                    rwMap.get(key);
                    rwMap.containsKey(key);
                    rwMap.size();
                    Thread.sleep(3);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable reader2 = () -> {
            try {
                start.await();
                for (int i = 0; i < 70; i++) {
                    String key = i % 2 == 0 ? "batch15" : "k" + ThreadLocalRandom.current().nextInt(1, 51);
                    rwMap.containsValue(rwMap.get(key));
                    rwMap.isEmpty();
                    Thread.sleep(3);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        pool.submit(writer);
        pool.submit(reader1);
        pool.submit(reader2);

        start.countDown();
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);

        System.out.println("Final size: " + rwMap.size());
        System.out.println("Contains k10: " + rwMap.containsKey("k10"));
        System.out.println("Value for k50: " + rwMap.get("k50"));
        System.out.println("Contains batch15: " + rwMap.containsKey("batch15"));
        rwMap.clear();
        System.out.println("Cleared map. Is empty: " + rwMap.isEmpty());
    }
}

import java.util.Map;
import java.util.HashMap;
import java.util.Objects;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.Future;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class Main {
    public static void main(String[] args) throws Exception {
        ReadWriteMap<Integer, String> rwMap = new ReadWriteMap<>(new HashMap<Integer, String>());

        ExecutorService pool = Executors.newFixedThreadPool(3);

        Callable<String> writer = new Callable<String>() {
            @Override
            public String call() throws Exception {
                Map<Integer, String> initial = new HashMap<Integer, String>();
                for (int i = 0; i < 10; i++) {
                    initial.put(i, "init-" + i);
                }
                rwMap.putAll(initial);
                Thread.sleep(50);
                for (int i = 10; i < 20; i++) {
                    rwMap.put(i, "val-" + i);
                    Thread.sleep(10);
                }
                String removed = rwMap.remove(5);
                boolean containsAfterRemove = rwMap.containsKey(5);
                int sizeBeforeClear = rwMap.size();
                Thread.sleep(20);
                rwMap.clear();
                return "writer:removed=" + removed + ",containsAfterRemove=" + containsAfterRemove + ",sizeBeforeClear=" + sizeBeforeClear + ",isEmptyAfterClear=" + rwMap.isEmpty();
            }
        };

        Callable<String> reader1 = new Callable<String>() {
            @Override
            public String call() throws Exception {
                int hits = 0;
                for (int i = 0; i < 50; i++) {
                    if (rwMap.containsValue("val-15")) {
                        hits++;
                    }
                    rwMap.get(i % 20);
                    rwMap.isEmpty();
                    Thread.sleep(5);
                }
                return "reader1:hits=" + hits + ",finalSize=" + rwMap.size();
            }
        };

        Callable<String> reader2 = new Callable<String>() {
            @Override
            public String call() throws Exception {
                int checks = 0;
                int sizeAccum = 0;
                for (int i = 0; i < 50; i++) {
                    if (rwMap.containsKey(i % 20)) {
                        checks++;
                    }
                    sizeAccum += rwMap.size();
                    Thread.sleep(5);
                }
                return "reader2:containsChecks=" + checks + ",sizeAccum=" + sizeAccum + ",finalEmpty=" + rwMap.isEmpty();
            }
        };

        List<Future<String>> results = pool.invokeAll(Arrays.asList(writer, reader1, reader2));
        for (Future<String> f : results) {
            System.out.println(f.get());
        }

        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);
    }
}

class ReadWriteMap<K, V> {
    private final Map<K, V> delegate;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> map) {
        this.delegate = Objects.requireNonNull(map);
    }

    public V put(K key, V value) {
        ReentrantReadWriteLock.WriteLock wl = lock.writeLock();
        wl.lock();
        try {
            return delegate.put(key, value);
        } finally {
            wl.unlock();
        }
    }

    public V remove(Object key) {
        ReentrantReadWriteLock.WriteLock wl = lock.writeLock();
        wl.lock();
        try {
            return delegate.remove(key);
        } finally {
            wl.unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        ReentrantReadWriteLock.WriteLock wl = lock.writeLock();
        wl.lock();
        try {
            delegate.putAll(m);
        } finally {
            wl.unlock();
        }
    }

    public void clear() {
        ReentrantReadWriteLock.WriteLock wl = lock.writeLock();
        wl.lock();
        try {
            delegate.clear();
        } finally {
            wl.unlock();
        }
    }

    public V get(Object key) {
        ReentrantReadWriteLock.ReadLock rl = lock.readLock();
        rl.lock();
        try {
            return delegate.get(key);
        } finally {
            rl.unlock();
        }
    }

    public int size() {
        ReentrantReadWriteLock.ReadLock rl = lock.readLock();
        rl.lock();
        try {
            return delegate.size();
        } finally {
            rl.unlock();
        }
    }

    public boolean isEmpty() {
        ReentrantReadWriteLock.ReadLock rl = lock.readLock();
        rl.lock();
        try {
            return delegate.isEmpty();
        } finally {
            rl.unlock();
        }
    }

    public boolean containsKey(Object key) {
        ReentrantReadWriteLock.ReadLock rl = lock.readLock();
        rl.lock();
        try {
            return delegate.containsKey(key);
        } finally {
            rl.unlock();
        }
    }

    public boolean containsValue(Object value) {
        ReentrantReadWriteLock.ReadLock rl = lock.readLock();
        rl.lock();
        try {
            return delegate.containsValue(value);
        } finally {
            rl.unlock();
        }
    }
}

import java.util.HashMap;
